    def _calculate_mantle_equilibrium(self, T: float, P: float, depth: float, composition: dict) -> dict:
        """Calculate equilibrium mineral assemblage for mantle conditions"""
        phases = {}
        
        # Determine major phase stability based on P-T-X conditions
        if depth < 50:  # Shallow mantle - spinel/plagioclase stability
            if P < 1.2:  # Plagioclase stability field
                phases = {
                    'olivine': 0.60 * (1 + 0.1 * composition.get('MgO', 37.8) / 40),
                    'orthopyroxene': 0.25,
                    'clinopyroxene': 0.10,
                    'plagioclase': 0.05 * composition.get('Al2O3', 4.45) / 5
                }
            else:  # Spinel stability field
                phases = {
                    'olivine': 0.58,
                    'orthopyroxene': 0.23,
                    'clinopyroxene': 0.12,
                    'spinel': 0.07
                }
        
        elif depth < 200:  # Garnet stability field
            phases = {
                'olivine': 0.55,
                'orthopyroxene': 0.20,
                'clinopyroxene': 0.15,
                'garnet': 0.10
            }
        
        elif depth < 410:  # Deep upper mantle
            phases = {
                'olivine': 0.60,
                'orthopyroxene': 0.25,
                'clinopyroxene': 0.10,
                'garnet': 0.05
            }
        
        elif depth < 520:  # Olivine-wadsleyite transition zone
            # Use phase loop with accurate Clapeyron slope
            transition = self._get_mantle_phase_transitions()['olivine_wadsleyite']
            P_transition = transition['pressure_gpa'] + transition['clapeyron_slope'] * (T - transition['temperature_k']) / 1e9
            
            if P < P_transition - transition['width_gpa']/2:
                # Pure olivine assemblage
                phases = {
                    'olivine': 0.60,
                    'orthopyroxene': 0.25,
                    'clinopyroxene': 0.10,
                    'garnet': 0.05
                }
            elif P > P_transition + transition['width_gpa']/2:
                # Pure wadsleyite assemblage
                phases = {
                    'wadsleyite': 0.60,
                    'orthopyroxene': 0.23,
                    'clinopyroxene': 0.12,
                    'garnet': 0.05
                }
            else:
                # Mixed assemblage in transition
                progress = (P - (P_transition - transition['width_gpa']/2)) / transition['width_gpa']
                phases = {
                    'olivine': 0.60 * (1 - progress),
                    'wadsleyite': 0.60 * progress,
                    'orthopyroxene': 0.24,
                    'clinopyroxene': 0.11,
                    'garnet': 0.05
                }
        
        elif depth < 660:  # Transition zone
            # Wadsleyite + ringwoodite assemblage
            transition = self._get_mantle_phase_transitions()['wadsleyite_ringwoodite']
            P_transition = transition['pressure_gpa'] + transition['clapeyron_slope'] * (T - transition['temperature_k']) / 1e9
            
            if P < P_transition:
                phases = {
                    'wadsleyite': 0.60,
                    'majorite': 0.35,
                    'garnet': 0.05
                }
            else:
                phases = {
                    'ringwoodite': 0.60,
                    'majorite': 0.35,
                    'garnet': 0.05
                }
        
        else:  # Lower mantle
            # Post-spinel assemblage
            phases = {
                'bridgmanite': 0.76,
                'ferropericlase': 0.20,
                'ca_perovskite': 0.04
            }
            
            # Add CF phase at very high pressures
            if P > 40:  # Above ~1000 km depth
                phases['cf_phase'] = 0.02
                phases['bridgmanite'] = 0.74
        
        # Normalize phase fractions
        total = sum(phases.values())
        if total > 0:
            phases = {k: v/total for k, v in phases.items()}
        
        return phases
    
    def _evaluate_metastable_phases(self, T: float, P: float, depth: float, equilibrium_phases: dict) -> dict:
        """Evaluate metastable phase retention due to kinetic effects"""
        metastable = {}
        
        # Common metastable phase scenarios in the mantle
        transitions = self._get_mantle_phase_transitions()
        
        # Metastable olivine in the transition zone
        if 410 < depth < 660:
            ol_wads = transitions['olivine_wadsleyite']
            P_eq = ol_wads['pressure_gpa'] + ol_wads['clapeyron_slope'] * (T - ol_wads['temperature_k']) / 1e9
            
            if P > P_eq and P < P_eq + ol_wads['metastable_overstep']:
                # Calculate kinetic rate for olivine -> wadsleyite
                activation_energy = 400000  # J/mol
                rate = 1e-8 * np.exp(-activation_energy / (8.314 * T))
                
                # Time scale for transformation (geological)
                time_scale = 1e6 * 365 * 24 * 3600  # 1 Myr in seconds
                progress = 1 - np.exp(-rate * time_scale)
                
                if progress < 0.9:  # Incomplete transformation
                    metastable_fraction = 0.1 * (1 - progress)
                    metastable['olivine_metastable'] = metastable_fraction
        
        # Metastable pyroxene phases
        if depth > 400:
            px_maj = transitions['pyroxene_majorite']
            P_eq = px_maj['pressure_gpa'] + px_maj['clapeyron_slope'] * (T - px_maj['temperature_k']) / 1e9
            
            if P > P_eq and 'orthopyroxene' in equilibrium_phases:
                # Some pyroxene may persist metastably
                metastable['pyroxene_metastable'] = 0.05 * equilibrium_phases['orthopyroxene']
        
        return metastable
    
    def _calculate_assemblage_properties(self, phases: dict, T: float, P: float) -> dict:
        """Calculate bulk physical properties of mineral assemblage"""
        
        # Mineral property database (at standard conditions)
        mineral_props = {
            'olivine': {'density': 3300, 'Ks': 129, 'G': 81, 'alpha': 3.0e-5, 'Cp': 82},
            'orthopyroxene': {'density': 3200, 'Ks': 110, 'G': 76, 'alpha': 2.7e-5, 'Cp': 85},
            'clinopyroxene': {'density': 3280, 'Ks': 112, 'G': 68, 'alpha': 2.8e-5, 'Cp': 87},
            'spinel': {'density': 3600, 'Ks': 185, 'G': 115, 'alpha': 2.5e-5, 'Cp': 90},
            'plagioclase': {'density': 2700, 'Ks': 75, 'G': 30, 'alpha': 2.4e-5, 'Cp': 79},
            'garnet': {'density': 3650, 'Ks': 175, 'G': 95, 'alpha': 2.2e-5, 'Cp': 95},
            'wadsleyite': {'density': 3470, 'Ks': 170, 'G': 110, 'alpha': 2.8e-5, 'Cp': 85},
            'ringwoodite': {'density': 3550, 'Ks': 185, 'G': 120, 'alpha': 2.6e-5, 'Cp': 88},
            'majorite': {'density': 3800, 'Ks': 165, 'G': 100, 'alpha': 2.3e-5, 'Cp': 92},
            'bridgmanite': {'density': 4100, 'Ks': 265, 'G': 175, 'alpha': 2.0e-5, 'Cp': 98},
            'ferropericlase': {'density': 3900, 'Ks': 157, 'G': 131, 'alpha': 2.8e-5, 'Cp': 85},
            'ca_perovskite': {'density': 4000, 'Ks': 235, 'G': 155, 'alpha': 2.1e-5, 'Cp': 95}
        }
        
        # Calculate bulk properties using Voigt-Reuss-Hill averaging
        bulk_density = 0
        bulk_Ks = 0  # Bulk modulus
        bulk_G = 0   # Shear modulus
        bulk_alpha = 0  # Thermal expansivity
        bulk_Cp = 0  # Heat capacity
        
        for phase, fraction in phases.items():
            if phase in mineral_props and fraction > 0:
                props = mineral_props[phase]
                
                # Apply P-T corrections to properties
                density_PT = props['density'] * (1 - props['alpha'] * (T - 298.15)) * (1 + 4e-12 * P * 1e9)
                Ks_PT = props['Ks'] * (1 + 4.0 * P / props['Ks']) * (1 - props['alpha'] * (T - 298.15))
                G_PT = props['G'] * (1 + 1.5 * P / props['Ks']) * (1 - 0.5 * props['alpha'] * (T - 298.15))
                
                # Weighted average
                bulk_density += fraction * density_PT
                bulk_Ks += fraction * Ks_PT
                bulk_G += fraction * G_PT
                bulk_alpha += fraction * props['alpha']
                bulk_Cp += fraction * props['Cp']
        
        # Calculate seismic velocities
        if bulk_density > 0:
            Vp = np.sqrt((bulk_Ks * 1e9 + 4/3 * bulk_G * 1e9) / bulk_density)
            Vs = np.sqrt(bulk_G * 1e9 / bulk_density)
        else:
            Vp = Vs = 0
        
        return {
            'density': bulk_density,
            'bulk_modulus': bulk_Ks,
            'shear_modulus': bulk_G,
            'seismic_velocity_p': Vp,
            'seismic_velocity_s': Vs,
            'thermal_expansivity': bulk_alpha,
            'heat_capacity': bulk_Cp
        }
    
    def _initialize_stress_field(self, X: np.ndarray, Y: np.ndarray, Z: np.ndarray, rho: np.ndarray, dip: float) -> dict:
        """Initialize stress tensor field"""
        g = 9.81
        
        stress_tensor = {
            'xx': np.zeros_like(X),
            'yy': np.zeros_like(X), 
            'zz': np.zeros_like(X),
            'xy': np.zeros_like(X),
            'xz': np.zeros_like(X),
            'yz': np.zeros_like(X)
        }
        
        # Lithostatic stress as base
        for i in range(X.shape[0]):
            for j in range(X.shape[1]):
                for k in range(X.shape[2]):
                    depth_m = Z[i, j, k] * 1000
                    lithostatic = rho[i, j, k] * g * depth_m
                    
                    # Principal stresses
                    stress_tensor['xx'][i, j, k] = lithostatic * (1 - 0.3 * np.cos(dip))
                    stress_tensor['yy'][i, j, k] = lithostatic * 0.7
                    stress_tensor['zz'][i, j, k] = lithostatic
                    
                    # Shear stress from slab bending
                    stress_tensor['xz'][i, j, k] = 0.1 * lithostatic * np.sin(dip)
        
        return stress_tensor
    
    def _calculate_strain_rate_field(self, X: np.ndarray, Y: np.ndarray, Z: np.ndarray, convergence_rate: float) -> dict:
        """Calculate strain rate tensor field"""
        # Convert convergence rate to m/s
        v_conv = convergence_rate * 1e-2 / (365.25 * 24 * 3600)
        
        strain_rate = {
            'xx': np.zeros_like(X),
            'yy': np.zeros_like(X),
            'zz': np.zeros_like(X),
            'xy': np.zeros_like(X),
            'xz': np.zeros_like(X),
            'yz': np.zeros_like(X)
        }
        
        # Simple shear model
        for i in range(X.shape[0]):
            for j in range(X.shape[1]):
                for k in range(X.shape[2]):
                    thickness_m = Y[i, j, k] * 1000
                    if abs(thickness_m) > 1e-6:
                        strain_rate['xy'][i, j, k] = v_conv / abs(thickness_m)
                        strain_rate['xz'][i, j, k] = 0.5 * v_conv / abs(thickness_m)
        
        return strain_rate
    
    def _calculate_water_distribution(self, T: np.ndarray, P: np.ndarray, facies: np.ndarray) -> np.ndarray:
        """Calculate water content distribution"""
        water_content = np.zeros_like(T)
        
        # Water content depends on metamorphic facies and P-T conditions
        for i in range(T.shape[0]):
            for j in range(T.shape[1]):
                for k in range(T.shape[2]):
                    f = facies[i, j, k]
                    
                    # Initial water content based on facies
                    if f in [1, 2]:  # Zeolite, prehnite-pumpellyite
                        water_content[i, j, k] = 4.0  # wt%
                    elif f in [3, 5]:  # Greenschist, blueschist
                        water_content[i, j, k] = 2.5
                    elif f in [4, 6]:  # Amphibolite, epidote amphibolite
                        water_content[i, j, k] = 1.5
                    elif f in [7, 8, 9]:  # Granulite, eclogite
                        water_content[i, j, k] = 0.5
                    
                    # Temperature-dependent dehydration
                    temp_c = T[i, j, k] - 273.15
                    if temp_c > 600:
                        water_content[i, j, k] *= 0.3  # Significant dehydration
                    elif temp_c > 400:
                        water_content[i, j, k] *= 0.7  # Moderate dehydration
        
        return water_content
    
    def _calculate_melt_fraction(self, T: np.ndarray, P: np.ndarray, water: np.ndarray) -> np.ndarray:
        """Calculate melt fraction"""
        melt_fraction = np.zeros_like(T)
        
        for i in range(T.shape[0]):
            for j in range(T.shape[1]):
                for k in range(T.shape[2]):
                    temp_c = T[i, j, k] - 273.15
                    press_gpa = P[i, j, k] / 1e9
                    h2o = water[i, j, k]
                    
                    # Wet solidus depression
                    solidus_dry = 1200 + 132 * press_gpa - 5.1 * press_gpa**2
                    solidus_wet = solidus_dry - 1240/(1 + 0.0769 * h2o**(-0.333))
                    
                    if temp_c > solidus_wet:
                        # Simple melt fraction model
                        melt_fraction[i, j, k] = min(0.3, (temp_c - solidus_wet) / 200.0)
        
        return melt_fraction
    
    def _calculate_seismic_velocities(self, rho: np.ndarray, T: np.ndarray, P: np.ndarray, phases: dict) -> dict:
        """Calculate seismic velocities"""
        velocities = {
            'vp': np.zeros_like(rho),
            'vs': np.zeros_like(rho),
            'qp': np.ones_like(rho) * 1000,
            'qs': np.ones_like(rho) * 600
        }
        
        for i in range(rho.shape[0]):
            for j in range(rho.shape[1]):
                for k in range(rho.shape[2]):
                    density = rho[i, j, k]
                    temp = T[i, j, k]
                    press = P[i, j, k]
                    
                    # Aggregate velocities based on phase proportions
                    K_bulk = 0  # Bulk modulus
                    mu_shear = 0  # Shear modulus
                    
                    for phase, fraction in phases.items():
                        if fraction[i, j, k] > 0:
                            # Phase-specific elastic moduli (GPa)
                            if phase == 'olivine':
                                K_phase = 129 - 0.008 * (temp - 273.15) + 0.004 * press/1e9
                                mu_phase = 81 - 0.008 * (temp - 273.15) + 0.0015 * press/1e9
                            elif phase == 'pyroxene':
                                K_phase = 108 - 0.006 * (temp - 273.15) + 0.005 * press/1e9
                                mu_phase = 74 - 0.007 * (temp - 273.15) + 0.002 * press/1e9
                            else:  # Default values
                                K_phase = 120
                                mu_phase = 75
                            
                            K_bulk += K_phase * fraction[i, j, k]
                            mu_shear += mu_phase * fraction[i, j, k]
                    
                    # Calculate velocities
                    K_bulk *= 1e9  # Convert to Pa
                    mu_shear *= 1e9
                    
                    if density > 0:
                        velocities['vp'][i, j, k] = np.sqrt((K_bulk + 4*mu_shear/3) / density)
                        velocities['vs'][i, j, k] = np.sqrt(mu_shear / density)
                    
                    # Temperature-dependent attenuation
                    temp_factor = np.exp(-(temp - 1273) / 200)
                    velocities['qp'][i, j, k] = 1000 * temp_factor
                    velocities['qs'][i, j, k] = 600 * temp_factor
        
        return velocities
    
    def _calculate_thermal_conductivity(self, T: np.ndarray, phases: dict) -> np.ndarray:
        """Calculate thermal conductivity field"""
        k_thermal = np.zeros_like(T)
        
        for i in range(T.shape[0]):
            for j in range(T.shape[1]):
                for k in range(T.shape[2]):
                    temp = T[i, j, k]
                    
                    # Aggregate thermal conductivity
                    k_total = 0
                    for phase, fraction in phases.items():
                        if fraction[i, j, k] > 0:
                            if phase == 'olivine':
                                k_phase = 4.0 * (298/temp)**0.5  # W/m/K
                            elif phase == 'pyroxene':
                                k_phase = 3.5 * (298/temp)**0.5
                            else:
                                k_phase = 3.0 * (298/temp)**0.5
                            
                            k_total += k_phase * fraction[i, j, k]
                    
                    k_thermal[i, j, k] = max(k_total, 1.5)  # Minimum value
        
        return k_thermal
    
    def _calculate_thermal_diffusivity(self, T: np.ndarray, rho: np.ndarray, phases: dict) -> np.ndarray:
        """Calculate thermal diffusivity field"""
        diffusivity = np.zeros_like(T)
        
        # Get thermal conductivity
        k_thermal = self._calculate_thermal_conductivity(T, phases)
        heat_capacity = self._calculate_heat_capacity(T, phases)
        
        for i in range(T.shape[0]):
            for j in range(T.shape[1]):
                for k in range(T.shape[2]):
                    if rho[i, j, k] > 0 and heat_capacity[i, j, k] > 0:
                        diffusivity[i, j, k] = k_thermal[i, j, k] / (rho[i, j, k] * heat_capacity[i, j, k])
        
        return diffusivity
    
    def _calculate_heat_capacity(self, T: np.ndarray, phases: dict) -> np.ndarray:
        """Calculate specific heat capacity field"""
        cp = np.zeros_like(T)
        
        for i in range(T.shape[0]):
            for j in range(T.shape[1]):
                for k in range(T.shape[2]):
                    temp = T[i, j, k]
                    
                    # Aggregate heat capacity
                    cp_total = 0
                    for phase, fraction in phases.items():
                        if fraction[i, j, k] > 0:
                            # Maier-Kelley equation: Cp = a + bT + cT^-2
                            if phase == 'olivine':
                                cp_phase = 238.6 + 0.0356 * temp - 71.4e5 / temp**2
                            elif phase == 'pyroxene':
                                cp_phase = 272.3 + 0.0542 * temp - 84.1e5 / temp**2
                            else:
                                cp_phase = 250 + 0.04 * temp - 75e5 / temp**2
                            
                            cp_total += cp_phase * fraction[i, j, k]
                    
                    cp[i, j, k] = max(cp_total, 800)  # J/kg/K minimum value
        
        return cp
    
    def _calculate_elastic_moduli(self, rho: np.ndarray, T: np.ndarray, P: np.ndarray) -> dict:
        """Calculate elastic moduli tensors"""
        moduli = {
            'bulk_modulus': np.zeros_like(rho),
            'shear_modulus': np.zeros_like(rho),
            'youngs_modulus': np.zeros_like(rho),
            'poisson_ratio': np.zeros_like(rho)
        }
        
        for i in range(rho.shape[0]):
            for j in range(rho.shape[1]):
                for k in range(rho.shape[2]):
                    temp = T[i, j, k]
                    press = P[i, j, k]
                    
                    # Temperature and pressure derivatives
                    dK_dT = -0.015  # GPa/K
                    dK_dP = 4.0  # dimensionless
                    dmu_dT = -0.012  # GPa/K
                    dmu_dP = 1.8  # dimensionless
                    
                    # Reference values at 298 K, 1 bar
                    K0 = 129  # GPa
                    mu0 = 81  # GPa
                    
                    K = K0 + dK_dT * (temp - 298) + dK_dP * press/1e9
                    mu = mu0 + dmu_dT * (temp - 298) + dmu_dP * press/1e9
                    
                    moduli['bulk_modulus'][i, j, k] = K * 1e9  # Pa
                    moduli['shear_modulus'][i, j, k] = mu * 1e9  # Pa
                    
                    # Derived moduli
                    E = 9 * K * mu / (3 * K + mu)  # Young's modulus
                    nu = (3 * K - 2 * mu) / (6 * K + 2 * mu)  # Poisson's ratio
                    
                    moduli['youngs_modulus'][i, j, k] = E * 1e9  # Pa
                    moduli['poisson_ratio'][i, j, k] = nu
        
        return moduli
    
    def _calculate_seismic_anisotropy(self, strain_rate: dict, phases: dict, T: np.ndarray, P: np.ndarray, 
                                    strain_history: dict = None) -> dict:
        """Advanced seismic anisotropy calculation using lattice preferred orientation modeling
        
        Implements comprehensive crystal physics approach including:
        - Detailed elastic tensor calculations for all major mantle phases
        - Lattice preferred orientation (LPO) development from deformation mechanisms
        - Multi-phase anisotropy averaging using various homogenization schemes
        - Temperature and pressure effects on elastic properties
        - Strain rate and stress regime dependent fabric evolution
        - Metastable phase contributions to anisotropy
        """
        
        # Initialize comprehensive anisotropy arrays
        anisotropy_data = {
            # Velocity anisotropies
            'vp_anisotropy': np.zeros_like(list(strain_rate.values())[0]),
            'vs1_anisotropy': np.zeros_like(list(strain_rate.values())[0]),
            'vs2_anisotropy': np.zeros_like(list(strain_rate.values())[0]),
            'avs': np.zeros_like(list(strain_rate.values())[0]),  # Radial anisotropy
            
            # Directional properties
            'fast_direction_azimuth': np.zeros_like(list(strain_rate.values())[0]),
            'fast_direction_inclination': np.zeros_like(list(strain_rate.values())[0]),
            'slow_direction_azimuth': np.zeros_like(list(strain_rate.values())[0]),
            'slow_direction_inclination': np.zeros_like(list(strain_rate.values())[0]),
            
            # Full elastic tensor components (21 independent elements for anisotropic media)
            'c11': np.zeros_like(list(strain_rate.values())[0]),
            'c12': np.zeros_like(list(strain_rate.values())[0]),
            'c13': np.zeros_like(list(strain_rate.values())[0]),
            'c14': np.zeros_like(list(strain_rate.values())[0]),
            'c15': np.zeros_like(list(strain_rate.values())[0]),
            'c16': np.zeros_like(list(strain_rate.values())[0]),
            'c22': np.zeros_like(list(strain_rate.values())[0]),
            'c23': np.zeros_like(list(strain_rate.values())[0]),
            'c24': np.zeros_like(list(strain_rate.values())[0]),
            'c25': np.zeros_like(list(strain_rate.values())[0]),
            'c26': np.zeros_like(list(strain_rate.values())[0]),
            'c33': np.zeros_like(list(strain_rate.values())[0]),
            'c34': np.zeros_like(list(strain_rate.values())[0]),
            'c35': np.zeros_like(list(strain_rate.values())[0]),
            'c36': np.zeros_like(list(strain_rate.values())[0]),
            'c44': np.zeros_like(list(strain_rate.values())[0]),
            'c45': np.zeros_like(list(strain_rate.values())[0]),
            'c46': np.zeros_like(list(strain_rate.values())[0]),
            'c55': np.zeros_like(list(strain_rate.values())[0]),
            'c56': np.zeros_like(list(strain_rate.values())[0]),
            'c66': np.zeros_like(list(strain_rate.values())[0]),
            
            # LPO strength parameters
            'j_index': np.zeros_like(list(strain_rate.values())[0]),  # J-index fabric strength
            'm_index': np.zeros_like(list(strain_rate.values())[0]),  # M-index fabric strength
            'ba_index': np.zeros_like(list(strain_rate.values())[0]), # BA-index fabric strength
            
            # Deformation mechanism indicators
            'dominant_mechanism': np.empty_like(list(strain_rate.values())[0], dtype=object),
            'mechanism_fractions': np.empty_like(list(strain_rate.values())[0], dtype=object)
        }
        
        # Load mineral elastic tensor database
        elastic_database = self._load_elastic_tensor_database()
        
        # Calculate strain tensor components
        strain_tensor = self._calculate_strain_tensor(strain_rate)
        
        # Get crystallographic orientation distributions for each phase
        lpo_data = self._calculate_lpo_evolution(strain_tensor, phases, T, P, strain_history)
        
        # Calculate anisotropy for each grid point
        shape = list(strain_rate.values())[0].shape
        for i in range(shape[0]):
            for j in range(shape[1]):
                for k in range(shape[2]):
                    
                    # Extract local conditions
                    local_T = T[i, j, k]
                    local_P = P[i, j, k]
                    local_strain = {key: tensor[i, j, k] for key, tensor in strain_tensor.items()}
                    local_phases = {phase: fraction[i, j, k] for phase, fraction in phases.items() if hasattr(fraction, 'shape')}
                    
                    # Skip invalid points
                    if local_T <= 0 or local_P <= 0:
                        continue
                    
                    # Calculate effective elastic tensor for multi-phase aggregate
                    C_eff = self._calculate_effective_elastic_tensor(
                        local_phases, lpo_data, local_T, local_P, i, j, k, elastic_database
                    )
                    
                    # Extract anisotropic properties from elastic tensor
                    aniso_props = self._extract_anisotropic_properties(C_eff, local_phases)
                    
                    # Calculate LPO strength indices
                    lpo_indices = self._calculate_lpo_indices(lpo_data, local_phases, i, j, k)
                    
                    # Store results
                    for prop, value in aniso_props.items():
                        if prop in anisotropy_data:
                            anisotropy_data[prop][i, j, k] = value
                    
                    for index, value in lpo_indices.items():
                        if index in anisotropy_data:
                            anisotropy_data[index][i, j, k] = value
        
        return anisotropy_data
    
