        # Multi-physics coupling parameters
        age_seconds = zone['age'] * 1e6 * 365.25 * 24 * 3600
        convergence_velocity = zone['convergence_rate'] * 1e-2 / (365.25 * 24 * 3600)  # m/s
        slab_thickness_m = zone['slab_thickness'] * 1000  # m
        
