    def _initialize_radioactive_heating(self, geometry: dict) -> np.ndarray:
        """Initialize radioactive heating field"""
        T = geometry['thermal_properties']['temperature']
        Z = geometry['coordinates']['z'] * 1000  # m
        
        # Radioactive isotope concentrations (decay constants in 1/s)
        isotopes = {
            'U238': {'concentration': 0.9e-6, 'decay_constant': 4.916e-18, 'energy': 8.2e-13},  # J/decay
            'U235': {'concentration': 0.063e-6, 'decay_constant': 3.12e-17, 'energy': 7.7e-13},
            'Th232': {'concentration': 3.5e-6, 'decay_constant': 1.563e-18, 'energy': 6.8e-13},
            'K40': {'concentration': 2.8e-4, 'decay_constant': 1.692e-17, 'energy': 2.1e-13}
        }
        
        heating_rate = np.zeros_like(T)
        
        for i in range(T.shape[0]):
            for j in range(T.shape[1]):
                for k in range(T.shape[2]):
                    depth = Z[i, j, k]
                    
                    # Depth-dependent concentration (exponential decay)
                    depth_factor = np.exp(-depth / 5000)  # 5 km e-folding depth
                    
                    heat_rate = 0
                    for isotope, params in isotopes.items():
                        concentration = params['concentration'] * depth_factor
                        heat_rate += concentration * params['decay_constant'] * params['energy']
                    
                    heating_rate[i, j, k] = heat_rate * 2700  # kg/m³ * W/kg = W/m³
        
        return heating_rate
    
    def _initialize_viscous_heating(self, geometry: dict, zone: dict) -> np.ndarray:
        """Initialize viscous dissipation heating"""
        strain_rate = geometry['mechanical_properties']['strain_rate']
        viscosity = geometry['mechanical_properties']['viscosity']
        
        heating_rate = np.zeros_like(viscosity)
        
        # Calculate second invariant of strain rate tensor
        for i in range(heating_rate.shape[0]):
            for j in range(heating_rate.shape[1]):
                for k in range(heating_rate.shape[2]):
                    exx = strain_rate['xx'][i, j, k]
                    eyy = strain_rate['yy'][i, j, k]
                    ezz = strain_rate['zz'][i, j, k]
                    exy = strain_rate['xy'][i, j, k]
                    exz = strain_rate['xz'][i, j, k]
                    eyz = strain_rate['yz'][i, j, k]
                    
                    # Second invariant
                    second_inv = 0.5 * (exx**2 + eyy**2 + ezz**2) + exy**2 + exz**2 + eyz**2
                    
                    # Viscous dissipation: 2 * eta * dot_epsilon_ij^2
                    heating_rate[i, j, k] = 2 * viscosity[i, j, k] * second_inv
        
        return heating_rate
    
    def _initialize_adiabatic_heating(self, geometry: dict, velocity: float) -> np.ndarray:
        """Initialize adiabatic heating/cooling"""
        T = geometry['thermal_properties']['temperature']
        P = geometry['mechanical_properties']['pressure']
        rho = geometry['mechanical_properties']['density']
        
        # Thermal expansion coefficient (temperature dependent)
        alpha = 3e-5 * (1 + 1e-4 * (T - 273.15))
        
        # Adiabatic heating rate: T * alpha * v * grad(P)
        heating_rate = np.zeros_like(T)
        
        # Calculate pressure gradient
        dP_dz = np.gradient(P, axis=2)
        
        for i in range(T.shape[0]):
            for j in range(T.shape[1]):
                for k in range(T.shape[2]):
                    heating_rate[i, j, k] = (T[i, j, k] * alpha[i, j, k] * velocity * 
                                           abs(dP_dz[i, j, k]) / rho[i, j, k])
        
        return heating_rate
    
    def _initialize_reaction_heating_field(self, geometry: dict) -> np.ndarray:
        """Initialize latent heat from metamorphic reactions"""
        T = geometry['thermal_properties']['temperature']
        P = geometry['mechanical_properties']['pressure']
        facies = geometry['petrological_properties']['metamorphic_facies']
        
        heating_rate = np.zeros_like(T)
        
        # Reaction enthalpies (J/mol)
        reactions = {
            'serpentine_dehydration': -178000,
            'chlorite_breakdown': -125000,
            'lawsonite_breakdown': -89000,
            'blueschist_eclogite': -45000,
            'amphibole_breakdown': -156000
        }
        
        for i in range(T.shape[0]):
            for j in range(T.shape[1]):
                for k in range(T.shape[2]):
                    temp_c = T[i, j, k] - 273.15
                    press_gpa = P[i, j, k] / 1e9
                    f = facies[i, j, k]
                    
                    # Determine active reactions based on P-T-facies
                    reaction_rate = 0
                    
                    if f == 5 and 350 < temp_c < 500 and 0.8 < press_gpa < 2.5:  # Blueschist
                        reaction_rate += self._calculate_reaction_rate(T[i, j, k], P[i, j, k], 
                                                                    'serpentine_dehydration')
                    
                    if f == 8 and 500 < temp_c < 700 and press_gpa > 1.5:  # Eclogite
                        reaction_rate += self._calculate_reaction_rate(T[i, j, k], P[i, j, k], 
                                                                    'blueschist_eclogite')
                    
                    heating_rate[i, j, k] = reaction_rate * 1e-12  # W/m³
        
        return heating_rate
    
    def _initialize_frictional_heating(self, geometry: dict, zone: dict) -> np.ndarray:
        """Initialize frictional heating on fault planes"""
        Z = geometry['coordinates']['z'] * 1000  # m
        stress = geometry['mechanical_properties']['stress_tensor']
        
        heating_rate = np.zeros_like(Z)
        
        # Seismogenic zone parameters
        seismogenic_top = 5000  # m
        seismogenic_bottom = 40000  # m
        friction_coefficient = 0.6
        slip_velocity = zone['convergence_rate'] * 1e-2 / (365.25 * 24 * 3600)  # m/s
        
        for i in range(Z.shape[0]):
            for j in range(Z.shape[1]):
                for k in range(Z.shape[2]):
                    depth = Z[i, j, k]
                    
                    if seismogenic_top < depth < seismogenic_bottom:
                        # Effective normal stress
                        normal_stress = stress['zz'][i, j, k] - 0.37 * stress['zz'][i, j, k]  # Pore pressure
                        
                        # Frictional heating: mu * sigma_n * v_slip
                        heating_rate[i, j, k] = (friction_coefficient * normal_stress * 
                                               slip_velocity * 1e-3)  # Scale factor
        
        return heating_rate
    
    def _initialize_serpentine_heating(self, geometry: dict) -> np.ndarray:
        """Initialize serpentine dehydration heating"""
        T = geometry['thermal_properties']['temperature']
        P = geometry['mechanical_properties']['pressure']
        water = geometry['petrological_properties']['water_content']
        
        heating_rate = np.zeros_like(T)
        
        # Serpentine dehydration reaction
        for i in range(T.shape[0]):
            for j in range(T.shape[1]):
                for k in range(T.shape[2]):
                    temp_c = T[i, j, k] - 273.15
                    press_gpa = P[i, j, k] / 1e9
                    h2o = water[i, j, k]
                    
                    # Serpentine stability field
                    if h2o > 10 and 400 < temp_c < 700 and press_gpa > 1.0:
                        # Reaction rate (simplified Arrhenius)
                        activation_energy = 180000  # J/mol
                        pre_exponential = 1e8  # 1/s
                        R = 8.314  # J/mol/K
                        
                        rate = pre_exponential * np.exp(-activation_energy / (R * T[i, j, k]))
                        enthalpy = -178000  # J/mol
                        
                        heating_rate[i, j, k] = rate * enthalpy * 1e-15  # W/m³
        
        return heating_rate
    
    def _initialize_eclogite_heating(self, geometry: dict) -> np.ndarray:
        """Initialize eclogite formation heating"""
        T = geometry['thermal_properties']['temperature']
        P = geometry['mechanical_properties']['pressure']
        facies = geometry['petrological_properties']['metamorphic_facies']
        
        heating_rate = np.zeros_like(T)
        
        for i in range(T.shape[0]):
            for j in range(T.shape[1]):
                for k in range(T.shape[2]):
                    temp_c = T[i, j, k] - 273.15
                    press_gpa = P[i, j, k] / 1e9
                    f = facies[i, j, k]
                    
                    # Eclogite facies transformation
                    if f == 8 and 450 < temp_c < 800 and press_gpa > 1.2:
                        # Plagioclase -> omphacite + garnet transformation
                        rate = 1e6 * np.exp(-200000 / (8.314 * T[i, j, k]))  # 1/s
                        enthalpy = -45000  # J/mol (exothermic)
                        
                        heating_rate[i, j, k] = rate * enthalpy * 1e-15  # W/m³
        
        return heating_rate
    
    def _calculate_reaction_rate(self, T: float, P: float, reaction: str) -> float:
        """Calculate reaction rate using Arrhenius kinetics"""
        R = 8.314  # J/mol/K
        
        kinetic_params = {
            'serpentine_dehydration': {'A': 1e12, 'E': 180000, 'V': -8e-6},
            'blueschist_eclogite': {'A': 1e10, 'E': 250000, 'V': -5e-6},
            'lawsonite_breakdown': {'A': 1e11, 'E': 200000, 'V': -6e-6},
            'chlorite_breakdown': {'A': 1e9, 'E': 220000, 'V': -7e-6}
        }
        
        params = kinetic_params.get(reaction, {'A': 1e10, 'E': 200000, 'V': -6e-6})
        
        # Arrhenius equation with pressure term
        rate = params['A'] * np.exp(-(params['E'] + P * params['V']) / (R * T))
        
        return rate
    
    def _calculate_radiative_heat_transfer(self, T: np.ndarray, geometry: dict) -> dict:
        """Calculate comprehensive radiative heat transfer with spectral and geometric considerations"""
        stefan_boltzmann = 5.67037442e-8  # W/m²/K⁴ (2018 CODATA value)
        
        # Advanced temperature-dependent emissivity model
        emissivity = self._calculate_temperature_dependent_emissivity(T, geometry)
        
        # Surface area calculations for geometric view factors
        surface_areas = self._calculate_surface_areas(geometry)
        view_factors = self._calculate_view_factors(geometry)
        
        # Spectral radiative properties
        spectral_bands = self._define_spectral_bands()
        spectral_emissivity = self._calculate_spectral_emissivity(T, geometry, spectral_bands)
        
        # Net radiative heat transfer with mutual radiation
        net_radiation = np.zeros_like(T)
        
        # Calculate Planck function for each spectral band
        for band_idx, (lambda_min, lambda_max) in enumerate(spectral_bands):
            planck_integral = self._integrate_planck_function(T, lambda_min, lambda_max)
            band_emissivity = spectral_emissivity[:, :, band_idx]
            
            # Band-specific radiative flux
            band_flux = band_emissivity * planck_integral
            net_radiation += band_flux
        
        # Apply view factor corrections for 3D geometry
        corrected_radiation = self._apply_view_factor_corrections(
            net_radiation, view_factors, surface_areas, T
        )
        
        # Atmospheric absorption and re-emission (if applicable)
        if 'atmosphere' in geometry:
            atmospheric_effects = self._calculate_atmospheric_radiation(
                corrected_radiation, T, geometry['atmosphere']
            )
            corrected_radiation += atmospheric_effects
        
        # Surface roughness effects on emissivity
        roughness_factor = self._calculate_roughness_effects(
            geometry.get('surface_roughness', np.ones_like(T))
        )
        corrected_radiation *= roughness_factor
        
        # Convert to volumetric heat source (W/m³)
        characteristic_length = np.cbrt(geometry['volume'] / len(T.flatten()))
        volumetric_radiation = corrected_radiation / characteristic_length
        
        return {
            'total_flux': corrected_radiation,
            'volumetric_source': volumetric_radiation,
            'spectral_breakdown': spectral_emissivity,
            'view_factors': view_factors,
            'effective_emissivity': emissivity,
            'planck_temperature': T
        }
    
    def _initialize_fluid_flow(self, geometry: dict, zone: dict) -> dict:
        """Initialize comprehensive 3D fluid flow field with Navier-Stokes solver"""
        coords = geometry['coordinates']
        shape = coords['x'].shape
        
        # Physical parameters
        convergence_velocity = zone['convergence_rate'] * 1e-2 / (365.25 * 24 * 3600)  # m/s
        temperature = geometry['thermal_properties']['temperature']
        pressure = geometry['mechanical_properties']['pressure']
        
        # Temperature and pressure dependent fluid properties
        fluid_props = self._calculate_fluid_properties(temperature, pressure, zone)
        
        # Initialize pressure and velocity fields
        velocity_field = self._solve_navier_stokes_initialization(
            geometry, zone, fluid_props, convergence_velocity
        )
        
        # Add geophysical forcing terms
        buoyancy_force = self._calculate_buoyancy_forces(
            temperature, pressure, fluid_props['density'], geometry
        )
        
        coriolis_force = self._calculate_coriolis_effects(
            velocity_field, geometry['latitude'], geometry['longitude']
        )
        
        # Pressure gradient from tectonic stress
        tectonic_pressure_gradient = self._calculate_tectonic_pressure_gradient(
            zone, geometry, convergence_velocity
        )
        
        # Viscous stress tensor components
        viscous_stress = self._calculate_viscous_stress_tensor(
            velocity_field, fluid_props['dynamic_viscosity'], geometry
        )
        
        # Solve momentum equations with all forcing terms
        final_velocity = self._solve_momentum_equations(
            velocity_field, buoyancy_force, coriolis_force, 
            tectonic_pressure_gradient, viscous_stress, geometry, fluid_props
        )
        
        # Calculate derived flow properties
        vorticity = self._calculate_vorticity(final_velocity, geometry)
        strain_rate = self._calculate_strain_rate_tensor(final_velocity, geometry)
        reynolds_number = self._calculate_reynolds_number(final_velocity, fluid_props, geometry)
        
        # Turbulence modeling for high Reynolds numbers
        if np.max(reynolds_number) > 2300:  # Turbulent threshold
            turbulence_model = self._initialize_turbulence_model(
                final_velocity, reynolds_number, fluid_props, geometry
            )
            final_velocity = self._apply_turbulence_corrections(
                final_velocity, turbulence_model
            )
        
        # Mass conservation check and correction
        final_velocity = self._enforce_mass_conservation(
            final_velocity, fluid_props['density'], geometry
        )
        
        # Boundary condition enforcement
        final_velocity = self._apply_boundary_conditions(
            final_velocity, zone, geometry, convergence_velocity
        )
        
        return {
            'velocity': final_velocity,
            'pressure_field': self._calculate_pressure_field(final_velocity, fluid_props, geometry),
            'vorticity': vorticity,
            'strain_rate': strain_rate,
            'reynolds_number': reynolds_number,
            'fluid_properties': fluid_props,
            'buoyancy_force': buoyancy_force,
            'coriolis_force': coriolis_force,
            'viscous_stress': viscous_stress,
            'mass_flux': self._calculate_mass_flux(final_velocity, fluid_props['density']),
            'energy_flux': self._calculate_energy_flux(final_velocity, temperature, fluid_props),
            'turbulence_intensity': self._calculate_turbulence_intensity(final_velocity) if np.max(reynolds_number) > 2300 else np.zeros_like(final_velocity['vx'])
        }
    
    def _calculate_permeability_field(self, geometry: dict) -> np.ndarray:
        """Calculate permeability field"""
        porosity = geometry['petrological_properties'].get('porosity', 
                                                         np.full_like(geometry['coordinates']['x'], 0.1))
        
        # Kozeny-Carman relation
        permeability = 1e-12 * porosity**3 / (1 - porosity)**2  # m²
        
        return permeability
    
    def _calculate_fluid_conductivity(self, geometry: dict) -> np.ndarray:
        """Calculate fluid thermal conductivity"""
        T = geometry['thermal_properties']['temperature']
        P = geometry['mechanical_properties']['pressure']
        
        # Water thermal conductivity (temperature and pressure dependent)
        k_fluid = 0.6 * (1 + 1e-4 * (T - 273.15)) * (1 + 1e-10 * P)
        
        return k_fluid
    
    def _initialize_hydrothermal_system(self, geometry: dict) -> dict:
        """Initialize hydrothermal circulation system"""
        T = geometry['thermal_properties']['temperature']
        shape = T.shape
        
        hydrothermal = {
            'circulation_cells': np.zeros(shape),
            'heat_transport_efficiency': np.zeros(shape),
            'fluid_pathways': np.zeros(shape),
            'thermal_springs': []
        }
        
        # Identify hydrothermal circulation zones
        for i in range(shape[0]):
            for j in range(shape[1]):
                for k in range(shape[2]):
                    temp = T[i, j, k]
                    
                    # High temperature gradients indicate circulation
                    if k < shape[2] - 1:
                        temp_gradient = abs(T[i, j, k+1] - temp)
                        if temp_gradient > 50:  # K gradient threshold
                            hydrothermal['circulation_cells'][i, j, k] = 1.0
                            hydrothermal['heat_transport_efficiency'][i, j, k] = min(temp_gradient / 100, 1.0)
        
        return hydrothermal
    
    def _initialize_vapor_transport(self, geometry: dict) -> dict:
        """Initialize vapor transport system"""
        T = geometry['thermal_properties']['temperature']
        P = geometry['mechanical_properties']['pressure']
        water = geometry['petrological_properties']['water_content']
        
        vapor_transport = {
            'vapor_pressure': np.zeros_like(T),
            'vapor_flux': np.zeros_like(T),
            'condensation_rate': np.zeros_like(T),
            'evaporation_rate': np.zeros_like(T)
        }
        
        # Calculate vapor pressure (Antoine equation for water)
        for i in range(T.shape[0]):
            for j in range(T.shape[1]):
                for k in range(T.shape[2]):
                    temp_c = T[i, j, k] - 273.15
                    
                    if temp_c > 0:
                        # Antoine equation constants for water
                        A, B, C = 8.07131, 1730.63, 233.426
                        log_p = A - B / (temp_c + C)
                        vapor_p = 10**log_p * 133.322  # Convert mmHg to Pa
                        
                        vapor_transport['vapor_pressure'][i, j, k] = vapor_p
                        
                        # Vapor flux proportional to water content and vapor pressure
                        vapor_transport['vapor_flux'][i, j, k] = water[i, j, k] * vapor_p * 1e-15
        
        return vapor_transport
    
    def _calculate_surface_temperature(self, geometry: dict, zone: dict) -> np.ndarray:
        """Calculate surface temperature boundary condition"""
        X = geometry['coordinates']['x']
        Y = geometry['coordinates']['y']
        
        # Surface temperature varies with location
        surface_temp = 273.15 + 15 * np.ones_like(X)  # Base 15°C
        
        # Add spatial variations
        surface_temp += 10 * np.sin(X / 100000)  # ±10°C variation over 100 km
        
        return surface_temp
    
    def _calculate_bottom_temperature(self, geometry: dict, zone: dict, time: float = 0) -> dict:
        """Advanced bottom temperature boundary condition using comprehensive mantle thermal structure
        
        Implements sophisticated thermal modeling including:
        - Thermodynamically consistent mantle adiabat with phase transitions
        - Thermal boundary layer development and dynamics
        - Compositional effects on thermal structure
        - Temporal evolution of thermal conditions
        - Regional mantle temperature variations
        """
        
        X = geometry['coordinates']['x']
        Y = geometry['coordinates']['y'] 
        Z = geometry['coordinates']['z']
        P = zone.get('pressure', np.zeros_like(Z))
        
        # Get mantle composition and properties
        mantle_composition = zone.get('mantle_composition', self._get_default_mantle_composition())
        
        # Calculate thermodynamically consistent mantle adiabat
        adiabat_data = self._calculate_mantle_adiabat(Z, P, mantle_composition, time)
        
        # Calculate thermal boundary layer effects
        boundary_layer_data = self._calculate_thermal_boundary_layer(X, Y, Z, zone, time)
        
        # Regional mantle temperature variations
        regional_variations = self._calculate_regional_thermal_variations(X, Y, Z, zone, time)
        
        # Temporal thermal evolution
        temporal_evolution = self._calculate_temporal_thermal_evolution(Z, time)
        
        # Combine all thermal contributions
        bottom_temperature = (adiabat_data['temperature'] + 
                            boundary_layer_data['temperature_perturbation'] +
                            regional_variations['temperature_anomaly'] +
                            temporal_evolution['temperature_change'])
        
        return {
            'temperature': bottom_temperature,
            'adiabat_data': adiabat_data,
            'boundary_layer': boundary_layer_data,
            'regional_variations': regional_variations,
            'temporal_evolution': temporal_evolution,
            'heat_flux': adiabat_data['heat_flux'] + boundary_layer_data['additional_heat_flux']
        }
    
    def _calculate_mantle_adiabat(self, Z: np.ndarray, P: np.ndarray, composition: dict, time: float) -> dict:
        """Calculate thermodynamically consistent mantle adiabat with phase transitions"""
        
        # Reference conditions
        T0 = 1600  # K - potential temperature
        P0 = 1e5   # Pa - surface pressure
        
        # Initialize arrays
        T_adiabat = np.zeros_like(Z)
        heat_capacity = np.zeros_like(Z)
        thermal_expansivity = np.zeros_like(Z)
        gruneisen_parameter = np.zeros_like(Z)
        
        # Calculate adiabat using thermodynamic integration
        for i in range(Z.shape[0]):
            for j in range(Z.shape[1]):
                for k in range(Z.shape[2]):
                    depth = Z[i, j, k]
                    pressure = P[i, j, k] if P.size > 1 else self._pressure_from_depth(depth)
                    
                    # Get local phase assemblage for thermal properties
                    phases = self._get_mantle_phases_at_depth(depth, pressure, composition)
                    
                    # Calculate depth-dependent thermal properties
                    Cp = self._calculate_heat_capacity(phases, pressure, T0)
                    alpha = self._calculate_thermal_expansivity(phases, pressure, T0)
                    gamma = self._calculate_gruneisen_parameter(phases, pressure, T0)
                    
                    # Thermodynamic adiabatic gradient: dT/dP = (α*T)/(ρ*Cp)
                    density = self._calculate_density(phases, pressure, T0)
                    adiabatic_gradient = (alpha * T0) / (density * Cp)
                    
                    # Integrate adiabat with phase transition effects
                    T_adiabat[i, j, k] = self._integrate_adiabat_with_transitions(
                        T0, P0, pressure, adiabatic_gradient, depth, phases
                    )
                    
                    heat_capacity[i, j, k] = Cp
                    thermal_expansivity[i, j, k] = alpha
                    gruneisen_parameter[i, j, k] = gamma
        
        # Calculate heat flux from adiabatic temperature gradient
        thermal_conductivity = self._calculate_thermal_conductivity(Z, P, T_adiabat)
        heat_flux = -thermal_conductivity * np.gradient(T_adiabat, Z, axis=2)
        
        return {
            'temperature': T_adiabat,
            'heat_capacity': heat_capacity,
            'thermal_expansivity': thermal_expansivity,
            'gruneisen_parameter': gruneisen_parameter,
            'heat_flux': heat_flux,
            'thermal_conductivity': thermal_conductivity
        }
    
    def _calculate_thermal_boundary_layer(self, X: np.ndarray, Y: np.ndarray, Z: np.ndarray, 
                                        zone: dict, time: float) -> dict:
        """Calculate thermal boundary layer development and dynamics"""
        
        # Boundary layer parameters
        velocity_field = zone.get('velocity', np.zeros((*X.shape, 3)))
        viscosity = zone.get('viscosity', np.full_like(X, 1e21))
        
        # Calculate boundary layer thickness
        delta_thermal = self._calculate_boundary_layer_thickness(velocity_field, viscosity, time)
        
        # Temperature perturbation from boundary layer
        temp_perturbation = np.zeros_like(X)
        additional_heat_flux = np.zeros_like(X)
        
        for i in range(X.shape[0]):
            for j in range(X.shape[1]):
                for k in range(X.shape[2]):
                    depth = Z[i, j, k]
                    
                    # Thermal boundary layer profile
                    if depth < delta_thermal[i, j, k]:
                        # Similarity solution for thermal boundary layer
                        eta = depth / delta_thermal[i, j, k]
                        
                        # Temperature profile in boundary layer
                        temp_perturbation[i, j, k] = self._thermal_boundary_layer_profile(eta)
                        
                        # Enhanced heat flux in boundary layer
                        additional_heat_flux[i, j, k] = self._boundary_layer_heat_flux(
                            eta, delta_thermal[i, j, k], velocity_field[i, j, k]
                        )
        
        # Instability analysis
        instability_data = self._analyze_boundary_layer_instabilities(
            temp_perturbation, velocity_field, viscosity
        )
        
        return {
            'temperature_perturbation': temp_perturbation,
            'boundary_layer_thickness': delta_thermal,
            'additional_heat_flux': additional_heat_flux,
            'instability_data': instability_data
        }
    
    def _calculate_lateral_heat_flux(self, geometry: dict, zone: dict, time: float = 0) -> dict:
        """Advanced lateral heat flux calculation with multi-physics coupling
        
        Implements comprehensive heat transfer including:
        - Convective heat transfer from mantle flow
        - Conductive heat transfer through thermal gradients
        - Radiative heat transfer at high temperatures
        - Advective heat transport by fluid flow
        - Thermal-mechanical coupling effects
        """
        
        X = geometry['coordinates']['x']
        Y = geometry['coordinates']['y']
        Z = geometry['coordinates']['z']
        T = geometry['thermal_properties']['temperature']
        
        # Get velocity field and material properties
        velocity = zone.get('velocity', np.zeros((*X.shape, 3)))
        thermal_conductivity = zone.get('thermal_conductivity', np.full_like(X, 3.0))
        density = zone.get('density', np.full_like(X, 3300))
        heat_capacity = zone.get('heat_capacity', np.full_like(X, 1000))
        
        # Calculate different heat transfer components
        conductive_flux = self._calculate_conductive_heat_flux(T, thermal_conductivity, X, Y, Z)
        convective_flux = self._calculate_convective_heat_flux(T, velocity, density, heat_capacity)
        radiative_flux = self._calculate_radiative_heat_flux(T, zone)
        advective_flux = self._calculate_advective_heat_flux(T, velocity, density, heat_capacity)
        
        # Thermal-mechanical coupling effects
        mechanical_coupling = self._calculate_thermal_mechanical_coupling(T, zone, time)
        
        # Total lateral heat flux
        total_flux = (conductive_flux + convective_flux + radiative_flux + 
                     advective_flux + mechanical_coupling['thermal_flux'])
        
        # Boundary effects and corrections
        boundary_corrections = self._apply_lateral_boundary_corrections(total_flux, geometry, zone)
        
        return {
            'total_heat_flux': total_flux + boundary_corrections,
            'conductive_component': conductive_flux,
            'convective_component': convective_flux,
            'radiative_component': radiative_flux,
            'advective_component': advective_flux,
            'mechanical_coupling': mechanical_coupling,
            'boundary_corrections': boundary_corrections
        }
    
    def _calculate_interface_conditions(self, geometry: dict, zone: dict, time: float = 0) -> dict:
        """Advanced slab-mantle interface conditions with multi-physics coupling
        
        Implements comprehensive interface physics including:
        - Non-linear contact mechanics and thermal resistance
        - Phase change effects at interfaces
        - Fluid flow and permeability at contacts
        - Chemical reaction kinetics
        - Dynamic interface evolution
        """
        
        T = geometry['thermal_properties']['temperature']
        P = zone.get('pressure', np.zeros_like(T))
        strain_rate = zone.get('strain_rate', {})
        
        # Calculate contact mechanics
        contact_data = self._calculate_contact_mechanics(T, P, strain_rate)
        
        # Phase change effects at interface
        phase_change_data = self._calculate_interface_phase_changes(T, P, time)
        
        # Fluid flow and permeability
        fluid_data = self._calculate_interface_fluid_flow(T, P, zone)
        
        # Chemical reactions at interface
        chemical_data = self._calculate_interface_chemistry(T, P, time)
        
        # Dynamic heat transfer coefficient
        h_dynamic = self._calculate_dynamic_heat_transfer_coefficient(
            T, contact_data, phase_change_data, fluid_data
        )
        
        # Contact resistance with pressure and temperature dependence
        contact_resistance = self._calculate_contact_resistance(
            T, P, contact_data, phase_change_data
        )
        
        # Interfacial temperature accounting for all effects
        T_interface = self._calculate_interfacial_temperature(
            T, h_dynamic, contact_resistance, phase_change_data, chemical_data
        )
        
        # Heat flux continuity with corrections
        heat_flux_continuity = self._enforce_heat_flux_continuity(
            T_interface, geometry, phase_change_data, chemical_data
        )
        
        return {
            'heat_transfer_coefficient': h_dynamic,
            'contact_resistance': contact_resistance,
            'interfacial_temperature': T_interface,
            'heat_flux_continuity': heat_flux_continuity['continuity_satisfied'],
            'contact_mechanics': contact_data,
            'phase_changes': phase_change_data,
            'fluid_flow': fluid_data,
            'chemical_reactions': chemical_data,
            'interface_evolution': self._calculate_interface_evolution(time, T, P),
            'heat_flux_corrections': heat_flux_continuity['corrections']
        }
    
    def _calculate_thermal_radiation(self, geometry: dict, zone: dict = None) -> dict:
        """Advanced thermal radiation modeling with comprehensive physics
        
        Implements sophisticated radiation transfer including:
        - Spectral radiation properties and opacity effects
        - Multi-band radiation transfer
        - Scattering and absorption by mineral phases
        - View factor calculations for complex geometries
        - Non-gray radiation effects
        """
        
        T = geometry['thermal_properties']['temperature']
        phases = zone.get('mineral_phases', {}) if zone else {}
        
        # Calculate spectral radiation properties
        spectral_data = self._calculate_spectral_radiation_properties(T, phases)
        
        # Multi-band radiation transfer
        radiation_bands = self._calculate_multi_band_radiation(T, spectral_data)
        
        # Opacity and absorption effects
        opacity_data = self._calculate_opacity_effects(T, phases)
        
        # View factor calculations
        view_factors = self._calculate_view_factors(geometry)
        
        # Net radiation heat transfer
        net_radiation = self._calculate_net_radiation_transfer(
            T, spectral_data, radiation_bands, opacity_data, view_factors
        )
        
        # Radiation pressure effects (high temperature)
        radiation_pressure = self._calculate_radiation_pressure(T, spectral_data)
        
        return {
            'net_radiation': net_radiation,
            'spectral_properties': spectral_data,
            'radiation_bands': radiation_bands,
            'opacity_data': opacity_data,
            'view_factors': view_factors,
            'radiation_pressure': radiation_pressure,
            'emissive_power': spectral_data['total_emissive_power']
        }
    
    # Helper methods for advanced thermal calculations
    
    def _get_default_mantle_composition(self) -> dict:
        """Get default mantle composition (pyrolite)"""
        return {
            'SiO2': 45.0, 'Al2O3': 4.45, 'FeO': 8.05, 'MgO': 37.8,
            'CaO': 3.55, 'Na2O': 0.36, 'Cr2O3': 0.38, 'NiO': 0.25
        }
    
    def _pressure_from_depth(self, depth: float) -> float:
        """Calculate pressure from depth using PREM model"""
        g = 9.81  # m/s²
        rho_avg = 3300 + 0.5 * depth / 1000  # Depth-dependent density
        return rho_avg * g * depth
    
    def _get_mantle_phases_at_depth(self, depth: float, pressure: float, composition: dict) -> dict:
        """Get mantle phase assemblage at given depth and pressure"""
        T_ref = 1600  # Reference temperature
        
        if depth < 410000:  # Upper mantle
            return {
                'olivine': 0.6, 'orthopyroxene': 0.25, 
                'clinopyroxene': 0.1, 'garnet': 0.05
            }
        elif depth < 660000:  # Transition zone
            return {
                'wadsleyite': 0.4, 'ringwoodite': 0.2,
                'majorite': 0.35, 'garnet': 0.05
            }
        else:  # Lower mantle
            return {
                'bridgmanite': 0.76, 'ferropericlase': 0.20,
                'ca_perovskite': 0.04
            }
    
    def _calculate_heat_capacity(self, phases: dict, pressure: float, temperature: float) -> float:
        """Calculate heat capacity from phase assemblage"""
        heat_capacities = {
            'olivine': 82, 'orthopyroxene': 85, 'clinopyroxene': 87,
            'garnet': 95, 'wadsleyite': 85, 'ringwoodite': 88,
            'majorite': 92, 'bridgmanite': 98, 'ferropericlase': 85,
            'ca_perovskite': 95
        }
        
        Cp = 0
        for phase, fraction in phases.items():
            if phase in heat_capacities:
                # Temperature dependence: Cp = a + b*T + c*T^-2
                Cp_phase = heat_capacities[phase] * (1 + 1e-4 * (temperature - 298))
                Cp += fraction * Cp_phase
        
        return Cp
    
    def _calculate_thermal_expansivity(self, phases: dict, pressure: float, temperature: float) -> float:
        """Calculate thermal expansivity from phase assemblage"""
        expansivities = {
            'olivine': 3.0e-5, 'orthopyroxene': 2.7e-5, 'clinopyroxene': 2.8e-5,
            'garnet': 2.2e-5, 'wadsleyite': 2.8e-5, 'ringwoodite': 2.6e-5,
            'majorite': 2.3e-5, 'bridgmanite': 2.0e-5, 'ferropericlase': 2.8e-5,
            'ca_perovskite': 2.1e-5
        }
        
        alpha = 0
        for phase, fraction in phases.items():
            if phase in expansivities:
                # Pressure dependence
                alpha_phase = expansivities[phase] * (1 - 1e-11 * pressure)
                alpha += fraction * alpha_phase
        
        return alpha
    
    def _calculate_gruneisen_parameter(self, phases: dict, pressure: float, temperature: float) -> float:
        """Calculate Grüneisen parameter from phase assemblage"""
        gruneisen_values = {
            'olivine': 1.3, 'orthopyroxene': 1.2, 'clinopyroxene': 1.1,
            'garnet': 1.0, 'wadsleyite': 1.4, 'ringwoodite': 1.5,
            'majorite': 1.2, 'bridgmanite': 1.6, 'ferropericlase': 1.5,
            'ca_perovskite': 1.3
        }
        
        gamma = 0
        for phase, fraction in phases.items():
            if phase in gruneisen_values:
                gamma += fraction * gruneisen_values[phase]
        
        return gamma
    
    def _calculate_density(self, phases: dict, pressure: float, temperature: float) -> float:
        """Calculate density from phase assemblage"""
        densities = {
            'olivine': 3355, 'orthopyroxene': 3200, 'clinopyroxene': 3280,
            'garnet': 3565, 'wadsleyite': 3470, 'ringwoodite': 3550,
            'majorite': 3800, 'bridgmanite': 4100, 'ferropericlase': 3900,
            'ca_perovskite': 4000
        }
        
        density = 0
        for phase, fraction in phases.items():
            if phase in densities:
                # P-T corrections
                rho_phase = densities[phase] * (1 + 4e-12 * pressure) * (1 - 3e-5 * (temperature - 298))
                density += fraction * rho_phase
        
        return density
    
    def _integrate_adiabat_with_transitions(self, T0: float, P0: float, P: float, 
                                         dTdP: float, depth: float, phases: dict) -> float:
        """Integrate adiabat accounting for phase transitions"""
        # Simple integration with phase transition corrections
        T_adiabat = T0 + dTdP * (P - P0)
        
        # Phase transition effects
        if 410000 < depth < 420000:  # Olivine-wadsleyite transition
            T_adiabat += 50  # Latent heat effect
        elif 660000 < depth < 670000:  # Ringwoodite-bridgmanite transition
            T_adiabat -= 30  # Negative Clapeyron slope effect
        
        return T_adiabat
    
    def _calculate_thermal_conductivity(self, Z: np.ndarray, P: np.ndarray, T: np.ndarray) -> np.ndarray:
        """Calculate thermal conductivity with P-T dependence"""
        k0 = 3.0  # W/m/K reference conductivity
        
        # Temperature dependence: k ~ T^-1
        # Pressure dependence: k ~ P^0.3
        P_gpa = P / 1e9
        k = k0 * (298 / T) * (1 + 0.1 * P_gpa**0.3)
        
        return k
    
    def _calculate_boundary_layer_thickness(self, velocity: np.ndarray, viscosity: np.ndarray, time: float) -> np.ndarray:
        """Calculate thermal boundary layer thickness"""
        # Typical thermal diffusivity
        kappa = 1e-6  # m²/s
        
        # Boundary layer thickness: δ ~ sqrt(κt) for transient
        # or δ ~ sqrt(κ/u) for steady state
        u_magnitude = np.sqrt(velocity[:,:,:,0]**2 + velocity[:,:,:,1]**2 + velocity[:,:,:,2]**2)
        
        # Use minimum of transient and steady-state thickness
        delta_transient = np.sqrt(kappa * time)
        delta_steady = np.sqrt(kappa / (u_magnitude + 1e-10))
        
        return np.minimum(delta_transient, delta_steady)
    
    def _thermal_boundary_layer_profile(self, eta: float) -> float:
        """Thermal boundary layer temperature profile"""
        # Similarity solution for thermal boundary layer
        return 200 * (1 - np.exp(-3 * eta))  # Temperature perturbation in K
    
    def _boundary_layer_heat_flux(self, eta: float, delta: float, velocity: np.ndarray) -> float:
        """Calculate heat flux in boundary layer"""
        k = 3.0  # Thermal conductivity
        dTdy = 600 / delta * np.exp(-3 * eta)  # Temperature gradient
        return k * dTdy
    
    def _analyze_boundary_layer_instabilities(self, temp_field: np.ndarray, 
                                            velocity_field: np.ndarray, 
                                            viscosity: np.ndarray) -> dict:
        """Analyze thermal boundary layer instabilities"""
        # Rayleigh number calculation
        g = 9.81
        alpha = 3e-5
        kappa = 1e-6
        
        delta_T = np.max(temp_field) - np.min(temp_field)
        Ra = g * alpha * delta_T * np.power(np.mean(temp_field), 3) / (viscosity * kappa)
        
        return {
            'rayleigh_number': Ra,
            'critical_rayleigh': 1708,
            'unstable': Ra > 1708
        }
    
    def _calculate_thermal_boundary_layer(self, geometry: dict, age_seconds: float) -> dict:
        """Calculate thermal boundary layer structure"""
        T = geometry['thermal_properties']['temperature']
        kappa = geometry['thermal_properties']['thermal_diffusivity']
        
        boundary_layer = {
            'thickness': np.sqrt(kappa * age_seconds),
            'temperature_profile': T.copy(),
            'heat_flux': np.gradient(T, axis=2),
            'boundary_layer_edge': np.zeros_like(T)
        }
        
        # Identify boundary layer edge (99% of temperature difference)
        mantle_temp = 1573.15
        surface_temp = 273.15
        
        for i in range(T.shape[0]):
            for j in range(T.shape[1]):
                for k in range(T.shape[2]):
                    if T[i, j, k] > surface_temp + 0.99 * (mantle_temp - surface_temp):
                        boundary_layer['boundary_layer_edge'][i, j, k] = 1.0
        
        return boundary_layer
    
    def _identify_rheological_transitions(self, geometry: dict) -> dict:
        """Identify rheological transitions"""
        T = geometry['thermal_properties']['temperature']
        P = geometry['mechanical_properties']['pressure']
        
        transitions = {
            'brittle_ductile': np.zeros_like(T),
            'dislocation_creep': np.zeros_like(T),
            'diffusion_creep': np.zeros_like(T),
            'mylonite_zones': np.zeros_like(T)
        }
        
        for i in range(T.shape[0]):
            for j in range(T.shape[1]):
                for k in range(T.shape[2]):
                    temp_c = T[i, j, k] - 273.15
                    press_gpa = P[i, j, k] / 1e9
                    
                    # Brittle-ductile transition (temperature-dependent)
                    if temp_c < 300 + 50 * press_gpa:
                        transitions['brittle_ductile'][i, j, k] = 1.0
                    
                    # Dislocation creep regime
                    if temp_c > 800:
                        transitions['dislocation_creep'][i, j, k] = 1.0
                    
                    # Diffusion creep at high P, moderate T
                    if 600 < temp_c < 800 and press_gpa > 2.0:
                        transitions['diffusion_creep'][i, j, k] = 1.0
        
        return transitions
    
    def _detect_thermal_anomalies(self, geometry: dict) -> dict:
        """Detect thermal anomalies"""
        T = geometry['thermal_properties']['temperature']
        
        # Calculate local temperature statistics
        T_mean = np.mean(T)
        T_std = np.std(T)
        
        anomalies = {
            'hot_anomalies': T > (T_mean + 2 * T_std),
            'cold_anomalies': T < (T_mean - 2 * T_std),
            'temperature_inversions': np.zeros_like(T),
            'anomaly_strength': abs(T - T_mean) / T_std
        }
        
        # Detect temperature inversions (temperature increases upward)
        for i in range(T.shape[0]):
            for j in range(T.shape[1]):
                for k in range(1, T.shape[2]):
                    if T[i, j, k] < T[i, j, k-1]:  # Shallower is hotter
                        anomalies['temperature_inversions'][i, j, k] = 1.0
        
        return anomalies
    
    def _calculate_temperature_gradients(self, T: np.ndarray) -> dict:
        """Calculate temperature gradients"""
        gradients = {
            'dT_dx': np.gradient(T, axis=0),
            'dT_dy': np.gradient(T, axis=1),
            'dT_dz': np.gradient(T, axis=2),
            'gradient_magnitude': np.zeros_like(T),
            'gradient_direction': np.zeros((T.shape[0], T.shape[1], T.shape[2], 3))
        }
        
        # Calculate gradient magnitude and direction
        for i in range(T.shape[0]):
            for j in range(T.shape[1]):
                for k in range(T.shape[2]):
                    dx = gradients['dT_dx'][i, j, k]
                    dy = gradients['dT_dy'][i, j, k]
                    dz = gradients['dT_dz'][i, j, k]
                    
                    magnitude = np.sqrt(dx**2 + dy**2 + dz**2)
                    gradients['gradient_magnitude'][i, j, k] = magnitude
                    
                    if magnitude > 1e-10:
                        gradients['gradient_direction'][i, j, k, :] = [dx, dy, dz] / magnitude
        
        return gradients
    
    def _calculate_isotherms(self, T: np.ndarray) -> dict:
        """Calculate isotherms"""
        isotherm_temps = [373, 473, 573, 673, 773, 873, 973, 1073, 1173, 1273, 1373, 1473, 1573]  # K
        
        isotherms = {}
        for temp in isotherm_temps:
            # Find points close to isotherm temperature
            isotherm_mask = abs(T - temp) < 25  # ±25K tolerance
            isotherms[f'{temp}K'] = isotherm_mask
        
        return isotherms
    
