    def _initialize_serpentine_kinetics(self, geometry: dict) -> dict:
        """Initialize serpentine breakdown kinetics"""
        T = geometry['thermal_properties']['temperature']
        P = geometry['mechanical_properties']['pressure']
        
        kinetics = {
            'activation_energy': 180000,  # J/mol
            'pre_exponential': 1e8,  # 1/s
            'pressure_dependence': -8e-6,  # m³/mol
            'reaction_rate': np.zeros_like(T),
            'extent_of_reaction': np.zeros_like(T)
        }
        
        # Calculate initial reaction rates
        R = 8.314
        for i in range(T.shape[0]):
            for j in range(T.shape[1]):
                for k in range(T.shape[2]):
                    temp = T[i, j, k]
                    press = P[i, j, k]
                    
                    rate = kinetics['pre_exponential'] * np.exp(
                        -(kinetics['activation_energy'] + press * kinetics['pressure_dependence']) / (R * temp)
                    )
                    kinetics['reaction_rate'][i, j, k] = rate
        
        return kinetics
    
    def _initialize_blueschist_kinetics(self, geometry: dict) -> dict:
        """Initialize blueschist to eclogite kinetics"""
        T = geometry['thermal_properties']['temperature']
        P = geometry['mechanical_properties']['pressure']
        
        kinetics = {
            'activation_energy': 250000,  # J/mol
            'pre_exponential': 1e10,  # 1/s
            'pressure_dependence': -5e-6,  # m³/mol
            'reaction_rate': np.zeros_like(T),
            'nucleation_rate': np.zeros_like(T),
            'growth_rate': np.zeros_like(T)
        }
        
        R = 8.314
        for i in range(T.shape[0]):
            for j in range(T.shape[1]):
                for k in range(T.shape[2]):
                    temp = T[i, j, k]
                    press = P[i, j, k]
                    
                    # Overall reaction rate
                    rate = kinetics['pre_exponential'] * np.exp(
                        -(kinetics['activation_energy'] + press * kinetics['pressure_dependence']) / (R * temp)
                    )
                    kinetics['reaction_rate'][i, j, k] = rate
                    
                    # Separate nucleation and growth
                    kinetics['nucleation_rate'][i, j, k] = rate * 0.1  # 10% nucleation
                    kinetics['growth_rate'][i, j, k] = rate * 0.9  # 90% growth
        
        return kinetics
    
