    def _initialize_410_transition_kinetics(self, geometry: dict) -> dict:
        """Initialize 410 km phase transition kinetics"""
        T = geometry['thermal_properties']['temperature']
        P = geometry['mechanical_properties']['pressure']
        Z = geometry['coordinates']['z'] * 1000  # m
        
        kinetics = {
            'transition_depth': 410000,  # m
            'clapeyron_slope': -2.0e6,  # Pa/K
            'transition_width': 20000,  # m
            'kinetic_rate': np.zeros_like(T),
            'phase_fraction': np.zeros_like(T)
        }
        
        # Calculate phase transition kinetics
        for i in range(T.shape[0]):
            for j in range(T.shape[1]):
                for k in range(T.shape[2]):
                    depth = Z[i, j, k]
                    temp = T[i, j, k]
                    press = P[i, j, k]
                    
                    # Equilibrium pressure for phase transition
                    P_eq = press + kinetics['clapeyron_slope'] * (temp - 1873)  # Reference T
                    
                    # Phase fraction based on depth relative to equilibrium
                    depth_offset = depth - kinetics['transition_depth']
                    phase_frac = 0.5 * (1 + np.tanh(depth_offset / (kinetics['transition_width'] / 4)))
                    kinetics['phase_fraction'][i, j, k] = phase_frac
        
        return kinetics
    
