    def _build_reaction_matrix(self, geometry: dict) -> np.ndarray:
        """Build comprehensive reaction stoichiometry matrix for metamorphic reactions"""
        
        # Define comprehensive set of metamorphic species
        species = {
            'quartz': 0, 'albite': 1, 'orthoclase': 2, 'anorthite': 3, 'diopside': 4,
            'forsterite': 5, 'fayalite': 6, 'enstatite': 7, 'ferrosilite': 8, 'wollastonite': 9,
            'grossular': 10, 'pyrope': 11, 'almandine': 12, 'spessartine': 13, 'muscovite': 14,
            'biotite': 15, 'chlorite': 16, 'kyanite': 17, 'andalusite': 18, 'sillimanite': 19,
            'staurolite': 20, 'garnet': 21, 'cordierite': 22, 'anthophyllite': 23, 'tremolite': 24,
            'actinolite': 25, 'epidote': 26, 'clinozoisite': 27, 'prehnite': 28, 'pumpellyite': 29
        }
        
        num_species = len(species)
        
        # Define key metamorphic reactions with accurate stoichiometry
        reactions = [
            # Pelitic reactions
            {'name': 'muscovite_breakdown', 'coeffs': {14: -1, 17: 1, 2: 1, 0: 1}},  # Ms = Ky + Kfs + Qz
            {'name': 'biotite_garnet', 'coeffs': {15: -1, 21: 1, 2: 1, 0: 1}},  # Bt = Grt + Kfs + Qz
            {'name': 'staurolite_formation', 'coeffs': {21: 1, 16: 1, 20: -1, 0: -1}},  # Grt + Chl = St + Qz
            {'name': 'cordierite_formation', 'coeffs': {15: -1, 21: -1, 22: 1, 2: 1}},  # Bt + Grt = Crd + Kfs
            {'name': 'al2sio5_transition', 'coeffs': {17: -1, 18: 1}},  # Ky = And
            {'name': 'al2sio5_transition2', 'coeffs': {18: -1, 19: 1}},  # And = Sil
            
            # Mafic reactions
            {'name': 'plagioclase_breakdown', 'coeffs': {3: -1, 27: 1, 0: 1}},  # An = Czo + Qz
            {'name': 'actinolite_formation', 'coeffs': {24: -1, 25: 1, 0: 1}},  # Tr = Act + Qz
            {'name': 'epidote_formation', 'coeffs': {3: 1, 16: 1, 26: -1, 0: -1}},  # An + Chl = Ep + Qz
            {'name': 'hornblende_breakdown', 'coeffs': {25: -1, 11: 1, 3: 1, 0: 1}},  # Act = Prp + An + Qz
            
            # Calc-silicate reactions
            {'name': 'diopside_formation', 'coeffs': {3: 1, 0: 1, 4: -1}},  # An + Qz = Di
            {'name': 'wollastonite_formation', 'coeffs': {0: 1, 9: -1}},  # Qz = Wo (simplified)
            {'name': 'grossular_formation', 'coeffs': {3: 1, 10: -1, 0: 1}},  # An = Gr + Qz
            
            # High-grade reactions
            {'name': 'orthopyroxene_formation', 'coeffs': {15: -1, 0: -1, 7: 1, 2: 1}},  # Bt + Qz = Opx + Kfs
            {'name': 'spinel_formation', 'coeffs': {22: -1, 21: 1, 0: 1}}  # Crd = Grt + Qz (simplified)
        ]
        
        # Build stoichiometry matrix
        num_reactions = len(reactions)
        matrix = np.zeros((num_reactions, num_species))
        
        for i, reaction in enumerate(reactions):
            for species_idx, coeff in reaction['coeffs'].items():
                if species_idx < num_species:
                    matrix[i, species_idx] = coeff
        
        # Apply pressure-temperature dependent modifications
        T = geometry['thermal_properties']['temperature']
        P = geometry['mechanical_properties']['pressure']
        
        # Higher P favors denser phases, modify coefficients accordingly
        pressure_factor = min(2.0, P / 1e9)  # Normalize to GPa
        temperature_factor = min(2.0, T / 1000.0)  # Normalize to K
        
        # Apply thermodynamic weighting based on Gibbs free energy changes
        for i in range(num_reactions):
            # High-pressure reactions get enhanced coefficients
            if 'garnet' in reactions[i]['name'] or 'kyanite' in reactions[i]['name']:
                matrix[i, :] *= (1.0 + 0.3 * pressure_factor)
            
            # High-temperature reactions get enhanced coefficients  
            if 'sillimanite' in reactions[i]['name'] or 'cordierite' in reactions[i]['name']:
                matrix[i, :] *= (1.0 + 0.2 * temperature_factor)
        
        return matrix
    
    def _calculate_equilibrium_constants(self, geometry: dict) -> np.ndarray:
        """Calculate thermodynamically rigorous equilibrium constants"""
        T = geometry['thermal_properties']['temperature']
        P = geometry['mechanical_properties']['pressure']
        
        # Comprehensive thermodynamic data for metamorphic reactions
        # ΔH° (J/mol), ΔS° (J/mol·K), ΔV° (J/bar)
        reaction_data = {
            'muscovite_breakdown': {'dH': 45000, 'dS': 85, 'dV': -0.8},
            'biotite_garnet': {'dH': 38000, 'dS': 72, 'dV': -1.2},
            'staurolite_formation': {'dH': -25000, 'dS': -45, 'dV': -0.5},
            'cordierite_formation': {'dH': 28000, 'dS': 65, 'dV': 0.3},
            'al2sio5_transition': {'dH': 2200, 'dS': 5.8, 'dV': -0.15},
            'al2sio5_transition2': {'dH': 1800, 'dS': 4.2, 'dV': 0.08},
            'plagioclase_breakdown': {'dH': 42000, 'dS': 78, 'dV': -0.9},
            'actinolite_formation': {'dH': -18000, 'dS': -32, 'dV': -0.3},
            'epidote_formation': {'dH': -35000, 'dS': -58, 'dV': -0.7},
            'hornblende_breakdown': {'dH': 55000, 'dS': 95, 'dV': -1.5},
            'diopside_formation': {'dH': -22000, 'dS': -38, 'dV': -0.4},
            'wollastonite_formation': {'dH': 15000, 'dS': 28, 'dV': 0.2},
            'grossular_formation': {'dH': -30000, 'dS': -52, 'dV': -0.6},
            'orthopyroxene_formation': {'dH': 48000, 'dS': 88, 'dV': -0.8},
            'spinel_formation': {'dH': 35000, 'dS': 68, 'dV': -1.0}
        }
        
        R = 8.314  # J/mol·K
        K_eq = np.zeros(len(reaction_data))
        
        for i, (reaction_name, data) in enumerate(reaction_data.items()):
            # Extended Van't Hoff equation including pressure dependence
            # ln(K) = -ΔH°/RT + ΔS°/R - ΔV°(P-P°)/RT
            
            dH = data['dH']  # Enthalpy change
            dS = data['dS']  # Entropy change  
            dV = data['dV']  # Volume change (J/bar)
            
            P_ref = 1.0  # Reference pressure (bar)
            P_bar = P / 1e5  # Convert Pa to bar
            
            # Temperature-dependent enthalpy correction (heat capacity)
            # ΔH(T) = ΔH°298 + ΔCp(T - 298)
            T_ref = 298.15
            dCp = 20.0  # Simplified average heat capacity change
            dH_T = dH + dCp * (T - T_ref)
            
            # Temperature-dependent entropy correction
            # ΔS(T) = ΔS°298 + ΔCp·ln(T/298)
            dS_T = dS + dCp * np.log(T / T_ref)
            
            # Calculate equilibrium constant with full P-T dependence
            ln_K = (-dH_T / (R * T) + 
                   dS_T / R - 
                   dV * (P_bar - P_ref) / (R * T))
            
            K_eq[i] = np.exp(ln_K)
            
            # Apply activity coefficient corrections for non-ideal solutions
            # Using simplified Margules model for solid solutions
            if 'garnet' in reaction_name or 'biotite' in reaction_name:
                # Account for Fe-Mg substitution in garnet/biotite
                X_Fe = 0.6  # Simplified Fe/(Fe+Mg) ratio
                gamma_correction = np.exp(2400 * X_Fe * (1 - X_Fe) / (R * T))
                K_eq[i] *= gamma_correction
        
        return K_eq
    
    def _calculate_reaction_affinities(self, geometry: dict) -> np.ndarray:
        """Calculate comprehensive reaction affinities and driving forces"""
        T = geometry['thermal_properties']['temperature']
        P = geometry['mechanical_properties']['pressure']
        
        # Get equilibrium constants
        K_eq = self._calculate_equilibrium_constants(geometry)
        
        # Calculate activity-based reaction quotients
        # Activities depend on mineral compositions and P-T conditions
        R = 8.314  # J/mol·K
        
        # Model mineral activities using thermodynamic mixing models
        activities = self._calculate_mineral_activities(geometry)
        
        affinities = np.zeros(len(K_eq))
        
        reaction_species = [
            {'products': ['kyanite', 'k-feldspar', 'quartz'], 'reactants': ['muscovite']},
            {'products': ['garnet', 'k-feldspar', 'quartz'], 'reactants': ['biotite']},
            {'products': ['staurolite', 'quartz'], 'reactants': ['garnet', 'chlorite']},
            {'products': ['cordierite', 'k-feldspar'], 'reactants': ['biotite', 'garnet']},
            {'products': ['andalusite'], 'reactants': ['kyanite']},
            {'products': ['sillimanite'], 'reactants': ['andalusite']},
            {'products': ['clinozoisite', 'quartz'], 'reactants': ['anorthite']},
            {'products': ['actinolite', 'quartz'], 'reactants': ['tremolite']},
            {'products': ['epidote', 'quartz'], 'reactants': ['anorthite', 'chlorite']},
            {'products': ['pyrope', 'anorthite', 'quartz'], 'reactants': ['actinolite']},
            {'products': ['diopside'], 'reactants': ['anorthite', 'quartz']},
            {'products': ['wollastonite'], 'reactants': ['quartz']},
            {'products': ['grossular', 'quartz'], 'reactants': ['anorthite']},
            {'products': ['enstatite', 'k-feldspar'], 'reactants': ['biotite', 'quartz']},
            {'products': ['garnet', 'quartz'], 'reactants': ['cordierite']}
        ]
        
        for i, reaction in enumerate(reaction_species):
            # Calculate reaction quotient Q
            Q = 1.0
            
            # Product activities (numerator)
            for product in reaction['products']:
                if product in activities:
                    activity = max(activities[product], 1e-10)  # Avoid log(0)
                    Q *= activity
            
            # Reactant activities (denominator)
            for reactant in reaction['reactants']:
                if reactant in activities:
                    activity = max(activities[reactant], 1e-10)
                    Q /= activity
            
            # Calculate affinity: A = -RT·ln(Q/K)
            # Positive affinity means reaction proceeds forward
            if K_eq[i] > 0 and Q > 0:
                affinities[i] = -R * T * np.log(Q / K_eq[i])
            else:
                affinities[i] = 0.0
            
            # Apply kinetic barriers and surface energy effects
            # Nucleation barrier for new phases
            nucleation_barrier = self._calculate_nucleation_barrier(reaction, T, P)
            surface_energy = self._calculate_surface_energy_contribution(reaction, geometry)
            
            # Net driving force includes thermodynamic affinity and kinetic barriers
            net_affinity = affinities[i] - nucleation_barrier - surface_energy
            affinities[i] = max(net_affinity, 0.0)  # Only forward reactions
            
            # Apply grain size and deformation effects
            grain_size_factor = self._calculate_grain_size_effect(geometry)
            deformation_factor = self._calculate_deformation_effect(geometry)
            
            affinities[i] *= grain_size_factor * deformation_factor
        
        return affinities
    
    def _calculate_mineral_activities(self, geometry: dict) -> dict:
        """Calculate mineral activities using thermodynamic models"""
        T = geometry['thermal_properties']['temperature']
        P = geometry['mechanical_properties']['pressure']
        
        # Initialize activities based on modal mineralogy and composition
        activities = {
            'quartz': 1.0,  # Pure phase
            'k-feldspar': 0.95,  # Nearly pure
            'muscovite': 0.8,   # Solid solution
            'biotite': 0.7,     # Fe-Mg substitution
            'garnet': 0.6,      # Complex solid solution
            'kyanite': 1.0,     # Pure phase
            'andalusite': 1.0,  # Pure phase
            'sillimanite': 1.0, # Pure phase
            'staurolite': 0.85, # Limited solid solution
            'cordierite': 0.75, # Mg-Fe substitution
            'chlorite': 0.65,   # Complex composition
            'anorthite': 0.9,   # Plagioclase solid solution
            'clinozoisite': 0.88,
            'epidote': 0.82,
            'actinolite': 0.7,  # Amphibole solid solution
            'tremolite': 0.75,
            'pyrope': 0.6,      # Garnet end-member
            'diopside': 0.85,   # Pyroxene
            'wollastonite': 0.95,
            'grossular': 0.65,  # Garnet end-member
            'enstatite': 0.8    # Orthopyroxene
        }
        
        # Apply pressure-temperature corrections to activities
        for mineral, base_activity in activities.items():
            # Temperature effect on activity (increased disorder)
            T_effect = np.exp(-1000 / (R * T))  # Simplified
            
            # Pressure effect on activity (compression)
            P_effect = 1.0 + (P - 1e5) / (10 * R * T)  # Linear approximation
            
            activities[mineral] = base_activity * T_effect * P_effect
            activities[mineral] = max(min(activities[mineral], 1.0), 1e-6)
        
        return activities
    
    def _calculate_nucleation_barrier(self, reaction: dict, T: float, P: float) -> float:
        """Calculate nucleation energy barrier for new phases"""
        # Classical nucleation theory: ΔG* = 16πσ³Vm²/3(ΔGv)²
        
        # Typical surface energies (J/m²)
        surface_energies = {
            'garnet': 1.5, 'staurolite': 1.2, 'cordierite': 1.0,
            'kyanite': 1.8, 'sillimanite': 1.6, 'andalusite': 1.4
        }
        
        # Molar volumes (m³/mol)
        molar_volumes = {
            'garnet': 115e-6, 'staurolite': 155e-6, 'cordierite': 233e-6,
            'kyanite': 44e-6, 'sillimanite': 50e-6, 'andalusite': 52e-6
        }
        
        barrier = 0.0
        for product in reaction['products']:
            if product in surface_energies and product in molar_volumes:
                sigma = surface_energies[product]
                Vm = molar_volumes[product]
                
                # Volumetric driving force (simplified)
                dGv = -8.314 * T  # Approximate driving force
                
                if abs(dGv) > 1e-6:
                    nucleation_barrier = (16 * np.pi * sigma**3 * Vm**2) / (3 * dGv**2)
                    barrier += nucleation_barrier / (8.314 * T)  # Normalize
        
        return min(barrier, 50000)  # Cap at reasonable value
    
    def _calculate_surface_energy_contribution(self, reaction: dict, geometry: dict) -> float:
        """Calculate surface energy contribution to reaction energetics"""
        # Surface energy depends on grain size and interface area
        grain_size = geometry.get('grain_size', 1e-3)  # Default 1 mm
        
        # Smaller grains have higher surface energy contribution
        surface_contribution = 1000 / grain_size  # J/mol per m grain size
        
        return surface_contribution
    
    def _calculate_grain_size_effect(self, geometry: dict) -> float:
        """Calculate grain size effect on reaction kinetics"""
        grain_size = geometry.get('grain_size', 1e-3)  # Default 1 mm
        
        # Finer grains enhance reaction rates (more surface area)
        # Effect scales as 1/grain_size
        grain_factor = (1e-3 / grain_size) ** 0.5
        
        return min(max(grain_factor, 0.1), 10.0)  # Reasonable bounds
    
    def _calculate_deformation_effect(self, geometry: dict) -> float:
        """Calculate deformation effect on reaction kinetics"""
        strain_rate = geometry.get('strain_rate', 1e-15)  # Default s⁻¹
        
        # Deformation enhances reaction rates through:
        # - Increased defect density
        # - Enhanced diffusion
        # - Mechanical work
        
        deformation_factor = 1.0 + 100 * strain_rate  # Linear enhancement
        
        return min(deformation_factor, 5.0)  # Cap enhancement
    
    def _initialize_nucleation_kinetics(self, geometry: dict) -> dict:
        """Initialize nucleation kinetics for new phases"""
        T = geometry['thermal_properties']['temperature']
        
        nucleation = {
            'nucleation_rate': np.zeros_like(T),
            'critical_radius': np.zeros_like(T),
            'nucleation_barrier': np.zeros_like(T),
            'interfacial_energy': 0.1,  # J/m²
            'volume_free_energy': np.zeros_like(T)
        }
        
        # Classical nucleation theory
        for i in range(T.shape[0]):
            for j in range(T.shape[1]):
                for k in range(T.shape[2]):
                    temp = T[i, j, k]
                    
                    # Critical radius for nucleation
                    if temp > 0:
                        sigma = nucleation['interfacial_energy']
                        delta_G = -1000  # J/mol (driving force)
                        
                        r_crit = 2 * sigma / abs(delta_G)
                        nucleation['critical_radius'][i, j, k] = r_crit
                        
                        # Nucleation barrier
                        barrier = 16 * np.pi * sigma**3 / (3 * delta_G**2)
                        nucleation['nucleation_barrier'][i, j, k] = barrier
        
        return nucleation
    
    def _initialize_growth_kinetics(self, geometry: dict) -> dict:
        """Initialize crystal growth kinetics"""
        T = geometry['thermal_properties']['temperature']
        
        growth = {
            'growth_rate': np.zeros_like(T),
            'surface_energy': np.zeros_like(T),
            'diffusion_coefficient': np.zeros_like(T),
            'interface_mobility': np.zeros_like(T)
        }
        
        # Growth rate proportional to temperature
        growth['growth_rate'] = 1e-12 * np.exp(-50000 / (8.314 * T))  # m/s
        
        return growth
    
    def _initialize_dissolution_kinetics(self, geometry: dict) -> dict:
        """Initialize dissolution kinetics"""
        T = geometry['thermal_properties']['temperature']
        P = geometry['mechanical_properties']['pressure']
        
        dissolution = {
            'dissolution_rate': np.zeros_like(T),
            'solubility': np.zeros_like(T),
            'surface_area': np.ones_like(T) * 1e-3,  # m²/g
            'activation_energy': 65000  # J/mol
        }
        
        # Temperature-dependent dissolution rate
        R = 8.314
        dissolution['dissolution_rate'] = 1e-10 * np.exp(-dissolution['activation_energy'] / (R * T))
        
        return dissolution
    
