    def _calculate_redox_conditions(self, geometry: dict) -> dict:
        """Calculate redox conditions"""
        T = geometry['thermal_properties']['temperature']
        P = geometry['mechanical_properties']['pressure']
        
        redox = {
            'oxygen_fugacity': np.zeros_like(T),
            'fe3_fe2_ratio': np.zeros_like(T),
            'buffer_assemblage': np.zeros_like(T, dtype=int)
        }
        
        # Calculate oxygen fugacity relative to FMQ buffer
        for i in range(T.shape[0]):
            for j in range(T.shape[1]):
                for k in range(T.shape[2]):
                    temp = T[i, j, k]
                    press_gpa = P[i, j, k] / 1e9
                    
                    # FMQ buffer equation
                    log_fO2_FMQ = -25018.7 / temp + 8.4427 - 0.092 * press_gpa / temp
                    redox['oxygen_fugacity'][i, j, k] = 10**log_fO2_FMQ
        
        return redox
    
