    def _query_nasa_global_geology(self, lat: float, lon: float, nasa_connector) -> Dict:
        """Query NASA global geological datasets"""
        search_bbox = [lon - 1.0, lat - 1.0, lon + 1.0, lat + 1.0]  # 2-degree bounding box
        
        # NASA global geological datasets
        datasets = [
            'NASA_USGS_Global_Geology_Map',
            'NASA_GTOPO30_Geology',
            'NASA_Global_Lithology_Map',
            'NASA_Crustal_Age_Grid'
        ]
        
        geological_data = {}
        for dataset in datasets:
            try:
                data = nasa_connector.query_dataset(
                    dataset_name=dataset,
                    bbox=search_bbox,
                    temporal_range=None,  # Static geological data
                    data_format='GeoTIFF'
                )
                geological_data[dataset] = {
                    'data': data,
                    'metadata': nasa_connector.get_dataset_metadata(dataset),
                    'quality_flags': nasa_connector.get_quality_assessment(dataset, search_bbox)
                }
            except Exception as e:
                geological_data[dataset] = {'error': str(e), 'data': None}
        
        return geological_data
    
    def _query_nasa_crustal_models(self, lat: float, lon: float, nasa_connector) -> Dict:
        """Query NASA crustal structure and geophysical models"""
        search_point = {'lat': lat, 'lon': lon}
        
