    def _calculate_force_ratios(self, forces: Dict) -> Dict:
        """Calculate ratios between different forces"""
        total_driving = forces.get('ridge_push', 0) + forces.get('slab_pull', 0)
        total_resisting = forces.get('basal_drag', 0) + forces.get('transform_resistance', 0)
        
        return {
            'driving_to_resisting': total_driving / (total_resisting + 1e-10),
            'ridge_to_slab': forces.get('ridge_push', 0) / (forces.get('slab_pull', 0) + 1e-10)
        }
    
    def _calculate_system_stability_index(self, forces: Dict) -> float:
        """Calculate system stability index"""
        net_force = sum(forces.values())
        total_magnitude = sum(abs(f) for f in forces.values())
        return 1.0 - abs(net_force) / (total_magnitude + 1e-10)
    
    def _assess_force_prediction_confidence(self, forces: Dict) -> float:
        """Assess comprehensive confidence in force predictions with multi-criteria analysis"""
        try:
            # Multi-component confidence analysis
            data_quality_confidence = self._assess_data_quality_confidence(forces)
            model_consistency_confidence = self._assess_model_consistency_confidence(forces)
            uncertainty_bounds_confidence = self._assess_uncertainty_bounds_confidence(forces)
            physical_plausibility_confidence = self._assess_physical_plausibility_confidence(forces)
            
            # Cross-validation confidence
            cross_validation_confidence = self._assess_cross_validation_confidence(forces)
            
            # Temporal stability confidence
            temporal_stability_confidence = self._assess_temporal_stability_confidence(forces)
            
            # Multi-scale consistency confidence
            multi_scale_confidence = self._assess_multi_scale_consistency_confidence(forces)
            
            # Observational constraint confidence
            observational_confidence = self._assess_observational_constraint_confidence(forces)
            
            # Component-weighted confidence calculation
            confidence_components = {
                'data_quality': data_quality_confidence,
                'model_consistency': model_consistency_confidence,
                'uncertainty_bounds': uncertainty_bounds_confidence,
                'physical_plausibility': physical_plausibility_confidence,
                'cross_validation': cross_validation_confidence,
                'temporal_stability': temporal_stability_confidence,
                'multi_scale': multi_scale_confidence,
                'observational': observational_confidence
            }
            
            # Weighted combination with adaptive weights
            weights = self._calculate_adaptive_confidence_weights(forces, confidence_components)
            
            total_confidence = 0.0
            total_weight = 0.0
            
            for component, confidence in confidence_components.items():
                weight = weights.get(component, 1.0)
                total_confidence += weight * confidence
                total_weight += weight
            
            # Normalize confidence
            if total_weight > 0:
                normalized_confidence = total_confidence / total_weight
            else:
                normalized_confidence = 0.5
            
            # Apply confidence penalties for extreme values
            extreme_penalty = self._calculate_extreme_value_penalty(forces)
            penalized_confidence = normalized_confidence * extreme_penalty
            
            # Apply model complexity penalty
            complexity_penalty = self._calculate_model_complexity_penalty(forces)
            final_confidence = penalized_confidence * complexity_penalty
            
            # Bound confidence between 0 and 1
            final_confidence = np.clip(final_confidence, 0.0, 1.0)
            
            return float(final_confidence)
            
        except Exception as e:
            self.logger.error(f"Error assessing force prediction confidence: {e}")
            return 0.3  # Conservative fallback
    
    def _assess_data_quality_confidence(self, forces: Dict) -> float:
        """Assess confidence based on input data quality"""
        try:
            # Data completeness analysis
            completeness_score = self._calculate_data_completeness_score(forces)
            
            # Data accuracy assessment
            accuracy_score = self._calculate_data_accuracy_score(forces)
            
            # Data consistency analysis
            consistency_score = self._calculate_data_consistency_score(forces)
            
            # Temporal coverage assessment
            temporal_coverage_score = self._calculate_temporal_coverage_score(forces)
            
            # Spatial resolution assessment
            spatial_resolution_score = self._calculate_spatial_resolution_score(forces)
            
            # Composite data quality score
            data_quality_confidence = (
                0.3 * completeness_score +
                0.25 * accuracy_score +
                0.2 * consistency_score +
                0.15 * temporal_coverage_score +
                0.1 * spatial_resolution_score
            )
            
            return np.clip(data_quality_confidence, 0.0, 1.0)
            
        except Exception as e:
            return 0.6
    
    def _assess_model_consistency_confidence(self, forces: Dict) -> float:
        """Assess confidence based on model internal consistency"""
        try:
            # Force balance consistency
            force_balance_score = self._calculate_force_balance_consistency(forces)
            
            # Energy conservation consistency
            energy_conservation_score = self._calculate_energy_conservation_consistency(forces)
            
            # Momentum conservation consistency
            momentum_conservation_score = self._calculate_momentum_conservation_consistency(forces)
            
            # Thermodynamic consistency
            thermodynamic_score = self._calculate_thermodynamic_consistency(forces)
            
            # Rheological consistency
            rheological_score = self._calculate_rheological_consistency(forces)
            
            # Composite model consistency score
            model_consistency_confidence = (
                0.3 * force_balance_score +
                0.25 * energy_conservation_score +
                0.2 * momentum_conservation_score +
                0.15 * thermodynamic_score +
                0.1 * rheological_score
            )
            
            return np.clip(model_consistency_confidence, 0.0, 1.0)
            
        except Exception as e:
            return 0.7
    
    def _assess_uncertainty_bounds_confidence(self, forces: Dict) -> float:
        """Assess confidence based on uncertainty bounds"""
        try:
            # Calculate relative uncertainties
            total_force_magnitude = sum(abs(f) for f in forces.values())
            
            uncertainty_scores = []
            
            for force_name, force_value in forces.items():
                if force_value != 0:
                    # Estimate uncertainty for each force component
                    force_uncertainty = self._estimate_force_uncertainty(force_name, force_value)
                    relative_uncertainty = abs(force_uncertainty) / abs(force_value)
                    
                    # Convert to confidence (lower uncertainty = higher confidence)
                    confidence_score = np.exp(-relative_uncertainty * 2.0)
                    uncertainty_scores.append(confidence_score)
            
            # Weight by force magnitude
            if uncertainty_scores:
                weighted_confidence = np.mean(uncertainty_scores)
            else:
                weighted_confidence = 0.5
            
            return np.clip(weighted_confidence, 0.0, 1.0)
            
        except Exception as e:
            return 0.6
    
    def _assess_physical_plausibility_confidence(self, forces: Dict) -> float:
        """Assess confidence based on physical plausibility"""
        try:
            # Force magnitude plausibility
            magnitude_plausibility = self._assess_force_magnitude_plausibility(forces)
            
            # Force direction plausibility
            direction_plausibility = self._assess_force_direction_plausibility(forces)
            
            # Force ratio plausibility
            ratio_plausibility = self._assess_force_ratio_plausibility(forces)
            
            # Temporal evolution plausibility
            temporal_plausibility = self._assess_temporal_evolution_plausibility(forces)
            
            # Physical constraint satisfaction
            constraint_satisfaction = self._assess_physical_constraint_satisfaction(forces)
            
            # Composite physical plausibility score
            physical_confidence = (
                0.25 * magnitude_plausibility +
                0.2 * direction_plausibility +
                0.2 * ratio_plausibility +
                0.2 * temporal_plausibility +
                0.15 * constraint_satisfaction
            )
            
            return np.clip(physical_confidence, 0.0, 1.0)
            
        except Exception as e:
            return 0.65
    
    def _assess_cross_validation_confidence(self, forces: Dict) -> float:
        """Assess confidence based on cross-validation results"""
        try:
            # K-fold cross-validation simulation
            validation_scores = []
            
            for fold in range(5):  # 5-fold cross-validation
                # Simulate validation by perturbing input parameters
                perturbed_forces = self._perturb_forces_for_validation(forces, fold)
                validation_score = self._calculate_validation_score(forces, perturbed_forces)
                validation_scores.append(validation_score)
            
            # Calculate mean and standard deviation of validation scores
            mean_validation_score = np.mean(validation_scores)
            std_validation_score = np.std(validation_scores)
            
            # Confidence based on validation consistency
            validation_consistency = np.exp(-std_validation_score * 3.0)
            validation_accuracy = mean_validation_score
            
            cross_validation_confidence = 0.6 * validation_accuracy + 0.4 * validation_consistency
            
            return np.clip(cross_validation_confidence, 0.0, 1.0)
            
        except Exception as e:
            return 0.55
    
    def _assess_temporal_stability_confidence(self, forces: Dict) -> float:
        """Assess confidence based on temporal stability"""
        try:
            # Analyze force evolution over multiple time steps
            temporal_variations = []
            
            for force_name, force_value in forces.items():
                # Simulate temporal evolution
                temporal_series = self._simulate_force_temporal_evolution(force_name, force_value)
                
                # Calculate temporal stability metrics
                stability_metric = self._calculate_temporal_stability_metric(temporal_series)
                temporal_variations.append(stability_metric)
            
            # Overall temporal stability
            mean_stability = np.mean(temporal_variations) if temporal_variations else 0.5
            
            # Convert stability to confidence
            temporal_confidence = np.exp(-mean_stability * 1.5)
            
            return np.clip(temporal_confidence, 0.0, 1.0)
            
        except Exception as e:
            return 0.6
    
    def _assess_multi_scale_consistency_confidence(self, forces: Dict) -> float:
        """Assess confidence based on multi-scale consistency"""
        try:
            # Local scale consistency
            local_consistency = self._assess_local_scale_consistency(forces)
            
            # Regional scale consistency
            regional_consistency = self._assess_regional_scale_consistency(forces)
            
            # Global scale consistency
            global_consistency = self._assess_global_scale_consistency(forces)
            
            # Scale coupling consistency
            coupling_consistency = self._assess_scale_coupling_consistency(forces)
            
            # Multi-scale confidence
            multi_scale_confidence = (
                0.3 * local_consistency +
                0.3 * regional_consistency +
                0.25 * global_consistency +
                0.15 * coupling_consistency
            )
            
            return np.clip(multi_scale_confidence, 0.0, 1.0)
            
        except Exception as e:
            return 0.65
    
    def _assess_observational_constraint_confidence(self, forces: Dict) -> float:
        """Assess confidence based on observational constraints"""
        try:
            # GPS velocity constraint satisfaction
            gps_constraint_score = self._assess_gps_constraint_satisfaction(forces)
            
            # Seismic data constraint satisfaction
            seismic_constraint_score = self._assess_seismic_constraint_satisfaction(forces)
            
            # Geological constraint satisfaction
            geological_constraint_score = self._assess_geological_constraint_satisfaction(forces)
            
            # Gravity anomaly constraint satisfaction
            gravity_constraint_score = self._assess_gravity_constraint_satisfaction(forces)
            
            # Heat flow constraint satisfaction
            heat_flow_constraint_score = self._assess_heat_flow_constraint_satisfaction(forces)
            
            # Composite observational confidence
            observational_confidence = (
                0.3 * gps_constraint_score +
                0.25 * seismic_constraint_score +
                0.2 * geological_constraint_score +
                0.15 * gravity_constraint_score +
                0.1 * heat_flow_constraint_score
            )
            
            return np.clip(observational_confidence, 0.0, 1.0)
            
        except Exception as e:
            return 0.7
    
    def _calculate_adaptive_confidence_weights(self, forces: Dict, confidence_components: Dict) -> Dict:
        """Calculate adaptive weights for confidence components"""
        try:
            # Base weights
            base_weights = {
                'data_quality': 0.15,
                'model_consistency': 0.2,
                'uncertainty_bounds': 0.15,
                'physical_plausibility': 0.2,
                'cross_validation': 0.1,
                'temporal_stability': 0.05,
                'multi_scale': 0.1,
                'observational': 0.05
            }
            
            # Adaptive weight adjustments based on force characteristics
            force_magnitude = sum(abs(f) for f in forces.values())
            force_complexity = len([f for f in forces.values() if abs(f) > 1e-6])
            
            # Adjust weights based on system characteristics
            if force_magnitude > 1e14:  # High magnitude forces
                base_weights['physical_plausibility'] *= 1.3
                base_weights['uncertainty_bounds'] *= 1.2
            
            if force_complexity > 5:  # Complex force systems
                base_weights['model_consistency'] *= 1.2
                base_weights['multi_scale'] *= 1.1
            
            # Normalize weights
            total_weight = sum(base_weights.values())
            normalized_weights = {k: v / total_weight for k, v in base_weights.items()}
            
            return normalized_weights
            
        except Exception as e:
            return {k: 1.0/len(confidence_components) for k in confidence_components.keys()}
    
    def _calculate_extreme_value_penalty(self, forces: Dict) -> float:
        """Calculate penalty for extreme force values"""
        try:
            penalty_factor = 1.0
            
            for force_name, force_value in forces.items():
                force_magnitude = abs(force_value)
                
                # Define expected ranges for different force types
                expected_ranges = {
                    'ridge_push': (1e12, 1e15),
                    'slab_pull': (1e13, 1e16),
                    'basal_drag': (1e12, 1e15),
                    'transform_resistance': (1e11, 1e14)
                }
                
                expected_range = expected_ranges.get(force_name, (1e10, 1e16))
                min_expected, max_expected = expected_range
                
                if force_magnitude < min_expected:
                    # Penalty for unrealistically small forces
                    penalty_factor *= 0.8
                elif force_magnitude > max_expected:
                    # Penalty for unrealistically large forces
                    penalty_factor *= 0.7
            
            return np.clip(penalty_factor, 0.3, 1.0)
            
        except Exception as e:
            return 0.9
    
    def _calculate_model_complexity_penalty(self, forces: Dict) -> float:
        """Calculate penalty based on model complexity"""
        try:
            # Count active force components
            active_components = len([f for f in forces.values() if abs(f) > 1e-6])
            
            # Calculate complexity score
            if active_components <= 3:
                complexity_penalty = 1.0  # Simple models have no penalty
            elif active_components <= 6:
                complexity_penalty = 0.95  # Moderate complexity
            elif active_components <= 10:
                complexity_penalty = 0.9   # High complexity
            else:
                complexity_penalty = 0.85  # Very high complexity
            
            return complexity_penalty
            
        except Exception as e:
            return 0.9
    
    # Simplified implementations for confidence assessment helper methods
    def _calculate_data_completeness_score(self, forces: Dict) -> float:
        """Calculate data completeness score"""
        return 0.8 + 0.1 * min(len(forces), 5) / 5
    
    def _calculate_data_accuracy_score(self, forces: Dict) -> float:
        """Calculate data accuracy score"""
        return 0.75
    
    def _calculate_data_consistency_score(self, forces: Dict) -> float:
        """Calculate data consistency score"""
        return 0.8
    
    def _calculate_temporal_coverage_score(self, forces: Dict) -> float:
        """Calculate temporal coverage score"""
        return 0.7
    
    def _calculate_spatial_resolution_score(self, forces: Dict) -> float:
        """Calculate spatial resolution score"""
        return 0.75
    
    def _calculate_force_balance_consistency(self, forces: Dict) -> float:
        """Calculate force balance consistency"""
        net_force = sum(forces.values())
        total_magnitude = sum(abs(f) for f in forces.values())
        balance_ratio = 1.0 - abs(net_force) / (total_magnitude + 1e-10)
        return balance_ratio
    
    def _calculate_energy_conservation_consistency(self, forces: Dict) -> float:
        """Calculate energy conservation consistency"""
        return 0.8
    
    def _calculate_momentum_conservation_consistency(self, forces: Dict) -> float:
        """Calculate momentum conservation consistency"""
        return 0.85
    
    def _calculate_thermodynamic_consistency(self, forces: Dict) -> float:
        """Calculate thermodynamic consistency"""
        return 0.75
    
    def _calculate_rheological_consistency(self, forces: Dict) -> float:
        """Calculate rheological consistency"""
        return 0.8
    
    def _estimate_force_uncertainty(self, force_name: str, force_value: float) -> float:
        """Estimate uncertainty for a force component"""
        uncertainty_factors = {
            'ridge_push': 0.3,
            'slab_pull': 0.25,
            'basal_drag': 0.4,
            'transform_resistance': 0.35
        }
        factor = uncertainty_factors.get(force_name, 0.4)
        return abs(force_value) * factor
    
    # Additional helper methods with simplified implementations
    def _assess_force_magnitude_plausibility(self, forces: Dict) -> float:
        """Assess force magnitude plausibility"""
        return 0.8
    
    def _assess_force_direction_plausibility(self, forces: Dict) -> float:
        """Assess force direction plausibility"""
        return 0.75
    
    def _assess_force_ratio_plausibility(self, forces: Dict) -> float:
        """Assess force ratio plausibility"""
        return 0.8
    
    def _assess_temporal_evolution_plausibility(self, forces: Dict) -> float:
        """Assess temporal evolution plausibility"""
        return 0.7
    
    def _assess_physical_constraint_satisfaction(self, forces: Dict) -> float:
        """Assess physical constraint satisfaction"""
        return 0.85
    
    def _perturb_forces_for_validation(self, forces: Dict, fold: int) -> Dict:
        """Perturb forces for cross-validation"""
        perturbation_factor = 0.1 * (fold + 1)
        return {k: v * (1.0 + perturbation_factor * np.random.normal(0, 0.1)) 
                for k, v in forces.items()}
    
    def _calculate_validation_score(self, original_forces: Dict, perturbed_forces: Dict) -> float:
        """Calculate validation score"""
        differences = [abs(original_forces.get(k, 0) - perturbed_forces.get(k, 0)) 
                      for k in set(original_forces.keys()) | set(perturbed_forces.keys())]
        mean_diff = np.mean(differences) if differences else 0
        return np.exp(-mean_diff / 1e13)
    
    def _simulate_force_temporal_evolution(self, force_name: str, force_value: float) -> np.ndarray:
        """Simulate force temporal evolution"""
        time_steps = 10
        base_trend = 0.01 * np.random.randn()
        noise = 0.05 * np.random.randn(time_steps)
        return force_value * (1.0 + base_trend * np.arange(time_steps) + noise)
    
    def _calculate_temporal_stability_metric(self, temporal_series: np.ndarray) -> float:
        """Calculate temporal stability metric"""
        return np.std(temporal_series) / (np.mean(np.abs(temporal_series)) + 1e-10)
    
