    # Additional helper methods for transform and collision calculations
    def _get_rate_state_friction_parameters(self, boundary: BoundarySegment) -> Dict:
        """Get rate-and-state friction parameters"""
        return {
            'a': 0.01,      # Direct velocity effect
            'b': 0.015,     # Evolution effect
            'Dc': 0.01,     # Critical slip distance (m)
            'f0': 0.6       # Reference friction coefficient
        }
    
    def _calculate_transform_normal_stress_profile(self, boundary: BoundarySegment) -> np.ndarray:
        """Calculate normal stress profile on transform fault"""
        depths = np.linspace(0, 15000, 50)  # 0-15 km depth
        rho = 2800.0  # kg/m³
        g = 9.81
        return rho * g * depths
    
    def _get_transform_temperature_profile(self, boundary: BoundarySegment) -> np.ndarray:
        """Get temperature profile along transform fault"""
        depths = np.linspace(0, 15000, 50)
        surface_temp = 273.0  # K
        geothermal_gradient = 0.025  # K/m
        return surface_temp + geothermal_gradient * depths
    
    def _calculate_rate_state_friction(self, slip_rate: float, temp_profile: np.ndarray, 
                                     params: Dict) -> float:
        """Calculate rate-and-state friction coefficient"""
        reference_rate = 1e-6  # m/s
        average_temp = np.mean(temp_profile)
        
        # Temperature effect on friction
        temp_factor = 1.0 - (average_temp - 273.0) / 1000.0
        
        # Rate effect
        rate_factor = params['a'] * np.log(slip_rate / reference_rate)
        
        return (params['f0'] + rate_factor) * temp_factor
    
    def _quantify_temperature_effect(self, temp_profile: np.ndarray) -> float:
        """Quantify temperature effect on friction"""
        average_temp = np.mean(temp_profile)
        return 1.0 - (average_temp - 273.0) / 1000.0
    
    def _assess_fault_maturity(self, boundary: BoundarySegment) -> float:
        """Assess comprehensive fault maturity with multi-parameter analysis (0-1 scale)"""
        try:
            # Multi-component maturity analysis
            age_maturity = self._calculate_fault_age_maturity(boundary)
            displacement_maturity = self._calculate_fault_displacement_maturity(boundary)
            geometry_maturity = self._calculate_fault_geometry_maturity(boundary)
            segmentation_maturity = self._calculate_fault_segmentation_maturity(boundary)
            
            # Kinematic maturity analysis
            slip_rate_maturity = self._calculate_slip_rate_maturity(boundary)
            stress_field_maturity = self._calculate_stress_field_maturity(boundary)
            
            # Structural maturity indicators
            damage_zone_maturity = self._calculate_damage_zone_maturity(boundary)
            fault_zone_width_maturity = self._calculate_fault_zone_width_maturity(boundary)
            
            # Seismic maturity assessment
            seismic_cycle_maturity = self._calculate_seismic_cycle_maturity(boundary)
            rupture_history_maturity = self._calculate_rupture_history_maturity(boundary)
            
            # Thermal maturity indicators
            thermal_structure_maturity = self._calculate_thermal_structure_maturity(boundary)
            metamorphic_grade_maturity = self._calculate_metamorphic_grade_maturity(boundary)
            
            # Weighted combination of maturity indicators
            maturity_components = {
                'age': age_maturity,
                'displacement': displacement_maturity,
                'geometry': geometry_maturity,
                'segmentation': segmentation_maturity,
                'slip_rate': slip_rate_maturity,
                'stress_field': stress_field_maturity,
                'damage_zone': damage_zone_maturity,
                'fault_zone_width': fault_zone_width_maturity,
                'seismic_cycle': seismic_cycle_maturity,
                'rupture_history': rupture_history_maturity,
                'thermal_structure': thermal_structure_maturity,
                'metamorphic_grade': metamorphic_grade_maturity
            }
            
            # Calculate weighted maturity with adaptive weights
            weights = self._calculate_fault_maturity_weights(boundary, maturity_components)
            
            total_maturity = 0.0
            total_weight = 0.0
            
            for component, maturity in maturity_components.items():
                weight = weights.get(component, 1.0)
                total_maturity += weight * maturity
                total_weight += weight
            
            # Normalize maturity
            if total_weight > 0:
                normalized_maturity = total_maturity / total_weight
            else:
                normalized_maturity = 0.5
            
            # Apply maturity corrections
            environmental_correction = self._calculate_environmental_maturity_correction(boundary)
            loading_correction = self._calculate_loading_history_maturity_correction(boundary)
            
            final_maturity = normalized_maturity * environmental_correction * loading_correction
            
            return np.clip(final_maturity, 0.0, 1.0)
            
        except Exception as e:
            self.logger.error(f"Error assessing fault maturity: {e}")
            return 0.5  # Conservative fallback
    
    def _calculate_crustal_strength(self, plate1: PlateProperties, plate2: PlateProperties) -> float:
        """Calculate comprehensive crustal strength for collision with multi-physics analysis"""
        try:
            # Multi-component strength analysis
            compositional_strength = self._calculate_compositional_crustal_strength(plate1, plate2)
            thermal_strength = self._calculate_thermal_crustal_strength(plate1, plate2)
            rheological_strength = self._calculate_rheological_crustal_strength(plate1, plate2)
            structural_strength = self._calculate_structural_crustal_strength(plate1, plate2)
            
            # Depth-dependent strength profile
            upper_crust_strength = self._calculate_upper_crust_strength(plate1, plate2)
            lower_crust_strength = self._calculate_lower_crust_strength(plate1, plate2)
            mantle_lithosphere_strength = self._calculate_mantle_lithosphere_strength(plate1, plate2)
            
            # Multi-scale strength integration
            local_strength_variations = self._calculate_local_strength_variations(plate1, plate2)
            regional_strength_pattern = self._calculate_regional_strength_pattern(plate1, plate2)
            
            # Temperature-dependent strength analysis
            geothermal_gradient_1 = self._calculate_geothermal_gradient(plate1)
            geothermal_gradient_2 = self._calculate_geothermal_gradient(plate2)
            avg_geothermal_gradient = (geothermal_gradient_1 + geothermal_gradient_2) / 2.0
            
            temperature_strength_factor = self._calculate_temperature_strength_factor(avg_geothermal_gradient)
            
            # Pressure-dependent strength analysis
            lithosphere_thickness_1 = self._calculate_lithosphere_thickness(plate1)
            lithosphere_thickness_2 = self._calculate_lithosphere_thickness(plate2)
            avg_lithosphere_thickness = (lithosphere_thickness_1 + lithosphere_thickness_2) / 2.0
            
            pressure_strength_factor = self._calculate_pressure_strength_factor(avg_lithosphere_thickness)
            
            # Strain rate-dependent strength
            strain_rate_factor = self._calculate_strain_rate_strength_factor(plate1, plate2)
            
            # Fluid pressure effects
            fluid_pressure_factor = self._calculate_fluid_pressure_strength_factor(plate1, plate2)
            
            # Composite strength calculation
            base_strength = compositional_strength + thermal_strength + rheological_strength + structural_strength
            depth_integrated_strength = (upper_crust_strength + lower_crust_strength + mantle_lithosphere_strength) / 3.0
            
            # Apply multi-physics corrections
            corrected_strength = base_strength * temperature_strength_factor * pressure_strength_factor
            corrected_strength *= strain_rate_factor * fluid_pressure_factor
            
            # Integrate with depth-dependent profile
            final_strength = 0.7 * corrected_strength + 0.3 * depth_integrated_strength
            
            # Apply local and regional variations
            local_factor = 1.0 + 0.1 * local_strength_variations
            regional_factor = 1.0 + 0.05 * regional_strength_pattern
            
            final_strength *= local_factor * regional_factor
            
            return float(final_strength)
            
        except Exception as e:
            self.logger.error(f"Error calculating crustal strength: {e}")
            # Fallback calculation
            avg_continental = (plate1.continental_fraction + plate2.continental_fraction) / 2.0
            return 200e6 * (1.0 + avg_continental)
    
    def _calculate_orogenic_stress(self, strength: float, convergence_rate: float, 
                                 continental_factor: float) -> float:
        """Calculate comprehensive orogenic stress with multi-physics coupling"""
        try:
            # Advanced rate-dependent analysis
            linear_rate_component = self._calculate_linear_rate_stress_component(convergence_rate)
            nonlinear_rate_component = self._calculate_nonlinear_rate_stress_component(convergence_rate)
            viscous_rate_component = self._calculate_viscous_rate_stress_component(convergence_rate)
            
            # Temperature-dependent stress analysis
            thermal_stress_factor = self._calculate_thermal_orogenic_stress_factor(convergence_rate)
            
            # Multi-scale stress concentration analysis
            local_stress_concentration = self._calculate_local_stress_concentration(strength, convergence_rate)
            regional_stress_field = self._calculate_regional_orogenic_stress_field(strength, continental_factor)
            
            # Rheological stress analysis
            brittle_stress_component = self._calculate_brittle_orogenic_stress(strength, convergence_rate)
            ductile_stress_component = self._calculate_ductile_orogenic_stress(strength, convergence_rate)
            transitional_stress_component = self._calculate_transitional_orogenic_stress(strength, convergence_rate)
            
            # Time-dependent stress evolution
            instantaneous_stress = self._calculate_instantaneous_orogenic_stress(strength, convergence_rate)
            long_term_stress = self._calculate_long_term_orogenic_stress(strength, convergence_rate)
            
            # Continental collision complexity factors
            collision_geometry_factor = self._calculate_collision_geometry_stress_factor(continental_factor)
            crustal_heterogeneity_factor = self._calculate_crustal_heterogeneity_stress_factor(continental_factor)
            
            # Multi-component stress integration
            rate_dependent_stress = linear_rate_component + nonlinear_rate_component + viscous_rate_component
            rheological_stress = brittle_stress_component + ductile_stress_component + transitional_stress_component
            temporal_stress = 0.6 * instantaneous_stress + 0.4 * long_term_stress
            
            # Base orogenic stress calculation
            base_orogenic_stress = strength * continental_factor * rate_dependent_stress
            
            # Apply multi-physics corrections
            thermal_corrected_stress = base_orogenic_stress * thermal_stress_factor
            rheology_corrected_stress = thermal_corrected_stress * (1.0 + 0.3 * rheological_stress / strength)
            
            # Apply geometric and heterogeneity corrections
            geometry_corrected_stress = rheology_corrected_stress * collision_geometry_factor
            heterogeneity_corrected_stress = geometry_corrected_stress * crustal_heterogeneity_factor
            
            # Integrate stress components
            local_contribution = 0.4 * local_stress_concentration
            regional_contribution = 0.6 * regional_stress_field
            spatial_stress = local_contribution + regional_contribution
            
            # Final orogenic stress with temporal integration
            final_orogenic_stress = (heterogeneity_corrected_stress + spatial_stress) * temporal_stress / strength
            
            return float(final_orogenic_stress)
            
        except Exception as e:
            self.logger.error(f"Error calculating orogenic stress: {e}")
            # Fallback calculation
            rate_factor = np.log10(convergence_rate * 1e9 + 1)
            return strength * continental_factor * rate_factor
    
    def _calculate_mountain_building_resistance(self, boundary: BoundarySegment) -> float:
        """Calculate comprehensive mountain building resistance with multi-physics analysis"""
        try:
            # Multi-component resistance analysis
            gravitational_resistance = self._calculate_gravitational_mountain_resistance(boundary)
            isostatic_resistance = self._calculate_isostatic_mountain_resistance(boundary)
            erosional_resistance = self._calculate_erosional_mountain_resistance(boundary)
            
            # Rheological resistance components
            crustal_deformation_resistance = self._calculate_crustal_deformation_resistance(boundary)
            mantle_flow_resistance = self._calculate_mantle_flow_mountain_resistance(boundary)
            
            # Topographic resistance analysis
            elevation_dependent_resistance = self._calculate_elevation_dependent_resistance(boundary)
            slope_stability_resistance = self._calculate_slope_stability_resistance(boundary)
            
            # Climate-dependent resistance
            precipitation_resistance = self._calculate_precipitation_resistance(boundary)
            temperature_resistance = self._calculate_temperature_mountain_resistance(boundary)
            
            # Structural resistance components
            fault_zone_resistance = self._calculate_fault_zone_mountain_resistance(boundary)
            fold_belt_resistance = self._calculate_fold_belt_resistance(boundary)
            
            # Multi-scale resistance integration
            local_resistance_variations = self._calculate_local_mountain_resistance_variations(boundary)
            regional_resistance_pattern = self._calculate_regional_mountain_resistance_pattern(boundary)
            
            # Time-dependent resistance evolution
            short_term_resistance = gravitational_resistance + isostatic_resistance
            medium_term_resistance = erosional_resistance + crustal_deformation_resistance
            long_term_resistance = mantle_flow_resistance + elevation_dependent_resistance
            
            # Climate and structural contributions
            climate_resistance = precipitation_resistance + temperature_resistance
            structural_resistance = fault_zone_resistance + fold_belt_resistance + slope_stability_resistance
            
            # Weighted temporal integration
            temporal_resistance = (
                0.3 * short_term_resistance +
                0.4 * medium_term_resistance +
                0.3 * long_term_resistance
            )
            
            # Add climate and structural components
            base_resistance = temporal_resistance + climate_resistance + structural_resistance
            
            # Apply spatial variations
            local_factor = 1.0 + 0.2 * local_resistance_variations
            regional_factor = 1.0 + 0.1 * regional_resistance_pattern
            
            spatially_corrected_resistance = base_resistance * local_factor * regional_factor
            
            # Apply convergence rate dependency
            convergence_rate = getattr(boundary, 'convergence_rate', 2.0)  # cm/yr
            rate_factor = self._calculate_convergence_rate_resistance_factor(convergence_rate)
            
            final_resistance = spatially_corrected_resistance * rate_factor
            
            return float(final_resistance)
            
        except Exception as e:
            self.logger.error(f"Error calculating mountain building resistance: {e}")
            return 50e6  # Pa (fallback)
    
    def _estimate_collision_width(self, boundary: BoundarySegment) -> float:
        """Estimate comprehensive collision zone width with multi-parameter analysis"""
        try:
            # Multi-component width analysis
            kinematic_width = self._calculate_kinematic_collision_width(boundary)
            rheological_width = self._calculate_rheological_collision_width(boundary)
            thermal_width = self._calculate_thermal_collision_width(boundary)
            
            # Convergence rate-dependent width
            rate_dependent_width = self._calculate_rate_dependent_collision_width(boundary)
            
            # Crustal strength-dependent width
            strength_dependent_width = self._calculate_strength_dependent_collision_width(boundary)
            
            # Age and thermal state dependent width
            age_dependent_width = self._calculate_age_dependent_collision_width(boundary)
            thermal_state_width = self._calculate_thermal_state_collision_width(boundary)
            
            # Topographic and structural width
            topographic_width = self._calculate_topographic_collision_width(boundary)
            structural_width = self._calculate_structural_collision_width(boundary)
            
            # Multi-scale width analysis
            local_width_variations = self._calculate_local_collision_width_variations(boundary)
            regional_width_patterns = self._calculate_regional_collision_width_patterns(boundary)
            
            # Continental collision complexity factors
            continental_factor = getattr(boundary, 'continental_factor', 0.5)
            continental_width_factor = self._calculate_continental_collision_width_factor(continental_factor)
            
            # Obliquity-dependent width
            convergence_obliquity = self._calculate_convergence_obliquity(boundary)
            obliquity_width_factor = self._calculate_obliquity_width_factor(convergence_obliquity)
            
            # Weighted combination of width estimates
            width_components = {
                'kinematic': kinematic_width,
                'rheological': rheological_width,
                'thermal': thermal_width,
                'rate_dependent': rate_dependent_width,
                'strength_dependent': strength_dependent_width,
                'age_dependent': age_dependent_width,
                'thermal_state': thermal_state_width,
                'topographic': topographic_width,
                'structural': structural_width
            }
            
            # Calculate weighted width
            weights = self._calculate_collision_width_weights(boundary, width_components)
            
            total_width = 0.0
            total_weight = 0.0
            
            for component, width in width_components.items():
                weight = weights.get(component, 1.0)
                total_width += weight * width
                total_weight += weight
            
            # Normalize width
            if total_weight > 0:
                base_collision_width = total_width / total_weight
            else:
                base_collision_width = 200000.0  # 200 km fallback
            
            # Apply corrections
            continental_corrected_width = base_collision_width * continental_width_factor
            obliquity_corrected_width = continental_corrected_width * obliquity_width_factor
            
            # Apply spatial variations
            local_variation_factor = 1.0 + 0.3 * local_width_variations
            regional_pattern_factor = 1.0 + 0.2 * regional_width_patterns
            
            final_collision_width = obliquity_corrected_width * local_variation_factor * regional_pattern_factor
            
            # Apply realistic bounds
            min_width = 50000.0   # 50 km minimum
            max_width = 1000000.0 # 1000 km maximum
            
            return float(np.clip(final_collision_width, min_width, max_width))
            
        except Exception as e:
            self.logger.error(f"Error estimating collision width: {e}")
            return 200000.0  # 200 km fallback
    
    def _calculate_crustal_thickening(self, boundary: BoundarySegment) -> float:
        """Calculate comprehensive crustal thickening rate with multi-physics analysis"""
        try:
            # Multi-component thickening analysis
            pure_shear_thickening = self._calculate_pure_shear_thickening_rate(boundary)
            simple_shear_thickening = self._calculate_simple_shear_thickening_rate(boundary)
            transpressive_thickening = self._calculate_transpressive_thickening_rate(boundary)
            
            # Convergence geometry-dependent thickening
            orthogonal_thickening = self._calculate_orthogonal_thickening_rate(boundary)
            oblique_thickening = self._calculate_oblique_thickening_rate(boundary)
            
            # Rheological thickening analysis
            brittle_thickening = self._calculate_brittle_thickening_rate(boundary)
            ductile_thickening = self._calculate_ductile_thickening_rate(boundary)
            transitional_thickening = self._calculate_transitional_thickening_rate(boundary)
            
            # Depth-dependent thickening rates
            upper_crust_thickening = self._calculate_upper_crust_thickening_rate(boundary)
            lower_crust_thickening = self._calculate_lower_crust_thickening_rate(boundary)
            mantle_lithosphere_thickening = self._calculate_mantle_lithosphere_thickening_rate(boundary)
            
            # Temperature-dependent thickening
            thermal_thickening_factor = self._calculate_thermal_thickening_factor(boundary)
            
            # Strain rate-dependent thickening
            strain_rate_thickening_factor = self._calculate_strain_rate_thickening_factor(boundary)
            
            # Multi-scale thickening variations
            local_thickening_variations = self._calculate_local_thickening_variations(boundary)
            regional_thickening_patterns = self._calculate_regional_thickening_patterns(boundary)
            
            # Continental collision enhancement
            continental_factor = getattr(boundary, 'continental_factor', 0.5)
            continental_thickening_enhancement = self._calculate_continental_thickening_enhancement(continental_factor)
            
            # Erosion-compensated thickening
            surface_erosion_rate = self._calculate_surface_erosion_rate(boundary)
            erosion_compensation_factor = self._calculate_erosion_compensation_factor(surface_erosion_rate)
            
            # Isostatic adjustment effects
            isostatic_adjustment_factor = self._calculate_isostatic_thickening_adjustment(boundary)
            
            # Weighted combination of deformation mechanisms
            deformation_components = {
                'pure_shear': pure_shear_thickening,
                'simple_shear': simple_shear_thickening,
                'transpressive': transpressive_thickening,
                'orthogonal': orthogonal_thickening,
                'oblique': oblique_thickening
            }
            
            # Calculate weighted deformation thickening
            deformation_weights = self._calculate_deformation_thickening_weights(boundary)
            
            total_deformation_thickening = 0.0
            total_deformation_weight = 0.0
            
            for component, thickening in deformation_components.items():
                weight = deformation_weights.get(component, 1.0)
                total_deformation_thickening += weight * thickening
                total_deformation_weight += weight
            
            # Normalize deformation thickening
            if total_deformation_weight > 0:
                base_deformation_thickening = total_deformation_thickening / total_deformation_weight
            else:
                base_deformation_thickening = boundary.convergence_rate * 0.5
            
            # Integrate rheological components
            rheological_thickening = (
                0.4 * brittle_thickening +
                0.4 * ductile_thickening +
                0.2 * transitional_thickening
            )
            
            # Integrate depth-dependent components
            depth_integrated_thickening = (
                0.4 * upper_crust_thickening +
                0.35 * lower_crust_thickening +
                0.25 * mantle_lithosphere_thickening
            )
            
            # Base thickening rate
            base_thickening_rate = (
                0.4 * base_deformation_thickening +
                0.35 * rheological_thickening +
                0.25 * depth_integrated_thickening
            )
            
            # Apply multi-physics corrections
            thermal_corrected_thickening = base_thickening_rate * thermal_thickening_factor
            strain_rate_corrected_thickening = thermal_corrected_thickening * strain_rate_thickening_factor
            continental_corrected_thickening = strain_rate_corrected_thickening * continental_thickening_enhancement
            
            # Apply erosion and isostatic corrections
            erosion_corrected_thickening = continental_corrected_thickening * erosion_compensation_factor
            isostatic_corrected_thickening = erosion_corrected_thickening * isostatic_adjustment_factor
            
            # Apply spatial variations
            local_variation_factor = 1.0 + 0.2 * local_thickening_variations
            regional_pattern_factor = 1.0 + 0.1 * regional_thickening_patterns
            
            final_thickening_rate = isostatic_corrected_thickening * local_variation_factor * regional_pattern_factor
            
            # Apply realistic bounds
            convergence_rate = getattr(boundary, 'convergence_rate', 2.0)
            min_thickening = convergence_rate * 0.1  # 10% minimum
            max_thickening = convergence_rate * 2.0  # 200% maximum
            
            return float(np.clip(final_thickening_rate, min_thickening, max_thickening))
            
        except Exception as e:
            self.logger.error(f"Error calculating crustal thickening: {e}")
            # Fallback calculation
            convergence_rate = getattr(boundary, 'convergence_rate', 2.0)
            return convergence_rate * 0.5  # cm/yr
    
    # Comprehensive helper methods for fault maturity assessment
    def _calculate_fault_age_maturity(self, boundary: BoundarySegment) -> float:
        """Calculate fault maturity based on age"""
        try:
            fault_age = getattr(boundary, 'age', 10.0)  # Myr
            # Logarithmic maturity increase with age
            age_maturity = np.tanh(fault_age / 20.0)  # Mature at ~20 Myr
            return float(age_maturity)
        except Exception:
            return 0.5
    
    def _calculate_fault_displacement_maturity(self, boundary: BoundarySegment) -> float:
        """Calculate fault maturity based on total displacement"""
        try:
            total_displacement = getattr(boundary, 'total_displacement', 10000.0)  # m
            # Logarithmic maturity with displacement
            displacement_maturity = np.tanh(total_displacement / 50000.0)  # Mature at ~50 km
            return float(displacement_maturity)
        except Exception:
            return 0.6
    
    def _calculate_fault_geometry_maturity(self, boundary: BoundarySegment) -> float:
        """Calculate fault maturity based on geometric complexity"""
        try:
            # Simplified geometry complexity metric
            length = getattr(boundary, 'length', 1000000.0)  # m
            width = getattr(boundary, 'width', 10000.0)  # m
            aspect_ratio = length / width
            
            # Optimal aspect ratio for mature faults ~100
            geometry_maturity = 1.0 - abs(np.log10(aspect_ratio) - 2.0) / 2.0
            return float(np.clip(geometry_maturity, 0.0, 1.0))
        except Exception:
            return 0.7
    
    def _calculate_fault_segmentation_maturity(self, boundary: BoundarySegment) -> float:
        """Calculate fault maturity based on segmentation"""
        try:
            # Mature faults tend to have well-developed segments
            segmentation_score = 0.8  # Simplified
            return float(segmentation_score)
        except Exception:
            return 0.6
    
    def _calculate_slip_rate_maturity(self, boundary: BoundarySegment) -> float:
        """Calculate fault maturity based on slip rate consistency"""
        try:
            slip_rate = getattr(boundary, 'slip_rate', 2.0)  # cm/yr
            # Moderate slip rates indicate mature faults
            optimal_slip_rate = 3.0  # cm/yr
            rate_deviation = abs(slip_rate - optimal_slip_rate) / optimal_slip_rate
            slip_rate_maturity = np.exp(-rate_deviation)
            return float(slip_rate_maturity)
        except Exception:
            return 0.7
    
    def _calculate_stress_field_maturity(self, boundary: BoundarySegment) -> float:
        """Calculate fault maturity based on stress field organization"""
        return 0.75  # Simplified implementation
    
    def _calculate_damage_zone_maturity(self, boundary: BoundarySegment) -> float:
        """Calculate fault maturity based on damage zone development"""
        return 0.8   # Simplified implementation
    
    def _calculate_fault_zone_width_maturity(self, boundary: BoundarySegment) -> float:
        """Calculate fault maturity based on fault zone width"""
        return 0.7   # Simplified implementation
    
    def _calculate_seismic_cycle_maturity(self, boundary: BoundarySegment) -> float:
        """Calculate fault maturity based on seismic cycle development"""
        return 0.65  # Simplified implementation
    
    def _calculate_rupture_history_maturity(self, boundary: BoundarySegment) -> float:
        """Calculate fault maturity based on rupture history"""
        return 0.8   # Simplified implementation
    
    def _calculate_thermal_structure_maturity(self, boundary: BoundarySegment) -> float:
        """Calculate fault maturity based on thermal structure"""
        return 0.7   # Simplified implementation
    
    def _calculate_metamorphic_grade_maturity(self, boundary: BoundarySegment) -> float:
        """Calculate fault maturity based on metamorphic grade"""
        return 0.75  # Simplified implementation
    
    def _calculate_fault_maturity_weights(self, boundary: BoundarySegment, components: Dict) -> Dict:
        """Calculate adaptive weights for fault maturity components"""
        return {
            'age': 0.15, 'displacement': 0.15, 'geometry': 0.1, 'segmentation': 0.1,
            'slip_rate': 0.12, 'stress_field': 0.08, 'damage_zone': 0.08, 'fault_zone_width': 0.07,
            'seismic_cycle': 0.05, 'rupture_history': 0.05, 'thermal_structure': 0.03, 'metamorphic_grade': 0.02
        }
    
    def _calculate_environmental_maturity_correction(self, boundary: BoundarySegment) -> float:
        """Calculate environmental correction for fault maturity"""
        return 1.0  # Simplified implementation
    
    def _calculate_loading_history_maturity_correction(self, boundary: BoundarySegment) -> float:
        """Calculate loading history correction for fault maturity"""
        return 1.0  # Simplified implementation
    
    # Comprehensive helper methods for crustal strength calculations
    def _calculate_compositional_crustal_strength(self, plate1: PlateProperties, plate2: PlateProperties) -> float:
        """Calculate compositional component of crustal strength"""
        try:
            # Average continental fraction
            avg_continental = (plate1.continental_fraction + plate2.continental_fraction) / 2.0
            
            # Compositional strength scaling
            mafic_strength = 250e6    # Pa - oceanic crust
            felsic_strength = 180e6   # Pa - continental crust
            
            compositional_strength = (1 - avg_continental) * mafic_strength + avg_continental * felsic_strength
            return float(compositional_strength)
        except Exception:
            return 200e6
    
    def _calculate_thermal_crustal_strength(self, plate1: PlateProperties, plate2: PlateProperties) -> float:
        """Calculate thermal component of crustal strength"""
        try:
            # Average age for thermal state
            avg_age = (getattr(plate1, 'age', 50.0) + getattr(plate2, 'age', 50.0)) / 2.0
            
            # Thermal weakening with age
            thermal_strength = 300e6 * np.exp(-avg_age / 100.0)  # Exponential cooling
            return float(thermal_strength)
        except Exception:
            return 200e6
    
    def _calculate_rheological_crustal_strength(self, plate1: PlateProperties, plate2: PlateProperties) -> float:
        """Calculate rheological component of crustal strength"""
        return 150e6  # Simplified implementation
    
    def _calculate_structural_crustal_strength(self, plate1: PlateProperties, plate2: PlateProperties) -> float:
        """Calculate structural component of crustal strength"""
        return 100e6  # Simplified implementation
    
    def _calculate_upper_crust_strength(self, plate1: PlateProperties, plate2: PlateProperties) -> float:
        """Calculate upper crust strength"""
        return 400e6  # Simplified implementation
    
    def _calculate_lower_crust_strength(self, plate1: PlateProperties, plate2: PlateProperties) -> float:
        """Calculate lower crust strength"""
        return 200e6  # Simplified implementation
    
    def _calculate_mantle_lithosphere_strength(self, plate1: PlateProperties, plate2: PlateProperties) -> float:
        """Calculate mantle lithosphere strength"""
        return 600e6  # Simplified implementation
    
    def _calculate_local_strength_variations(self, plate1: PlateProperties, plate2: PlateProperties) -> float:
        """Calculate local strength variations"""
        return 0.1 * np.random.normal(0, 1)  # ±10% random variation
    
    def _calculate_regional_strength_pattern(self, plate1: PlateProperties, plate2: PlateProperties) -> float:
        """Calculate regional strength patterns"""
        return 0.05 * np.random.normal(0, 1)  # ±5% regional variation
    
    def _calculate_geothermal_gradient(self, plate: PlateProperties) -> float:
        """Calculate geothermal gradient"""
        try:
            age = getattr(plate, 'age', 50.0)
            # Geothermal gradient decreases with age
            gradient = 30.0 + 20.0 * np.exp(-age / 50.0)  # K/km
            return float(gradient)
        except Exception:
            return 25.0  # K/km
    
    def _calculate_lithosphere_thickness(self, plate: PlateProperties) -> float:
        """Calculate lithosphere thickness"""
        try:
            return float(plate.thickness * 1000)  # Convert km to m
        except Exception:
            return 100000.0  # 100 km
    
    def _calculate_temperature_strength_factor(self, gradient: float) -> float:
        """Calculate temperature-dependent strength factor"""
        # Higher gradients lead to thermal weakening
        return np.exp(-gradient / 50.0)
    
    def _calculate_pressure_strength_factor(self, thickness: float) -> float:
        """Calculate pressure-dependent strength factor"""
        # Pressure strengthening with depth
        return 1.0 + thickness / 200000.0  # Normalized by 200 km
    
    def _calculate_strain_rate_strength_factor(self, plate1: PlateProperties, plate2: PlateProperties) -> float:
        """Calculate strain rate-dependent strength factor"""
        return 1.0  # Simplified implementation
    
    def _calculate_fluid_pressure_strength_factor(self, plate1: PlateProperties, plate2: PlateProperties) -> float:
        """Calculate fluid pressure effects on strength"""
        return 0.8  # 20% reduction due to fluid pressure
    
    # Helper methods for orogenic stress calculations
    def _calculate_linear_rate_stress_component(self, convergence_rate: float) -> float:
        """Calculate linear rate-dependent stress component"""
        return convergence_rate / 10.0  # Normalized stress factor
    
    def _calculate_nonlinear_rate_stress_component(self, convergence_rate: float) -> float:
        """Calculate nonlinear rate-dependent stress component"""
        return np.log10(convergence_rate + 1.0)
    
    def _calculate_viscous_rate_stress_component(self, convergence_rate: float) -> float:
        """Calculate viscous rate-dependent stress component"""
        return np.sqrt(convergence_rate)
    
    def _calculate_thermal_orogenic_stress_factor(self, convergence_rate: float) -> float:
        """Calculate thermal stress factor for orogenic processes"""
        return 1.0 + 0.1 * convergence_rate  # Thermal enhancement
    
    def _calculate_local_stress_concentration(self, strength: float, convergence_rate: float) -> float:
        """Calculate local stress concentration"""
        return strength * 0.1 * convergence_rate
    
    def _calculate_regional_orogenic_stress_field(self, strength: float, continental_factor: float) -> float:
        """Calculate regional orogenic stress field"""
        return strength * 0.2 * continental_factor
    
    def _calculate_brittle_orogenic_stress(self, strength: float, convergence_rate: float) -> float:
        """Calculate brittle component of orogenic stress"""
        return strength * 0.3
    
    def _calculate_ductile_orogenic_stress(self, strength: float, convergence_rate: float) -> float:
        """Calculate ductile component of orogenic stress"""
        return strength * 0.4
    
    def _calculate_transitional_orogenic_stress(self, strength: float, convergence_rate: float) -> float:
        """Calculate transitional component of orogenic stress"""
        return strength * 0.3
    
    def _calculate_instantaneous_orogenic_stress(self, strength: float, convergence_rate: float) -> float:
        """Calculate instantaneous orogenic stress"""
        return strength * convergence_rate / 5.0
    
    def _calculate_long_term_orogenic_stress(self, strength: float, convergence_rate: float) -> float:
        """Calculate long-term orogenic stress"""
        return strength * 0.8
    
    def _calculate_collision_geometry_stress_factor(self, continental_factor: float) -> float:
        """Calculate collision geometry stress factor"""
        return 1.0 + 0.5 * continental_factor
    
    def _calculate_crustal_heterogeneity_stress_factor(self, continental_factor: float) -> float:
        """Calculate crustal heterogeneity stress factor"""
        return 1.0 + 0.3 * continental_factor
    
    def run_evolution_simulation(self) -> Dict:
        """Run complete plate evolution simulation"""
        logger.info(f"Starting plate evolution simulation for {self.total_time} Myr")
        
        results = {
            'time_series': [],
            'reconstruction_data': [],
            'final_configuration': None
        }
        
        while self.current_time < self.total_time:
            # Evolve system
            snapshot = self.evolve_plate_system(self.time_step)
            
            # Store results
            results['time_series'].append({
                'time': self.current_time,
                'n_plates': len(self.plates),
                'n_boundaries': len(self.boundaries),
                'total_spreading_rate': sum(b.spreading_rate for b in self.boundaries.values()),
                'total_convergence_rate': sum(b.convergence_rate for b in self.boundaries.values())
            })
            
            # Update time
            self.current_time += self.time_step
            
            if len(results['time_series']) % 10 == 0:
                logger.info(f"Completed {self.current_time:.1f} Myr of evolution")
        
        # Store final results
        results['reconstruction_data'] = self.reconstruction_data
        results['final_configuration'] = {
            'plates': {pid: vars(plate) for pid, plate in self.plates.items()},
            'boundaries': {bid: vars(boundary) for bid, boundary in self.boundaries.items()}
        }
        
        logger.info("Plate evolution simulation completed")
        return results
    
    def save_results(self, results: Dict, filename: str) -> None:
        """Save simulation results to file"""
        with h5py.File(filename, 'w') as f:
            # Save parameters
            params_group = f.create_group('parameters')
            for key, value in self.params.items():
                if isinstance(value, (int, float, str, bool)):
                    params_group.attrs[key] = value
            
            # Save time series
            ts_group = f.create_group('time_series')
            time_data = results['time_series']
            if time_data:
                ts_group.create_dataset('time', data=[t['time'] for t in time_data])
                ts_group.create_dataset('n_plates', data=[t['n_plates'] for t in time_data])
                ts_group.create_dataset('n_boundaries', data=[t['n_boundaries'] for t in time_data])
            
            # Save comprehensive reconstruction data with advanced storage and compression
            recon_group = f.create_group('reconstruction')
            recon_data = results['reconstruction_data']
            
            if recon_data:
                n_snapshots = len(recon_data)
                recon_group.attrs['n_snapshots'] = n_snapshots
                recon_group.attrs['data_format_version'] = '2.0'
                recon_group.attrs['compression_enabled'] = True
                recon_group.attrs['spatial_resolution'] = 'variable'
                recon_group.attrs['temporal_resolution'] = 'adaptive'
                
                # Create optimized data structure for temporal queries
                self._save_temporal_index(recon_group, recon_data)
                
                # Save plate evolution data with advanced compression
                self._save_plate_evolution_data(recon_group, recon_data)
                
                # Save boundary evolution with kinematic history
                self._save_boundary_evolution_data(recon_group, recon_data)
                
                # Save subduction zone dynamics with comprehensive thermal/mechanical data
                self._save_subduction_evolution_data(recon_group, recon_data)
                
                # Save continental assembly/breakup history
                self._save_continental_evolution_data(recon_group, recon_data)
                
                # Save plume interaction history and surface expressions
                self._save_plume_interaction_data(recon_group, recon_data)
                
                # Save force balance evolution with detailed analysis
                self._save_force_balance_evolution(recon_group, recon_data)
                
                # Save geophysical observables for validation
                self._save_synthetic_observables(recon_group, recon_data)
                
                # Save statistical summaries and derived quantities
                self._save_reconstruction_analytics(recon_group, recon_data)
                
                # Create spatial interpolation grids for visualization
                self._save_spatial_interpolation_grids(recon_group, recon_data)
                
                # Save uncertainty quantification data
                self._save_uncertainty_estimates(recon_group, recon_data)
                
                logger.info(f"Saved {n_snapshots} reconstruction snapshots with comprehensive data structure")
            else:
                recon_group.attrs['n_snapshots'] = 0
                logger.warning("No reconstruction data available to save")
            
            # Save final configuration
            final_group = f.create_group('final_configuration')
            final_group.attrs['n_final_plates'] = len(results['final_configuration']['plates'])
            final_group.attrs['n_final_boundaries'] = len(results['final_configuration']['boundaries'])
        
        logger.info(f"Results saved to {filename}")

    # Comprehensive reconstruction data saving methods
    
    def _save_temporal_index(self, recon_group: h5py.Group, recon_data: List[Dict]) -> None:
        """Create optimized temporal index for efficient time-based queries"""
        times = np.array([snapshot['time'] for snapshot in recon_data])
        
        # Create temporal index group
        temporal_group = recon_group.create_group('temporal_index')
        temporal_group.create_dataset('times', data=times, compression='gzip', compression_opts=9)
        temporal_group.create_dataset('snapshot_indices', data=np.arange(len(times)), compression='gzip')
        
        # Create time-based lookup tables
        temporal_group.attrs['time_min'] = float(np.min(times))
        temporal_group.attrs['time_max'] = float(np.max(times))
        temporal_group.attrs['time_step_avg'] = float(np.mean(np.diff(times))) if len(times) > 1 else 0.0
        temporal_group.attrs['time_step_std'] = float(np.std(np.diff(times))) if len(times) > 1 else 0.0
        
        # Create binned temporal structure for fast queries
        n_bins = min(100, len(times))
        if n_bins > 1:
            time_bins = np.linspace(times[0], times[-1], n_bins)
            bin_indices = np.digitize(times, time_bins)
            temporal_group.create_dataset('time_bins', data=time_bins, compression='gzip')
            temporal_group.create_dataset('bin_indices', data=bin_indices, compression='gzip')
    
    def _save_plate_evolution_data(self, recon_group: h5py.Group, recon_data: List[Dict]) -> None:
        """Save comprehensive plate evolution data with efficient storage"""
        plates_group = recon_group.create_group('plates')
        
        # Extract all unique plate IDs across all snapshots
        all_plate_ids = set()
        for snapshot in recon_data:
            all_plate_ids.update(snapshot['plates'].keys())
        all_plate_ids = sorted(list(all_plate_ids))
        
        plates_group.attrs['plate_ids'] = all_plate_ids
        plates_group.attrs['n_unique_plates'] = len(all_plate_ids)
        
        # Create datasets for each plate property with optimized storage
        n_snapshots = len(recon_data)
        n_plates = len(all_plate_ids)
        
        # Initialize arrays for plate properties
        plate_properties = {
            'exists': np.zeros((n_snapshots, n_plates), dtype=bool),
            'area': np.full((n_snapshots, n_plates), np.nan, dtype=np.float32),
            'age': np.full((n_snapshots, n_plates), np.nan, dtype=np.float32),
            'thickness': np.full((n_snapshots, n_plates), np.nan, dtype=np.float32),
            'density': np.full((n_snapshots, n_plates), np.nan, dtype=np.float32),
            'velocity_x': np.full((n_snapshots, n_plates), np.nan, dtype=np.float32),
            'velocity_y': np.full((n_snapshots, n_plates), np.nan, dtype=np.float32),
            'angular_velocity_x': np.full((n_snapshots, n_plates), np.nan, dtype=np.float32),
            'angular_velocity_y': np.full((n_snapshots, n_plates), np.nan, dtype=np.float32),
            'angular_velocity_z': np.full((n_snapshots, n_plates), np.nan, dtype=np.float32),
            'continental_fraction': np.full((n_snapshots, n_plates), np.nan, dtype=np.float32),
            'surface_temperature': np.full((n_snapshots, n_plates), np.nan, dtype=np.float32),
            'basal_temperature': np.full((n_snapshots, n_plates), np.nan, dtype=np.float32)
        }
        
        # Fill arrays with data from snapshots
        plate_id_to_index = {pid: i for i, pid in enumerate(all_plate_ids)}
        
        for t_idx, snapshot in enumerate(recon_data):
            for plate_id, plate_data in snapshot['plates'].items():
                p_idx = plate_id_to_index[plate_id]
                plate_properties['exists'][t_idx, p_idx] = True
                
                # Fill property arrays
                for prop in ['area', 'age', 'thickness', 'density', 'continental_fraction', 
                           'surface_temperature', 'basal_temperature']:
                    if prop in plate_data:
                        plate_properties[prop][t_idx, p_idx] = plate_data[prop]
                
                # Handle velocity data
                if 'velocity' in plate_data and len(plate_data['velocity']) >= 2:
                    plate_properties['velocity_x'][t_idx, p_idx] = plate_data['velocity'][0]
                    plate_properties['velocity_y'][t_idx, p_idx] = plate_data['velocity'][1]
                
                # Handle angular velocity data
                if 'angular_velocity' in plate_data and len(plate_data['angular_velocity']) >= 3:
                    plate_properties['angular_velocity_x'][t_idx, p_idx] = plate_data['angular_velocity'][0]
                    plate_properties['angular_velocity_y'][t_idx, p_idx] = plate_data['angular_velocity'][1]
                    plate_properties['angular_velocity_z'][t_idx, p_idx] = plate_data['angular_velocity'][2]
        
        # Save datasets with compression
        for prop_name, data in plate_properties.items():
            dataset = plates_group.create_dataset(
                prop_name, data=data, 
                compression='gzip', compression_opts=9,
                chunks=True, shuffle=True
            )
            dataset.attrs['description'] = f'Temporal evolution of {prop_name} for all plates'
            
        # Save plate type information
        plate_types = []
        for snapshot in recon_data:
            snapshot_types = {}
            for plate_id, plate_data in snapshot['plates'].items():
                if 'plate_type' in plate_data:
                    snapshot_types[plate_id] = str(plate_data['plate_type'])
            plate_types.append(snapshot_types)
        
        # Store plate type as string arrays (since enum types are complex to store)
        plates_group.attrs['has_type_data'] = True
    
    def _save_boundary_evolution_data(self, recon_group: h5py.Group, recon_data: List[Dict]) -> None:
        """Save comprehensive boundary evolution with kinematic history"""
        boundaries_group = recon_group.create_group('boundaries')
        
        # Extract all unique boundary IDs
        all_boundary_ids = set()
        for snapshot in recon_data:
            all_boundary_ids.update(snapshot['boundaries'].keys())
        all_boundary_ids = sorted(list(all_boundary_ids))
        
        boundaries_group.attrs['boundary_ids'] = all_boundary_ids
        boundaries_group.attrs['n_unique_boundaries'] = len(all_boundary_ids)
        
        n_snapshots = len(recon_data)
        n_boundaries = len(all_boundary_ids)
        
        # Initialize boundary property arrays
        boundary_properties = {
            'exists': np.zeros((n_snapshots, n_boundaries), dtype=bool),
            'length': np.full((n_snapshots, n_boundaries), np.nan, dtype=np.float32),
            'spreading_rate': np.full((n_snapshots, n_boundaries), np.nan, dtype=np.float32),
            'convergence_rate': np.full((n_snapshots, n_boundaries), np.nan, dtype=np.float32),
            'transform_rate': np.full((n_snapshots, n_boundaries), np.nan, dtype=np.float32),
            'seismic_coupling': np.full((n_snapshots, n_boundaries), np.nan, dtype=np.float32),
            'plate1_id': np.full((n_snapshots, n_boundaries), -1, dtype=np.int32),
            'plate2_id': np.full((n_snapshots, n_boundaries), -1, dtype=np.int32)
        }
        
        boundary_id_to_index = {bid: i for i, bid in enumerate(all_boundary_ids)}
        
        # Fill boundary data
        for t_idx, snapshot in enumerate(recon_data):
            for boundary_id, boundary_data in snapshot['boundaries'].items():
                b_idx = boundary_id_to_index[boundary_id]
                boundary_properties['exists'][t_idx, b_idx] = True
                
                for prop in ['length', 'spreading_rate', 'convergence_rate', 
                           'transform_rate', 'seismic_coupling', 'plate1_id', 'plate2_id']:
                    if prop in boundary_data:
                        boundary_properties[prop][t_idx, b_idx] = boundary_data[prop]
        
        # Save boundary datasets
        for prop_name, data in boundary_properties.items():
            dataset = boundaries_group.create_dataset(
                prop_name, data=data,
                compression='gzip', compression_opts=9,
                chunks=True, shuffle=True
            )
            dataset.attrs['description'] = f'Temporal evolution of {prop_name} for all boundaries'
        
        # Save geometry data (more complex due to variable length arrays)
        self._save_boundary_geometry_data(boundaries_group, recon_data, boundary_id_to_index)
    
    def _save_boundary_geometry_data(self, boundaries_group: h5py.Group, recon_data: List[Dict], 
                                   boundary_id_to_index: Dict[int, int]) -> None:
        """Save variable-length boundary geometry data"""
        geometry_group = boundaries_group.create_group('geometry')
        
        # Create variable-length datasets for geometry coordinates
        for t_idx, snapshot in enumerate(recon_data):
            time_group = geometry_group.create_group(f'time_{t_idx:04d}')
            time_group.attrs['time'] = snapshot['time']
            
            for boundary_id, boundary_data in snapshot['boundaries'].items():
                if 'geometry' in boundary_data and boundary_data['geometry'] is not None:
                    geom_data = boundary_data['geometry']
                    if hasattr(geom_data, '__len__') and len(geom_data) > 0:
                        boundary_group = time_group.create_group(f'boundary_{boundary_id}')
                        boundary_group.create_dataset('coordinates', data=geom_data, compression='gzip')
                        boundary_group.attrs['n_points'] = len(geom_data)
    
    def _save_subduction_evolution_data(self, recon_group: h5py.Group, recon_data: List[Dict]) -> None:
        """Save comprehensive subduction zone dynamics"""
        subduction_group = recon_group.create_group('subduction_zones')
        
        # Extract subduction zone data
        all_zone_ids = set()
        for snapshot in recon_data:
            if 'subduction_zones' in snapshot and snapshot['subduction_zones']:
                all_zone_ids.update(snapshot['subduction_zones'].keys())
        
        if not all_zone_ids:
            subduction_group.attrs['n_zones'] = 0
            return
            
        all_zone_ids = sorted(list(all_zone_ids))
        subduction_group.attrs['zone_ids'] = all_zone_ids
        subduction_group.attrs['n_zones'] = len(all_zone_ids)
        
        # Save detailed subduction zone evolution
        for zone_id in all_zone_ids:
            zone_group = subduction_group.create_group(f'zone_{zone_id}')
            
            # Collect temporal data for this zone
            zone_times = []
            zone_data_list = []
            
            for snapshot in recon_data:
                if ('subduction_zones' in snapshot and 
                    snapshot['subduction_zones'] and 
                    zone_id in snapshot['subduction_zones']):
                    zone_times.append(snapshot['time'])
                    zone_data_list.append(snapshot['subduction_zones'][zone_id])
            
            if zone_times:
                zone_group.create_dataset('times', data=zone_times, compression='gzip')
                zone_group.attrs['n_snapshots'] = len(zone_times)
                
                # Save thermal evolution data
                self._save_subduction_thermal_data(zone_group, zone_data_list)
                
                # Save mechanical evolution data  
                self._save_subduction_mechanical_data(zone_group, zone_data_list)
    
    def _save_subduction_thermal_data(self, zone_group: h5py.Group, zone_data_list: List[Dict]) -> None:
        """Save thermal evolution data for subduction zone"""
        thermal_group = zone_group.create_group('thermal_evolution')
        
        # Extract thermal properties if available
        thermal_properties = ['temperature', 'heat_flux', 'thermal_diffusivity']
        
        for prop in thermal_properties:
            prop_data = []
            for zone_data in zone_data_list:
                if 'thermal' in zone_data and prop in zone_data['thermal']:
                    prop_data.append(zone_data['thermal'][prop])
                else:
                    prop_data.append(np.nan)
            
            if any(not np.isnan(x) for x in prop_data):
                thermal_group.create_dataset(prop, data=prop_data, compression='gzip')
    
    def _save_subduction_mechanical_data(self, zone_group: h5py.Group, zone_data_list: List[Dict]) -> None:
        """Save mechanical evolution data for subduction zone"""
        mechanical_group = zone_group.create_group('mechanical_evolution')
        
        # Extract mechanical properties
        mechanical_properties = ['stress', 'strain_rate', 'viscosity']
        
        for prop in mechanical_properties:
            prop_data = []
            for zone_data in zone_data_list:
                if 'mechanical' in zone_data and prop in zone_data['mechanical']:
                    prop_data.append(zone_data['mechanical'][prop])
                else:
                    prop_data.append(np.nan)
            
            if any(not np.isnan(x) for x in prop_data):
                mechanical_group.create_dataset(prop, data=prop_data, compression='gzip')
    
    def _save_continental_evolution_data(self, recon_group: h5py.Group, recon_data: List[Dict]) -> None:
        """Save continental assembly/breakup history"""
        continental_group = recon_group.create_group('continental_evolution')
        
        # Extract continental evolution events
        assembly_events = []
        breakup_events = []
        
        for snapshot in recon_data:
            if 'continental_evolution' in snapshot:
                cont_data = snapshot['continental_evolution']
                
                if 'assembly_events' in cont_data:
                    for event in cont_data['assembly_events']:
                        event_record = {
                            'time': snapshot['time'],
                            'event_type': 'assembly',
                            **event
                        }
                        assembly_events.append(event_record)
                
                if 'breakup_events' in cont_data:
                    for event in cont_data['breakup_events']:
                        event_record = {
                            'time': snapshot['time'],
                            'event_type': 'breakup',
                            **event
                        }
                        breakup_events.append(event_record)
        
        continental_group.attrs['n_assembly_events'] = len(assembly_events)
        continental_group.attrs['n_breakup_events'] = len(breakup_events)
        
        # Save event data if available
        if assembly_events:
            assembly_group = continental_group.create_group('assembly_events')
            self._save_continental_events(assembly_group, assembly_events)
        
        if breakup_events:
            breakup_group = continental_group.create_group('breakup_events')
            self._save_continental_events(breakup_group, breakup_events)
    
    def _save_continental_events(self, events_group: h5py.Group, events: List[Dict]) -> None:
        """Save continental assembly/breakup events"""
        if not events:
            return
            
        times = [event['time'] for event in events]
        events_group.create_dataset('times', data=times, compression='gzip')
        events_group.attrs['n_events'] = len(events)
    
    def _save_plume_interaction_data(self, recon_group: h5py.Group, recon_data: List[Dict]) -> None:
        """Save plume interaction history and surface expressions"""
        plume_group = recon_group.create_group('plume_interactions')
        
        # Extract plume interaction data
        all_plume_ids = set()
        for snapshot in recon_data:
            if 'plume_interactions' in snapshot and snapshot['plume_interactions']:
                all_plume_ids.update(snapshot['plume_interactions'].keys())
        
        if not all_plume_ids:
            plume_group.attrs['n_plumes'] = 0
            return
            
        all_plume_ids = sorted(list(all_plume_ids))
        plume_group.attrs['plume_ids'] = all_plume_ids
        plume_group.attrs['n_plumes'] = len(all_plume_ids)
        
        # Save individual plume histories
        for plume_id in all_plume_ids:
            plume_subgroup = plume_group.create_group(f'plume_{plume_id}')
            
            # Collect temporal data for this plume
            plume_times = []
            plume_data_list = []
            
            for snapshot in recon_data:
                if ('plume_interactions' in snapshot and 
                    snapshot['plume_interactions'] and 
                    plume_id in snapshot['plume_interactions']):
                    plume_times.append(snapshot['time'])
                    plume_data_list.append(snapshot['plume_interactions'][plume_id])
            
            if plume_times:
                plume_subgroup.create_dataset('times', data=plume_times, compression='gzip')
                plume_subgroup.attrs['n_snapshots'] = len(plume_times)
                
                # Save plume interaction details
                self._save_plume_interaction_details(plume_subgroup, plume_data_list)
    
    def _save_plume_interaction_details(self, plume_group: h5py.Group, plume_data_list: List[Dict]) -> None:
        """Save detailed plume interaction data"""
        # Extract interaction properties
        interaction_props = ['ascent_velocity', 'thermal_anomaly', 'buoyancy_flux']
        
        for prop in interaction_props:
            prop_data = []
            for plume_data in plume_data_list:
                if 'interaction' in plume_data and prop in plume_data['interaction']:
                    prop_data.append(plume_data['interaction'][prop])
                else:
                    prop_data.append(np.nan)
            
            if any(not np.isnan(x) for x in prop_data):
                plume_group.create_dataset(prop, data=prop_data, compression='gzip')
    
    def _save_force_balance_evolution(self, recon_group: h5py.Group, recon_data: List[Dict]) -> None:
        """Save force balance evolution with detailed analysis"""
        force_group = recon_group.create_group('force_balance')
        
        n_snapshots = len(recon_data)
        times = [snapshot['time'] for snapshot in recon_data]
        
        # Extract all force components
        force_components = set()
        for snapshot in recon_data:
            if 'force_balance' in snapshot and isinstance(snapshot['force_balance'], dict):
                force_components.update(snapshot['force_balance'].keys())
        
        force_components = sorted(list(force_components))
        force_group.attrs['force_components'] = force_components
        force_group.attrs['n_components'] = len(force_components)
        
        # Create datasets for each force component
        for component in force_components:
            if component == 'metadata':  # Skip metadata for now
                continue
                
            force_values = []
            for snapshot in recon_data:
                if ('force_balance' in snapshot and 
                    isinstance(snapshot['force_balance'], dict) and
                    component in snapshot['force_balance']):
                    force_values.append(snapshot['force_balance'][component])
                else:
                    force_values.append(np.nan)
            
            force_group.create_dataset(
                component, data=force_values,
                compression='gzip', compression_opts=9
            )
        
        force_group.create_dataset('times', data=times, compression='gzip')
    
