    def _fallback_navier_stokes_initialization(self, geometry: dict, zone: dict, 
                                             convergence_velocity: float) -> dict:
        """Fallback simplified Navier-Stokes initialization"""
        try:
            coords = geometry['coordinates']
            shape = coords['x'].shape
            
            # Simple potential flow
            phi = self._solve_potential_flow(geometry, zone, convergence_velocity)
            
            # Velocity from potential
            dy, dx = np.gradient(phi)
            vx_potential = dx
            vy_potential = -dy
            vz_potential = np.zeros_like(vx_potential)
            
            # Apply basic boundary conditions
            vx_potential = self._apply_velocity_bc(vx_potential, geometry, zone, 'x')
            vy_potential = self._apply_velocity_bc(vy_potential, geometry, zone, 'y')
            
            return {
                'velocity_field': {
                    'vx': vx_potential,
                    'vy': vy_potential,
                    'vz': vz_potential
                },
                'method': 'fallback',
                'confidence': 0.3
            }
            
        except Exception as e:
            logging.warning(f"Fallback initialization failed: {e}")
            return {
                'velocity_field': {
                    'vx': np.zeros((10, 10)),
                    'vy': np.zeros((10, 10)),
                    'vz': np.zeros((10, 10))
                },
                'method': 'fallback',
                'error': str(e)
            }

    def _solve_potential_flow(self, geometry: dict, zone: dict, convergence_velocity: float) -> np.ndarray:
        """Solve for velocity potential in complex geometry"""
        coords = geometry['coordinates']
        shape = coords['x'].shape
        
        # Setup Laplace equation for potential flow
        phi = np.zeros(shape)
        
        # Simple iterative solver for ∇²φ = 0
        max_iter = 1000
        tolerance = 1e-6
        
        for iteration in range(max_iter):
            phi_old = phi.copy()
            
            # Interior points - 5-point stencil
            phi[1:-1, 1:-1] = 0.25 * (
                phi[2:, 1:-1] + phi[:-2, 1:-1] + 
                phi[1:-1, 2:] + phi[1:-1, :-2]
            )
            
            # Boundary conditions for potential
            phi[0, :] = convergence_velocity * coords['y'][0, :]  # Top boundary
            phi[-1, :] = 0  # Bottom boundary
            phi[:, 0] = 0   # Left boundary  
            phi[:, -1] = convergence_velocity * coords['y'][:, -1]  # Right boundary
            
            # Check convergence
            residual = np.max(np.abs(phi - phi_old))
            if residual < tolerance:
                break
        
        return phi

    def _apply_velocity_bc(self, velocity: np.ndarray, geometry: dict, 
                          zone: dict, component: str) -> np.ndarray:
        """Apply boundary conditions to velocity components"""
        vel_bc = velocity.copy()
        
        convergence_rate = zone['convergence_rate'] * 1e-2 / (365.25 * 24 * 3600)
        
        if component == 'x':
            # Convergent flow at boundaries
            vel_bc[0, :] = convergence_rate * 0.5   # Top
            vel_bc[-1, :] = -convergence_rate * 0.5  # Bottom
            vel_bc[:, 0] = convergence_rate         # Left
            vel_bc[:, -1] = -convergence_rate       # Right
        elif component == 'y':
            # Perpendicular flow
            vel_bc[0, :] = 0      # No slip at top
            vel_bc[-1, :] = 0     # No slip at bottom
            vel_bc[:, 0] = convergence_rate * 0.3   # Shear at sides
            vel_bc[:, -1] = convergence_rate * 0.3
        
        return vel_bc

    def _calculate_buoyancy_forces(self, T: np.ndarray, P: np.ndarray, 
                                 density: np.ndarray, geometry: dict) -> dict:
        """Calculate buoyancy forces from temperature and density variations"""
        g = 9.81  # m/s²
        
        # Thermal expansion coefficient
        beta_T = 3e-4  # 1/K (typical for water/rock)
        
        # Reference temperature and density
        T_ref = np.mean(T)
        rho_ref = np.mean(density)
        
        # Thermal buoyancy
        thermal_buoyancy = -g * beta_T * rho_ref * (T - T_ref)
        
        # Compositional buoyancy (if available)
        if 'composition' in geometry:
            composition = geometry['composition']
            compositional_buoyancy = g * (density - rho_ref) / rho_ref
        else:
            compositional_buoyancy = np.zeros_like(thermal_buoyancy)
        
        # Total buoyancy force (per unit volume)
        total_buoyancy = thermal_buoyancy + compositional_buoyancy
        
        return {
            'total': total_buoyancy,
            'thermal': thermal_buoyancy,
            'compositional': compositional_buoyancy,
            'magnitude': np.abs(total_buoyancy)
        }

    def _calculate_coriolis_effects(self, velocity: dict, latitude: np.ndarray, 
                                  longitude: np.ndarray) -> dict:
        """Calculate Coriolis forces for rotating reference frame"""
        omega_earth = 7.2921159e-5  # rad/s
        
        # Coriolis parameter
        f = 2 * omega_earth * np.sin(np.radians(latitude))
        
        # Coriolis acceleration components
        coriolis_x = -f * velocity['vy']
        coriolis_y = f * velocity['vx']
        coriolis_z = np.zeros_like(coriolis_x)  # Vertical Coriolis negligible
        
        return {
            'ax': coriolis_x,
            'ay': coriolis_y,
            'az': coriolis_z,
            'parameter': f
        }

    def _calculate_tectonic_pressure_gradient(self, zone: dict, geometry: dict, 
                                            convergence_velocity: float) -> dict:
        """Calculate pressure gradients from tectonic forces"""
        coords = geometry['coordinates']
        
        # Tectonic stress scale
        stress_scale = zone.get('stress_magnitude', 1e8)  # Pa
        
        # Characteristic length scale
        L_char = np.max(coords['x']) - np.min(coords['x'])
        
        # Pressure gradient components
        dP_dx = np.full_like(coords['x'], stress_scale / L_char)
        dP_dy = np.full_like(coords['y'], stress_scale / L_char * 0.5)
        
        # Modify based on convergence geometry
        if zone.get('subduction_zone', False):
            # Higher pressure gradients in subduction zones
            dP_dx *= 2.0
            dP_dy *= 1.5
        
        return {
            'dP_dx': dP_dx,
            'dP_dy': dP_dy,
            'stress_scale': stress_scale
        }

    def _calculate_viscous_stress_tensor(self, velocity: dict, viscosity: np.ndarray, 
                                       geometry: dict) -> dict:
        """Calculate viscous stress tensor components"""
        coords = geometry['coordinates']
        
        # Velocity gradients
        dvx_dx, dvx_dy = np.gradient(velocity['vx'])
        dvy_dx, dvy_dy = np.gradient(velocity['vy'])
        dvz_dx, dvz_dy = np.gradient(velocity['vz'])
        
        # Strain rate tensor components
        exx = dvx_dx
        eyy = dvy_dy
        exy = 0.5 * (dvx_dy + dvy_dx)
        exz = 0.5 * dvz_dx
        eyz = 0.5 * dvz_dy
        
        # Viscous stress tensor (τ = 2μe)
        tau_xx = 2 * viscosity * exx
        tau_yy = 2 * viscosity * eyy
        tau_xy = 2 * viscosity * exy
        tau_xz = 2 * viscosity * exz
        tau_yz = 2 * viscosity * eyz
        
        return {
            'tau_xx': tau_xx,
            'tau_yy': tau_yy,
            'tau_xy': tau_xy,
            'tau_xz': tau_xz,
            'tau_yz': tau_yz,
            'strain_rate': {
                'exx': exx, 'eyy': eyy, 'exy': exy,
                'exz': exz, 'eyz': eyz
            }
        }

    def _solve_momentum_equations(self, velocity: dict, buoyancy: dict, coriolis: dict,
                                pressure_grad: dict, viscous_stress: dict, 
                                geometry: dict, fluid_props: dict) -> dict:
        """Solve momentum conservation equations"""
        coords = geometry['coordinates']
        dt = 1.0  # Time step for steady state
        density = fluid_props['density']
        
        # Current velocity
        vx, vy, vz = velocity['vx'], velocity['vy'], velocity['vz']
        
        # Momentum equation residuals
        # ρ(∂v/∂t + v·∇v) = -∇p + ∇·τ + ρg + ρf_coriolis
        
        # Convective terms (simplified)
        convective_x = vx * np.gradient(vx, axis=1) + vy * np.gradient(vx, axis=0)
        convective_y = vx * np.gradient(vy, axis=1) + vy * np.gradient(vy, axis=0)
        convective_z = np.zeros_like(convective_x)
        
        # Force balance per unit volume
        force_x = (-pressure_grad['dP_dx'] + 
                  np.gradient(viscous_stress['tau_xx'], axis=1) + 
                  np.gradient(viscous_stress['tau_xy'], axis=0) + 
                  density * coriolis['ax']) / density
        
        force_y = (-pressure_grad['dP_dy'] + 
                  np.gradient(viscous_stress['tau_xy'], axis=1) + 
                  np.gradient(viscous_stress['tau_yy'], axis=0) + 
                  density * coriolis['ay'] + buoyancy['total']) / density
        
        force_z = (buoyancy['total'] + 
                  density * coriolis['az']) / density
        
        # Update velocities (explicit time integration)
        vx_new = vx + dt * (force_x - convective_x)
        vy_new = vy + dt * (force_y - convective_y) 
        vz_new = vz + dt * (force_z - convective_z)
        
        return {
            'vx': vx_new,
            'vy': vy_new,
            'vz': vz_new
        }

    def _calculate_vorticity(self, velocity: dict, geometry: dict) -> np.ndarray:
        """Calculate vorticity field"""
        dvx_dy = np.gradient(velocity['vx'], axis=0)
        dvy_dx = np.gradient(velocity['vy'], axis=1)
        
        vorticity = dvy_dx - dvx_dy
        return vorticity

    def _calculate_strain_rate_tensor(self, velocity: dict, geometry: dict) -> dict:
        """Calculate strain rate tensor"""
        dvx_dx, dvx_dy = np.gradient(velocity['vx'])
        dvy_dx, dvy_dy = np.gradient(velocity['vy'])
        
        return {
            'exx': dvx_dx,
            'eyy': dvy_dy,
            'exy': 0.5 * (dvx_dy + dvy_dx),
            'magnitude': np.sqrt(dvx_dx**2 + dvy_dy**2 + (dvx_dy + dvy_dx)**2)
        }

    def _calculate_reynolds_number(self, velocity: dict, fluid_props: dict, geometry: dict) -> np.ndarray:
        """Calculate Reynolds number field"""
        coords = geometry['coordinates']
        characteristic_length = np.sqrt((coords['x'][-1, -1] - coords['x'][0, 0])**2 + 
                                      (coords['y'][-1, -1] - coords['y'][0, 0])**2)
        
        velocity_magnitude = np.sqrt(velocity['vx']**2 + velocity['vy']**2 + velocity['vz']**2)
        
        Re = (fluid_props['density'] * velocity_magnitude * characteristic_length / 
              fluid_props['dynamic_viscosity'])
        
        return Re

    def _initialize_turbulence_model(self, velocity: dict, reynolds_number: np.ndarray,
                                   fluid_props: dict, geometry: dict) -> dict:
        """Initialize k-ε turbulence model for high Reynolds number flow"""
        velocity_magnitude = np.sqrt(velocity['vx']**2 + velocity['vy']**2 + velocity['vz']**2)
        
        # Turbulence intensity (assume 5% for moderate turbulence)
        I_turb = 0.05
        
        # Turbulent kinetic energy
        k = 1.5 * (I_turb * velocity_magnitude)**2
        
        # Turbulent dissipation rate
        coords = geometry['coordinates']
        L_turb = 0.1 * np.sqrt((coords['x'][-1, -1] - coords['x'][0, 0])**2 + 
                              (coords['y'][-1, -1] - coords['y'][0, 0])**2)
        
        epsilon = 0.164 * k**(3/2) / L_turb
        
        # Turbulent viscosity
        C_mu = 0.09
        mu_turb = C_mu * fluid_props['density'] * k**2 / epsilon
        
        return {
            'k': k,
            'epsilon': epsilon,
            'mu_turbulent': mu_turb,
            'turbulence_intensity': I_turb
        }

    def _apply_turbulence_corrections(self, velocity: dict, turbulence_model: dict) -> dict:
        """Apply turbulence corrections to mean flow"""
        # Simple turbulence correction (mixing length model)
        k = turbulence_model['k']
        
        # Turbulent fluctuation magnitude
        u_prime = np.sqrt(2/3 * k)
        
        # Apply random turbulent fluctuations (simplified)
        np.random.seed(42)  # For reproducibility
        
        vx_corrected = velocity['vx'] + 0.1 * u_prime * np.random.randn(*velocity['vx'].shape)
        vy_corrected = velocity['vy'] + 0.1 * u_prime * np.random.randn(*velocity['vy'].shape)
        vz_corrected = velocity['vz'] + 0.05 * u_prime * np.random.randn(*velocity['vz'].shape)
        
        return {
            'vx': vx_corrected,
            'vy': vy_corrected,
            'vz': vz_corrected
        }

    def _enforce_mass_conservation(self, velocity: dict, density: np.ndarray, geometry: dict) -> dict:
        """Enforce mass conservation through velocity correction"""
        # Continuity equation: ∇·(ρv) = 0
        
        rho_vx = density * velocity['vx']
        rho_vy = density * velocity['vy']
        
        # Calculate divergence
        drho_vx_dx = np.gradient(rho_vx, axis=1)
        drho_vy_dy = np.gradient(rho_vy, axis=0)
        
        mass_residual = drho_vx_dx + drho_vy_dy
        
        # Correction to enforce conservation
        correction_factor = 0.5
        velocity_correction_x = -correction_factor * mass_residual / density
        velocity_correction_y = -correction_factor * mass_residual / density
        
        return {
            'vx': velocity['vx'] + velocity_correction_x,
            'vy': velocity['vy'] + velocity_correction_y,
            'vz': velocity['vz']  # Assume incompressible in z-direction
        }

    def _apply_boundary_conditions(self, velocity: dict, zone: dict, geometry: dict, 
                                 convergence_velocity: float) -> dict:
        """Apply comprehensive boundary conditions"""
        vx, vy, vz = velocity['vx'].copy(), velocity['vy'].copy(), velocity['vz'].copy()
        
        # Plate boundary conditions
        if zone.get('boundary_type') == 'convergent':
            # Convergent boundaries
            vx[0, :] = convergence_velocity
            vx[-1, :] = -convergence_velocity
            vy[:, 0] = 0  # No slip
            vy[:, -1] = 0
            
        elif zone.get('boundary_type') == 'divergent':
            # Divergent boundaries  
            vx[0, :] = -convergence_velocity * 0.5
            vx[-1, :] = convergence_velocity * 0.5
            vy[:, 0] = 0
            vy[:, -1] = 0
            
        elif zone.get('boundary_type') == 'transform':
            # Transform boundaries
            vx[0, :] = convergence_velocity
            vx[-1, :] = convergence_velocity
            vy[:, 0] = -convergence_velocity * 0.3
            vy[:, -1] = convergence_velocity * 0.3
        
        # Free surface at top
        vz[0, :] = 0
        
        return {'vx': vx, 'vy': vy, 'vz': vz}

    def _calculate_pressure_field(self, velocity: dict, fluid_props: dict, geometry: dict) -> np.ndarray:
        """Calculate pressure field from velocity using Poisson equation"""
        coords = geometry['coordinates']
        shape = coords['x'].shape
        
        # Pressure Poisson equation: ∇²p = -ρ∇·(v·∇v)
        # Simplified implementation
        
        dvx_dx, dvx_dy = np.gradient(velocity['vx'])
        dvy_dx, dvy_dy = np.gradient(velocity['vy'])
        
        # Source term
        source = -fluid_props['density'] * (
            velocity['vx'] * dvx_dx + velocity['vy'] * dvx_dy +
            velocity['vx'] * dvy_dx + velocity['vy'] * dvy_dy
        )
        
        # Solve Poisson equation (simplified 5-point stencil)
        pressure = np.zeros(shape)
        
        for _ in range(500):  # Iteration
            pressure[1:-1, 1:-1] = 0.25 * (
                pressure[2:, 1:-1] + pressure[:-2, 1:-1] + 
                pressure[1:-1, 2:] + pressure[1:-1, :-2] -
                source[1:-1, 1:-1]
            )
        
        return pressure

    def _calculate_mass_flux(self, velocity: dict, density: np.ndarray) -> dict:
        """Calculate mass flux components"""
        return {
            'flux_x': density * velocity['vx'],
            'flux_y': density * velocity['vy'],
            'flux_z': density * velocity['vz'],
            'magnitude': density * np.sqrt(velocity['vx']**2 + velocity['vy']**2 + velocity['vz']**2)
        }

    def _calculate_energy_flux(self, velocity: dict, temperature: np.ndarray, fluid_props: dict) -> dict:
        """Calculate energy flux components"""
        specific_enthalpy = fluid_props['specific_heat'] * temperature
        
        return {
            'enthalpy_flux_x': fluid_props['density'] * velocity['vx'] * specific_enthalpy,
            'enthalpy_flux_y': fluid_props['density'] * velocity['vy'] * specific_enthalpy,
            'enthalpy_flux_z': fluid_props['density'] * velocity['vz'] * specific_enthalpy,
            'total_energy_flux': fluid_props['density'] * specific_enthalpy * 
                               np.sqrt(velocity['vx']**2 + velocity['vy']**2 + velocity['vz']**2)
        }

    def _calculate_turbulence_intensity(self, velocity: dict) -> np.ndarray:
        """Calculate turbulence intensity field"""
        velocity_magnitude = np.sqrt(velocity['vx']**2 + velocity['vy']**2 + velocity['vz']**2)
        
        # Estimate turbulence intensity from velocity gradients
        dvx_dx, dvx_dy = np.gradient(velocity['vx'])
        dvy_dx, dvy_dy = np.gradient(velocity['vy'])
        
        velocity_gradient_magnitude = np.sqrt(dvx_dx**2 + dvx_dy**2 + dvy_dx**2 + dvy_dy**2)
        
        # Turbulence intensity as fraction of mean velocity
        turbulence_intensity = 0.16 * velocity_gradient_magnitude / (velocity_magnitude + 1e-10)
        
        return np.clip(turbulence_intensity, 0.01, 0.3)
    
    # Additional helper methods for comprehensive thermal modeling
    
    def _calculate_regional_thermal_variations(self, X: np.ndarray, Y: np.ndarray, Z: np.ndarray, 
                                             zone: dict, time: float) -> dict:
        """Calculate regional mantle temperature variations"""
        # Mantle plume effects
        plume_locations = zone.get('plume_locations', [])
        temperature_anomaly = np.zeros_like(X)
        
        for plume in plume_locations:
            # Distance from plume center
            distance = np.sqrt((X - plume['x'])**2 + (Y - plume['y'])**2 + (Z - plume['z'])**2)
            
            # Gaussian plume temperature anomaly
            plume_radius = plume.get('radius', 100000)  # 100 km
            plume_strength = plume.get('temperature_excess', 200)  # 200 K
            
            temperature_anomaly += plume_strength * np.exp(-(distance / plume_radius)**2)
        
        return {'temperature_anomaly': temperature_anomaly}
    
    def _calculate_temporal_thermal_evolution(self, Z: np.ndarray, time: float) -> dict:
        """Calculate temporal evolution of thermal structure"""
        # Secular cooling of the Earth
        cooling_rate = 50 / 1e9  # 50 K per Gyr
        temperature_change = -cooling_rate * time * np.ones_like(Z)
        
        return {'temperature_change': temperature_change}
    
    def _calculate_conductive_heat_flux(self, T: np.ndarray, k: np.ndarray, 
                                      X: np.ndarray, Y: np.ndarray, Z: np.ndarray) -> np.ndarray:
        """Calculate conductive heat flux using Fourier's law"""
        dT_dx, dT_dy, dT_dz = np.gradient(T)
        dx, dy, dz = np.gradient(X)[1], np.gradient(Y)[0], np.gradient(Z)[2]
        
        # Fourier's law: q = -k * grad(T)
        q_x = -k * dT_dx / dx
        q_y = -k * dT_dy / dy  
        q_z = -k * dT_dz / dz
        
        return np.sqrt(q_x**2 + q_y**2 + q_z**2)
    
    def _calculate_convective_heat_flux(self, T: np.ndarray, velocity: np.ndarray, 
                                      density: np.ndarray, heat_capacity: np.ndarray) -> np.ndarray:
        """Calculate convective heat flux"""
        # Convective heat flux: q_conv = rho * Cp * v * T
        v_magnitude = np.sqrt(velocity[:,:,:,0]**2 + velocity[:,:,:,1]**2 + velocity[:,:,:,2]**2)
        return density * heat_capacity * v_magnitude * T * 1e-6  # Scale factor
    
    def _calculate_radiative_heat_flux(self, T: np.ndarray, zone: dict) -> np.ndarray:
        """Calculate radiative heat flux"""
        stefan_boltzmann = 5.67e-8
        emissivity = zone.get('emissivity', 0.8)
        
        # Simplified radiative heat flux
        return emissivity * stefan_boltzmann * T**4 * 1e-12  # Scale factor
    
    def _calculate_advective_heat_flux(self, T: np.ndarray, velocity: np.ndarray,
                                     density: np.ndarray, heat_capacity: np.ndarray) -> np.ndarray:
        """Calculate advective heat transport"""
        # Advective heat transport: q_adv = rho * Cp * v * dT/dx
        dT_dx, dT_dy, dT_dz = np.gradient(T)
        
        # Dot product of velocity and temperature gradient
        advective_flux = (velocity[:,:,:,0] * dT_dx + 
                         velocity[:,:,:,1] * dT_dy + 
                         velocity[:,:,:,2] * dT_dz)
        
        return density * heat_capacity * advective_flux * 1e-6
    
    def _calculate_thermal_mechanical_coupling(self, T: np.ndarray, zone: dict, time: float) -> dict:
        """Calculate thermal-mechanical coupling effects"""
        # Thermal expansion effects
        alpha = zone.get('thermal_expansion', 3e-5)
        reference_temp = 298.15
        
        thermal_strain = alpha * (T - reference_temp)
        thermal_stress = zone.get('bulk_modulus', 100e9) * thermal_strain
        
        # Thermal flux from mechanical work
        strain_rate = zone.get('strain_rate_magnitude', np.zeros_like(T))
        mechanical_heating = thermal_stress * strain_rate
        
        return {
            'thermal_flux': mechanical_heating * 1e-9,  # Convert to manageable units
            'thermal_strain': thermal_strain,
            'thermal_stress': thermal_stress
        }
    
    def _apply_lateral_boundary_corrections(self, heat_flux: np.ndarray, 
                                          geometry: dict, zone: dict) -> np.ndarray:
        """Apply boundary corrections to lateral heat flux"""
        # Simple edge effects
        corrections = np.zeros_like(heat_flux)
        
        # Enhance flux near boundaries
        shape = heat_flux.shape
        edge_width = min(5, shape[0]//10)  # 5 cells or 10% of domain
        
        corrections[:edge_width, :, :] += 0.1 * heat_flux[:edge_width, :, :]
        corrections[-edge_width:, :, :] += 0.1 * heat_flux[-edge_width:, :, :]
        corrections[:, :edge_width, :] += 0.1 * heat_flux[:, :edge_width, :]
        corrections[:, -edge_width:, :] += 0.1 * heat_flux[:, -edge_width:, :]
        
        return corrections
    
    def _calculate_contact_mechanics(self, T: np.ndarray, P: np.ndarray, strain_rate: dict) -> dict:
        """Calculate contact mechanics at interfaces"""
        # Contact pressure and area
        contact_pressure = P * 0.1  # Fraction of total pressure
        contact_area = np.ones_like(T)  # Normalized contact area
        
        # Surface roughness effects
        roughness = 1e-6  # 1 micron typical
        contact_area *= (1 - 0.1 * roughness / 1e-6)
        
        return {
            'contact_pressure': contact_pressure,
            'contact_area': contact_area,
            'roughness': roughness * np.ones_like(T)
        }
    
    def _calculate_interface_phase_changes(self, T: np.ndarray, P: np.ndarray, time: float) -> dict:
        """Calculate phase changes at interfaces"""
        # Dehydration reactions
        dehydration_temp = 773.15  # 500°C typical
        dehydration_pressure = 1e9  # 1 GPa
        
        phase_change_mask = (T > dehydration_temp) & (P > dehydration_pressure)
        latent_heat = 400000 * phase_change_mask  # J/kg
        
        return {
            'phase_change_mask': phase_change_mask,
            'latent_heat': latent_heat,
            'dehydration_rate': 0.01 * phase_change_mask  # kg/m³/s
        }
    
    def _calculate_interface_fluid_flow(self, T: np.ndarray, P: np.ndarray, zone: dict) -> dict:
        """Calculate fluid flow at interfaces"""
        # Permeability and fluid properties
        permeability = zone.get('permeability', 1e-18 * np.ones_like(T))  # m²
        fluid_viscosity = zone.get('fluid_viscosity', 1e-3 * np.ones_like(T))  # Pa·s
        
        # Darcy flow
        pressure_gradient = np.gradient(P)
        darcy_velocity = permeability / fluid_viscosity * pressure_gradient[0]
        
        return {
            'permeability': permeability,
            'fluid_viscosity': fluid_viscosity,
            'darcy_velocity': darcy_velocity
        }
    
    def _calculate_interface_chemistry(self, T: np.ndarray, P: np.ndarray, time: float) -> dict:
        """Calculate chemical reactions at interfaces"""
        # Reaction rate constants
        activation_energy = 200000  # J/mol
        R = 8.314  # J/mol/K
        pre_exponential = 1e6
        
        reaction_rate = pre_exponential * np.exp(-activation_energy / (R * T))
        
        # Chemical heat generation
        reaction_enthalpy = -50000  # J/mol (exothermic)
        chemical_heating = reaction_rate * reaction_enthalpy
        
        return {
            'reaction_rate': reaction_rate,
            'chemical_heating': chemical_heating,
            'extent_of_reaction': np.minimum(1.0, reaction_rate * time)
        }
    
    def _calculate_dynamic_heat_transfer_coefficient(self, T: np.ndarray, contact_data: dict,
                                                   phase_change_data: dict, fluid_data: dict) -> np.ndarray:
        """Calculate dynamic heat transfer coefficient"""
        # Base heat transfer coefficient
        h_base = 1000 * np.ones_like(T)  # W/m²/K
        
        # Temperature dependence
        h_temp = h_base * (T / 1000)**0.25
        
        # Contact pressure effects
        h_contact = h_temp * (1 + 0.1 * contact_data['contact_pressure'] / 1e9)
        
        # Phase change enhancement
        h_phase = h_contact * (1 + 2 * phase_change_data['phase_change_mask'])
        
        # Fluid flow effects
        reynolds = fluid_data['darcy_velocity'] * 1000 / fluid_data['fluid_viscosity']
        nusselt = 0.023 * reynolds**0.8  # Simplified correlation
        h_final = h_phase * (1 + 0.01 * nusselt)
        
        return h_final
    
    def _calculate_contact_resistance(self, T: np.ndarray, P: np.ndarray, 
                                    contact_data: dict, phase_change_data: dict) -> np.ndarray:
        """Calculate contact thermal resistance"""
        # Base thermal resistance
        R_base = 1e-4 * np.ones_like(T)  # K·m²/W
        
        # Pressure dependence (resistance decreases with pressure)
        R_pressure = R_base / (1 + P / 1e9)
        
        # Temperature effects
        R_temp = R_pressure * (1 - 0.001 * (T - 298.15))
        
        # Contact area effects
        R_contact = R_temp / contact_data['contact_area']
        
        # Phase change effects (reduced resistance during phase changes)
        R_final = R_contact * (1 - 0.5 * phase_change_data['phase_change_mask'])
        
        return np.maximum(R_final, 1e-6)  # Minimum resistance
    
    def _calculate_interfacial_temperature(self, T: np.ndarray, h: np.ndarray, R: np.ndarray,
                                         phase_change_data: dict, chemical_data: dict) -> np.ndarray:
        """Calculate interfacial temperature with all effects"""
        # Heat balance at interface
        # T_interface = (T_hot + h*R*T_cold + latent_heat_flux) / (1 + h*R)
        
        T_interface = T.copy()
        
        # Add phase change effects
        latent_heat_flux = phase_change_data['latent_heat'] * phase_change_data['dehydration_rate']
        T_interface += latent_heat_flux / (1000 * h)  # Convert to temperature
        
        # Add chemical reaction effects  
        chemical_heat_flux = chemical_data['chemical_heating']
        T_interface += chemical_heat_flux / (1000 * h)
        
        return T_interface
    
    def _enforce_heat_flux_continuity(self, T_interface: np.ndarray, geometry: dict,
                                    phase_change_data: dict, chemical_data: dict) -> dict:
        """Enforce heat flux continuity at interfaces"""
        # Calculate heat flux from both sides
        T = geometry['thermal_properties']['temperature']
        k = geometry['thermal_properties'].get('thermal_conductivity', 3.0)
        
        # Heat flux continuity check
        dT_dz = np.gradient(T, axis=2)
        heat_flux = k * dT_dz
        
        # Check continuity (simplified)
        flux_jump = np.abs(np.diff(heat_flux, axis=2))
        continuity_satisfied = flux_jump < 0.1 * np.abs(heat_flux[:,:,:-1])
        
        # Corrections for discontinuities
        corrections = np.zeros_like(T)
        corrections[:,:,1:] = np.where(~continuity_satisfied, 
                                     0.5 * flux_jump, 0)
        
        return {
            'continuity_satisfied': continuity_satisfied,
            'corrections': corrections,
            'flux_jump': flux_jump
        }
    
    def _calculate_interface_evolution(self, time: float, T: np.ndarray, P: np.ndarray) -> dict:
        """Calculate dynamic interface evolution"""
        # Interface migration rate
        migration_rate = 1e-10 * T / 1000  # m/s
        
        # Accumulated interface displacement
        displacement = migration_rate * time
        
        # Interface stability analysis
        stability = P / 1e9 - T / 2000  # Simplified stability criterion
        
        return {
            'migration_rate': migration_rate,
            'displacement': displacement,
            'stability': stability
        }
    
    def _calculate_spectral_radiation_properties(self, T: np.ndarray, phases: dict) -> dict:
        """Calculate spectral radiation properties"""
        # Planck function parameters
        h = 6.626e-34  # Planck constant
        c = 3e8        # Speed of light
        k_b = 1.381e-23  # Boltzmann constant
        
        # Wavelength bands (micrometers)
        wavelengths = np.array([1, 2, 5, 10, 20, 50])
        
        # Calculate spectral emissive power
        spectral_power = np.zeros((*T.shape, len(wavelengths)))
        
        for i, wavelength in enumerate(wavelengths):
            lambda_m = wavelength * 1e-6  # Convert to meters
            
            # Planck function
            B_lambda = (2 * h * c**2 / lambda_m**5) / \
                      (np.exp(h * c / (lambda_m * k_b * T)) - 1)
            
            spectral_power[:,:,:,i] = B_lambda
        
        # Total emissive power (Stefan-Boltzmann)
        stefan_boltzmann = 5.67e-8
        total_emissive_power = stefan_boltzmann * T**4
        
        return {
            'spectral_power': spectral_power,
            'total_emissive_power': total_emissive_power,
            'wavelengths': wavelengths
        }
    
    def _calculate_multi_band_radiation(self, T: np.ndarray, spectral_data: dict) -> dict:
        """Calculate multi-band radiation transfer"""
        bands = ['near_infrared', 'thermal_infrared', 'far_infrared']
        band_ranges = [(1, 5), (5, 20), (20, 100)]  # micrometers
        
        band_radiation = {}
        for i, (band, (lambda_min, lambda_max)) in enumerate(zip(bands, band_ranges)):
            # Integrate over wavelength band
            band_power = np.mean(spectral_data['spectral_power'], axis=3)
            band_radiation[band] = band_power
        
        return band_radiation
    
    def _calculate_opacity_effects(self, T: np.ndarray, phases: dict) -> dict:
        """Calculate opacity and absorption effects"""
        # Mineral-specific absorption coefficients
        absorption_coeffs = {
            'olivine': 0.1, 'pyroxene': 0.15, 'garnet': 0.2,
            'quartz': 0.05, 'feldspar': 0.08
        }
        
        # Calculate effective absorption
        absorption = np.zeros_like(T)
        for phase, fraction in phases.items():
            if phase in absorption_coeffs and hasattr(fraction, 'shape'):
                absorption += fraction * absorption_coeffs[phase]
        
        # Opacity (inverse of mean free path)
        opacity = absorption * T / 1000  # Temperature dependence
        
        return {
            'absorption_coefficient': absorption,
            'opacity': opacity,
            'scattering_coefficient': 0.1 * absorption  # Simplified
        }
    
    def _calculate_view_factors(self, geometry: dict) -> dict:
        """Calculate view factors for radiation exchange"""
        shape = geometry['coordinates']['x'].shape
        
        # Simplified view factor calculation
        view_factors = {
            'surface_to_surface': 0.5 * np.ones(shape),
            'volume_to_surface': 0.3 * np.ones(shape),
            'volume_to_volume': 0.2 * np.ones(shape)
        }
        
        return view_factors
    
    def _calculate_net_radiation_transfer(self, T: np.ndarray, spectral_data: dict,
                                        radiation_bands: dict, opacity_data: dict,
                                        view_factors: dict) -> np.ndarray:
        """Calculate net radiation heat transfer"""
        # Simplified net radiation calculation
        stefan_boltzmann = 5.67e-8
        
        # Emitted radiation
        emitted = spectral_data['total_emissive_power']
        
        # Absorbed radiation (simplified)
        absorbed = 0.8 * emitted * opacity_data['absorption_coefficient']
        
        # Net radiation
        net_radiation = emitted - absorbed
        
        # Apply view factor corrections
        net_radiation *= view_factors['volume_to_volume']
        
        return net_radiation
    
    def _calculate_radiation_pressure(self, T: np.ndarray, spectral_data: dict) -> np.ndarray:
        """Calculate radiation pressure effects"""
        # Radiation pressure: P_rad = (4/3) * sigma * T^4 / c
        stefan_boltzmann = 5.67e-8
        c = 3e8
        
        radiation_pressure = (4/3) * stefan_boltzmann * T**4 / c
        
        return radiation_pressure

    def _calculate_upper_boundary_layer_temp(self, depth_km: float, surface_temp: float) -> float:
        """Calculate temperature in upper thermal boundary layer (lithosphere)"""
        # Conductive geotherm with exponential heat source decay
        thermal_diffusivity = 1e-6  # m²/s
        heat_production = 2e-6  # W/m³ (radiogenic heating)
        thermal_conductivity = 3.0  # W/m/K
        
        # Exponential decay scale for heat production
        decay_scale = 10.0  # km
        
        # Temperature increase due to conduction and heat production
        depth_m = depth_km * 1000
        temp_gradient = 25.0 / 1000  # K/m (typical lithospheric gradient)
        
        # Add exponential heat source contribution
        heat_contrib = (heat_production * decay_scale * 1000 * 
                       (1 - np.exp(-depth_km / decay_scale)) / thermal_conductivity)
        
        return surface_temp + depth_m * temp_gradient + heat_contrib
    
    def _calculate_adiabatic_temperature(self, depth_km: float, surface_temp: float, region: str) -> float:
        """Calculate adiabatic temperature in convecting mantle regions"""
        # Thermodynamic properties vary with region
        if region == 'upper_mantle':
            # Olivine-dominated upper mantle
            cp = 1200.0  # J/kg/K (heat capacity)
            alpha = 3e-5  # 1/K (thermal expansion)
            density = 3300.0  # kg/m³
        else:  # lower_mantle
            # Perovskite-dominated lower mantle
            cp = 1100.0  # J/kg/K
            alpha = 2e-5  # 1/K
            density = 4500.0  # kg/m³
        
        # Gravitational acceleration (depth dependent)
        g = 9.81 * (1 - depth_km / 6371.0)  # Approximate variation
        
        # Adiabatic gradient: dT/dz = (αTg)/(ρcp)
        reference_depth = 100.0 if region == 'upper_mantle' else 660.0
        reference_temp = surface_temp + 100.0 if region == 'upper_mantle' else surface_temp + 800.0
        
        # Integrate adiabatic gradient
        depth_diff = (depth_km - reference_depth) * 1000  # Convert to meters
        adiabatic_gradient = (alpha * reference_temp * g) / (density * cp)
        
        # Add pressure-dependent corrections
        pressure_effect = self._calculate_pressure_temperature_coupling(depth_km, region)
        
        return reference_temp + adiabatic_gradient * depth_diff + pressure_effect
    
    def _calculate_transition_zone_temperature(self, depth_km: float, surface_temp: float) -> float:
        """Calculate temperature in upper transition zone (410-520 km)"""
        # 410 km discontinuity: olivine → wadsleyite transition
        transition_depth = 410.0
        base_temp = self._calculate_adiabatic_temperature(transition_depth, surface_temp, 'upper_mantle')
        
        # Phase transition effects on temperature
        clapeyron_slope = 4.0e6  # Pa/K (positive for olivine-wadsleyite)
        latent_heat = 400.0  # J/mol
        molar_volume_change = -1.5e-6  # m³/mol
        
        # Temperature jump due to phase transition
        depth_excess = depth_km - transition_depth
        pressure_change = depth_excess * 1000 * 3400 * 9.81  # Pa
        
        # Clausius-Clapeyron relation
        temp_jump = (latent_heat / molar_volume_change) * (pressure_change / clapeyron_slope)
        
        # Continued adiabatic gradient in wadsleyite stability field
        adiabatic_temp = self._calculate_adiabatic_temperature(depth_km, surface_temp, 'upper_mantle')
        
        return base_temp + temp_jump + (adiabatic_temp - base_temp) * 0.8  # Reduced gradient
    
    def _calculate_lower_transition_temperature(self, depth_km: float, surface_temp: float) -> float:
        """Calculate temperature in lower transition zone (520-660 km)"""
        # Multiple phase transitions in this region
        # 520 km: wadsleyite → ringwoodite
        # 660 km: ringwoodite → perovskite + ferropericlase
        
        base_temp = self._calculate_transition_zone_temperature(520.0, surface_temp)
        
        if depth_km < 660:
            # Ringwoodite stability field
            gradient = 0.6e-3  # K/m (reduced due to phase assemblage)
            depth_diff = (depth_km - 520.0) * 1000
            return base_temp + gradient * depth_diff
        else:
            # 660 km discontinuity effect
            clapeyron_slope = -2.5e6  # Pa/K (negative for post-spinel transition)
            latent_heat = 800.0  # J/mol
            molar_volume_change = -2.2e-6  # m³/mol
            
            depth_excess = depth_km - 660.0
            pressure_change = depth_excess * 1000 * 3700 * 9.81
            
            temp_jump = (latent_heat / molar_volume_change) * (pressure_change / clapeyron_slope)
            temp_660 = base_temp + 0.6e-3 * (660.0 - 520.0) * 1000
            
            return temp_660 + temp_jump
    
    def _calculate_lower_boundary_layer_temp(self, depth_km: float, cmb_temp: float) -> float:
        """Calculate temperature in D'' layer (lower thermal boundary layer)"""
        # Complex thermal structure near core-mantle boundary
        d_prime_top = 2700.0  # km
        cmb_depth = 2890.0   # km
        
        if depth_km < d_prime_top:
            # Lower mantle adiabat
            return self._calculate_adiabatic_temperature(depth_km, 1600.0, 'lower_mantle')
        
        # D'' layer thermal structure
        layer_thickness = cmb_depth - d_prime_top  # km
        depth_in_layer = depth_km - d_prime_top
        
        # Base temperature at top of D''
        d_prime_base_temp = self._calculate_adiabatic_temperature(d_prime_top, 1600.0, 'lower_mantle')
        
        # Non-linear temperature profile in D''
        # Accounts for thermal conductivity variations and phase transitions
        thermal_conductivity_ratio = 2.5  # Enhanced conductivity in D''
        normalized_depth = depth_in_layer / layer_thickness
        
        # Temperature profile with post-perovskite transition effects
        if normalized_depth > 0.7:  # Post-perovskite stability field
            post_pv_effect = 100.0 * (normalized_depth - 0.7) / 0.3  # K
        else:
            post_pv_effect = 0.0
        
        # Exponential approach to CMB temperature
        temp_diff = cmb_temp - d_prime_base_temp - post_pv_effect
        exp_profile = 1 - np.exp(-3 * normalized_depth)
        
        return d_prime_base_temp + temp_diff * exp_profile + post_pv_effect
    
    def _calculate_pressure_temperature_coupling(self, depth_km: float, region: str) -> float:
        """Calculate pressure-dependent temperature corrections"""
        depth_m = depth_km * 1000
        
        if region == 'upper_mantle':
            # Anharmonic effects in olivine
            pressure = depth_m * 3300 * 9.81  # Pa
            gruneisen_parameter = 1.2
            bulk_modulus = 128e9  # Pa
            
            # Temperature correction due to anharmonicity
            temp_correction = gruneisen_parameter * pressure / (3300 * 1200)  # K
            
        else:  # lower_mantle
            # Pressure effects in perovskite and ferropericlase
            pressure = depth_m * 4500 * 9.81  # Pa
            gruneisen_parameter = 1.5
            bulk_modulus = 250e9  # Pa
            
            # Include electronic transitions in iron
            electronic_transition_depth = 1800.0  # km
            if depth_km > electronic_transition_depth:
                electronic_effect = 50.0 * (depth_km - electronic_transition_depth) / 1000.0
            else:
                electronic_effect = 0.0
            
            temp_correction = (gruneisen_parameter * pressure / (4500 * 1100) + 
                             electronic_effect)  # K
        
        return temp_correction

